// Snake activation: y = x + sin(a*x)^2 * inv_b. Used by the optimize_graph reorder
// pass so it keeps the chain contiguous and by the dispatcher to detect the fusion.
// [TAG_CONV_INPUT_SPLIT] the qwen4exp GDN conv: concat(state, x^T) -> ssm_conv -> silu (graph_optimize keeps it whole)
static constexpr std::initializer_list<ggml_op> concat_conv_silu_pattern   { GGML_OP_CONCAT,   GGML_OP_SSM_CONV,
                                                                             GGML_OP_UNARY };

static constexpr std::initializer_list<ggml_op> snake_pattern              { GGML_OP_MUL,      GGML_OP_SIN,
                                                                             GGML_OP_SQR,      GGML_OP_MUL,
                                                                             GGML_OP_ADD };

// qwen4exp hyper-connection combine: out = residual + repeat(block) * (s2 * sigmoid(s1 * inject)).
// Emitted by build_hc_combine as
//   REPEAT(reshape(block)) SCALE(inject,1/hc) UNARY(SIGMOID) SCALE(.,2) RESHAPE MUL ADD
// (the graph builder pre-expands the inject projection so the seven nodes stay consecutive).
static constexpr std::initializer_list<ggml_op> hc_combine_pattern         { GGML_OP_REPEAT,  GGML_OP_SCALE,
                                                                             GGML_OP_UNARY,   GGML_OP_SCALE,
                                                                             GGML_OP_RESHAPE, GGML_OP_MUL,
                                                                             GGML_OP_ADD };

static constexpr std::initializer_list<std::array<int, 3>> hc_combine_edges {
    { 2, 0, 1 }, // sigmoid->src[0] == scale(inject)
    { 3, 0, 2 }, // scale2->src[0]  == sigmoid
    { 4, 0, 3 }, // reshape->src[0] == scale2
    { 5, 0, 0 }, // mul->src[0]     == repeat
    { 5, 1, 4 }, // mul->src[1]     == reshape
    { 6, 1, 5 }, // add->src[1]     == mul
};

// qwen4 QSA indexer: gather per-block scores to cells + add f16 mask (cast+reshape) + top-k,
// fused into one radix-select. The cast/reshape are elided; the raw f16 mask is read in-shader.
static constexpr std::initializer_list<ggml_op> topk_qsa_pattern { GGML_OP_GET_ROWS, GGML_OP_PERMUTE,
                                                                   GGML_OP_CONT,     GGML_OP_CPY,
                                                                   GGML_OP_RESHAPE,  GGML_OP_ADD,
                                                                   GGML_OP_TOP_K };
static constexpr std::initializer_list<std::array<int, 3>> topk_qsa_edges {
    { 1, 0, 0 }, // permute->src[0] == get_rows
    { 2, 0, 1 }, // cont->src[0]    == permute
    { 4, 0, 3 }, // reshape->src[0] == cpy (mask cast)
    { 5, 0, 2 }, // add->src[0]     == cont
    { 5, 1, 4 }, // add->src[1]     == reshape
    { 6, 0, 5 }, // top_k->src[0]   == add
};

