struct vk_device_struct {
    std::recursive_mutex mutex;
    mutable std::shared_mutex pinned_memory_mutex;

    // Guards compile_pending, all_pipelines, and the dynamic pipeline maps
    // (flash_attn, fa_mask_opt, solve_tri, conv2d, etc). The actual compile
    // runs with no lock held, so different pipelines can compile in parallel.
    // Lock order is device->mutex -> compile_mutex, never the reverse.
    std::mutex compile_mutex;
    std::condition_variable compile_cv;

    vk::PhysicalDevice physical_device;
    vk::PhysicalDeviceProperties properties;
    std::string name;
    uint64_t max_memory_allocation_size;
    uint64_t max_buffer_size;
    uint64_t suballocation_block_size;
    uint64_t min_imported_host_pointer_alignment;
    bool external_memory_host {};
    bool fp16;
    bool bf16;
    bool pipeline_robustness;
    bool memory_priority;
    vk::Device device;
    uint32_t vendor_id;
    vk::DriverId driver_id;
    vk_device_architecture architecture;
    std::unique_ptr<vk_queue> compute_queue;
    std::unique_ptr<vk_queue> transfer_queue;
    bool single_queue;
    bool support_async;
    bool async_use_transfer_queue;
    bool has_internally_synchronized_queues = false;
    uint32_t subgroup_size;
    uint32_t subgroup_size_log2;
    uint32_t shader_core_count;
    bool uma;
    bool prefer_host_memory;
    bool float_controls_rte_fp16;
    bool float_controls_denorm_preserve_fp16;
    bool subgroup_basic;
    bool subgroup_arithmetic;
    bool subgroup_shuffle;
    bool subgroup_ballot;
    bool subgroup_clustered;
    bool subgroup_vote;
    bool multi_add;
    bool shader_int64;
    bool buffer_device_address;
    bool vulkan_memory_model;

    bool add_rms_fusion;
    uint32_t partials_binding_alignment;
    uint32_t max_nodes_per_submit;

    bool shader_64b_indexing;

    bool integer_dot_product;
    // 0: default, 1: force mmvq, -1: disable mmvq
    int32_t mmvq_mode;

    bool subgroup_size_control;
    uint32_t subgroup_min_size;
    uint32_t subgroup_max_size;
    bool subgroup_require_full_support;

    // floor(log2(maxComputeWorkGroupInvocations))
    uint32_t max_workgroup_size_log2 {};

    bool coopmat_support;
    bool coopmat_acc_f32_support {};
    bool coopmat_acc_f16_support {};
    bool coopmat_bf16_support {};
    bool coopmat_support_16x16x16_f16acc {};
    bool coopmat_support_16x16x16_f32acc {};
    bool coopmat1_fa_support {};
    uint32_t coopmat_m;
    uint32_t coopmat_n;
    uint32_t coopmat_k;

    bool coopmat_int_support;
    uint32_t coopmat_int_m;
    uint32_t coopmat_int_n;
    uint32_t coopmat_int_k;
    // int8 coopmat1 MMQ (upstream #27952, mul_mmq_cm1.comp): coopmat1 + int8 coopmat + RDNA3/RDNA4. The fork's
    // A/B switch GGML_VK_DISABLE_MMQ_CM1=1 clears it -> no q8_1 pipelines on coopmat1 = the pre-port path.
    bool mmq_cm1 = false;
    // [TAG_MMQ_INT8_KNOBS] diagnostic restrictions of that path (GGML_VK_MMQ_INT8_MIN_N / GGML_VK_MMQ_INT8_OPS,
    // ggml-vulkan-mmq-knobs.h); the defaults leave it unrestricted.
    uint32_t mmq_int8_min_n = 0;
    uint32_t mmq_int8_ops = GGML_VK_MMQ_INT8_OPS_ALL;
    // [TAG_QSA_TOPK_V2] QSA selection kernel: false = v1 (topk_radix_select.comp, one workgroup per row),
    // true = v2 (topk_radix_select_v2.comp, tiles x 256 invocations, subgroup size qsa_topk_wave).
    // Byte-identical outputs; GGML_VK_QSA_TOPK=v1|v2 (default v2), GGML_VK_QSA_TOPK_WAVE=32|64 (default 64 where
    // supported, else 32), GGML_VK_QSA_TOPK_CPT=4|8|16 (diagnostic, default 8).
    bool qsa_topk_v2 = false;
    // [TAG_QSA_TOPK_NOKEYS] GGML_VK_QSA_TOPK_NOKEYS (default on; v2 only): the metadata variant's cell form without the key
    // rows (A3); GGML_VK_QSA_TOPK_NOKEYS_CHECK=1: flag out-of-domain scores (subnormal / NaN / +inf) of visible cells
    bool qsa_topk_nokeys = false;
    bool qsa_topk_nokeys_check = false;
    vk_buffer qsa_topk_nk_flag;   // the CHECK word (host-visible, 16 B), created at the first NOKEYS dispatch
    bool qsa_topk_nk_warned = false;
    uint32_t qsa_topk_wave = 0;
    uint32_t qsa_topk_cpt = 8;   // cells per invocation per tile: tile = 256 * qsa_topk_cpt cells

    bool coopmat2;
    bool coopmat2_bf16_support {};
    bool coopmat2_decode_vector;

    bool dot2_f16 {};
    bool ocp_fp4 {};

    bool pipeline_executable_properties_support {};

    bool device_fault {};
    PFN_vkGetDeviceFaultInfoEXT pfn_vkGetDeviceFaultInfoEXT {};

    bool serialize_submissions {};

    const ggml_cgraph * diag_cgraph {};
    int diag_prev_start = -1;
    int diag_prev_end = -1;

    size_t idx;

    bool mul_mat_l[GGML_TYPE_COUNT];
    bool mul_mat_m[GGML_TYPE_COUNT];
    bool mul_mat_s[GGML_TYPE_COUNT];
    bool mul_mat_id_l[GGML_TYPE_COUNT];
    bool mul_mat_id_m[GGML_TYPE_COUNT];
    bool mul_mat_id_s[GGML_TYPE_COUNT];

    // Separate flags for the q8_1 (integer dot) mmq path, whose shader uses
    // a different shared-memory layout than the float matmul shaders.
    bool mul_mat_l_int[GGML_TYPE_COUNT];
    bool mul_mat_m_int[GGML_TYPE_COUNT];
    bool mul_mat_s_int[GGML_TYPE_COUNT];
    bool mul_mat_id_l_int[GGML_TYPE_COUNT];
    bool mul_mat_id_m_int[GGML_TYPE_COUNT];
    bool mul_mat_id_s_int[GGML_TYPE_COUNT];

    vk::DescriptorSetLayout dsl;

    vk_matmul_pipeline pipeline_matmul_f32 {};
    // [TAG_QSA_POOL_REMAP] GGML_OP_MUL_MAT_ROWS: pipeline_matmul_f32's twins with A's rows named by a row-id buffer
    // (same SPIR-V defines + A_ROW_IDS, same spec constants / tiles / alignment); empty on coopmat2 devices
    vk_matmul_pipeline pipeline_matmul_f32_rows {};
    // [TAG_QSA_SCORE_EPILOGUE] GGML_OP_QSA_SCORE: pipeline_matmul_f32's / pipeline_matmul_f32_rows's twins with the indexer
    // score epilogue (ReLU, ordered head sum, bias) in the store; coopmat1 devices only (empty elsewhere)
    vk_matmul_pipeline pipeline_matmul_f32_qsa {};
    vk_matmul_pipeline pipeline_matmul_f32_rows_qsa {};
    // [TAG_QSA_POOLED_F16_MIRROR] the row-id QSA twin reading an f16 A (the pooled store's f16 mirror)
    vk_matmul_pipeline pipeline_matmul_f16_f32_rows_qsa {};
    // [TAG_QSA_SCORE_KREUSE] the three QSA twins above with the pooled keys reused across query tiles (workgroups numbered
    // M tile major, so the N tiles of one key tile run back to back); same slots / tiles / spec constants / push constants;
    // empty when GGML_VK_QSA_SCORE_KREUSE=0
    vk_matmul_pipeline pipeline_matmul_f32_qsa_kr {};
    vk_matmul_pipeline pipeline_matmul_f32_rows_qsa_kr {};
    vk_matmul_pipeline pipeline_matmul_f16_f32_rows_qsa_kr {};
    vk_matmul_pipeline pipeline_matmul_f32_f16 {};
    vk_matmul_pipeline pipeline_matmul_bf16 {};
    vk_matmul_pipeline2 pipeline_matmul_f16;
    vk_matmul_pipeline2 pipeline_matmul_f16_f32;

    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat[GGML_TYPE_COUNT];
    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat_f16[GGML_TYPE_COUNT];
    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat_q8_1[GGML_TYPE_COUNT];

    vk_matmul_pipeline pipeline_matmul_id_f32 {};
    vk_matmul_pipeline pipeline_matmul_id_bf16 {};
    vk_matmul_pipeline2 pipeline_matmul_id_f16;
    vk_matmul_pipeline2 pipeline_matmul_id_f16_f32;

    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat_id[GGML_TYPE_COUNT];
    // [TAG_MMID_PRECAST_B] the same coopmat1 mul_mat_id shaders with an f16 B (the activations pre-cast once per src1)
    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat_id_f16b[GGML_TYPE_COUNT];
    // [TAG_INJECT_TILE_M16] the dense quantized-A coopmat1 matmul shaders with a BM 16 x BN 16 tile (one subgroup, one
    // coopmat fragment) for m <= 16: the qwen4exp hc inject GEMM (m = 4). Only s / a_s are created (mul_mat_t16_s).
    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat_t16[GGML_TYPE_COUNT];
    bool mul_mat_t16_l[GGML_TYPE_COUNT];
    bool mul_mat_t16_m[GGML_TYPE_COUNT];
    bool mul_mat_t16_s[GGML_TYPE_COUNT];
    // [TAG_DENSE_TILE_B2] the dense quantized-A coopmat1 matmul shaders with the B2 tile set: l = BM 128 x BN 256 (xl),
    // m = BM 64 x BN 128 (hc); s never created. Availability per type (shmem, classified types) in mul_mat_b2_l (xl) /
    // mul_mat_b2_m (hc).
    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat_b2[GGML_TYPE_COUNT];
    bool mul_mat_b2_l[GGML_TYPE_COUNT];
    bool mul_mat_b2_m[GGML_TYPE_COUNT];
    bool mul_mat_b2_s[GGML_TYPE_COUNT];
    vk_matmul_pipeline2 pipeline_dequant_mul_mat_mat_id_q8_1[GGML_TYPE_COUNT];

    vk_pipeline pipeline_matmul_split_k_reduce;
    vk_pipeline pipeline_quantize_q8_1_x4;

    vk_pipeline pipeline_dequant[GGML_TYPE_COUNT];
    vk_pipeline pipeline_dequant_transpose[GGML_TYPE_COUNT]; // fused dequant+transpose for FA quant-KV
    vk_pipeline pipeline_dequant_mul_mat_vec_f32_f32[DMMV_WG_SIZE_COUNT][GGML_TYPE_COUNT][mul_mat_vec_max_cols];
    // [TAG_MMVQ_HOIST] C1: the hoisted-weight twins for NUM_COLS >= 2 (index = cols - 1; [0] never created): f32 x f32 and the
    // q8_1 MMVQ of q4_0 / q5_0 / q8_0 / q4_K. GGML_VK_MMVQ_HOIST=0 keeps the pipelines above.
    vk_pipeline pipeline_dequant_mul_mat_vec_f32_f32_hoist[DMMV_WG_SIZE_COUNT][mul_mat_vec_max_cols];
    vk_pipeline pipeline_dequant_mul_mat_vec_q8_1_f32_hoist[DMMV_WG_SIZE_COUNT][GGML_TYPE_COUNT][mul_mat_vec_max_cols];
    bool mmvq_hoist;
    uint32_t mmvq_hoist_min_cols;   // GGML_VK_MMVQ_HOIST_MIN_COLS (default 2, 2..8)
    // [TAG_QSA_POOL_REMAP] the twins of pipeline_dequant_mul_mat_vec_f32_f32[w][GGML_TYPE_F32][i] for GGML_OP_MUL_MAT_ROWS
    vk_pipeline pipeline_dequant_mul_mat_vec_rows_f32_f32[DMMV_WG_SIZE_COUNT][mul_mat_vec_max_cols];
    vk_pipeline pipeline_dequant_mul_mat_vec_f16_f32[DMMV_WG_SIZE_COUNT][GGML_TYPE_COUNT][mul_mat_vec_max_cols];
    vk_pipeline pipeline_dequant_mul_mat_vec_id_f32[DMMV_WG_SIZE_COUNT][GGML_TYPE_COUNT];

    vk_pipeline pipeline_dequant_mul_mat_vec_q8_1_f32[DMMV_WG_SIZE_COUNT][GGML_TYPE_COUNT][mul_mat_vec_max_cols];
    vk_pipeline pipeline_dequant_mul_mat_vec_id_q8_1_f32[DMMV_WG_SIZE_COUNT][GGML_TYPE_COUNT];

    vk_pipeline pipeline_mul_mat_vec_p021_f16_f32[p021_max_gqa_ratio];
    vk_pipeline pipeline_mul_mat_vec_nc_f16_f32;
    vk_pipeline pipeline_get_rows[GGML_TYPE_COUNT];
    vk_pipeline pipeline_get_rows_f32[GGML_TYPE_COUNT];
    vk_pipeline pipeline_get_rows_back_f32;
    vk_pipeline pipeline_acc_f32;
    vk_pipeline pipeline_set_f32;

    // [src0 0=fp32,1=fp16][src1 0=fp32,1=fp16][dst 0=fp32,1=fp16]
    vk_pipeline pipeline_add[2][2][2];
    vk_pipeline pipeline_add_norepeat[2][2][2];
    vk_pipeline pipeline_sub[2][2][2];
    vk_pipeline pipeline_sub_norepeat[2][2][2];
    vk_pipeline pipeline_mul[2][2][2];
    vk_pipeline pipeline_mul_norepeat[2][2][2];
    // fused UNARY(SIGMOID) + MUL, f32 only; index is norepeat
    vk_pipeline pipeline_mul_sigmoid_f32[2];
    vk_pipeline pipeline_div[2][2][2];
    vk_pipeline pipeline_div_norepeat[2][2][2];
    vk_pipeline pipeline_add_rms[2][2][2];
    vk_pipeline pipeline_add_rms_norepeat[2][2][2];

    // indexed by num_additional_fused_ops == num_adds - 1
    vk_pipeline pipeline_multi_add[MAX_FUSED_ADDS];
    vk_pipeline pipeline_multi_add_rms[MAX_FUSED_ADDS];
    // [TAG_HC_MIX_TAIL] ADD+ADD(+ADD...)+SCALE, indexed like pipeline_multi_add (number of adds - 1)
    vk_pipeline pipeline_multi_add_scale[MAX_FUSED_ADDS];

    vk_pipeline pipeline_add_id_f32;

    vk_pipeline pipeline_concat_i8, pipeline_concat_i16, pipeline_concat_i32, pipeline_concat_i64;
    vk_pipeline pipeline_upscale_nearest_f32, pipeline_upscale_bilinear_f32, pipeline_upscale_bicubic_f32, pipeline_upscale_bilinear_antialias_f32;
    vk_pipeline pipeline_scale_f32;
    // [TAG_HC_MIX_TAIL] SCALE + UNARY(SILU)
    vk_pipeline pipeline_scale_silu_f32;
    vk_pipeline pipeline_log[2];
    vk_pipeline pipeline_tri[2];
    vk_pipeline pipeline_diag[2];
    vk_pipeline pipeline_clamp[2];
    vk_pipeline pipeline_pad_f32;
    vk_pipeline pipeline_pad_reflect_1d_f32;
    vk_pipeline pipeline_roll_f32;
    vk_pipeline pipeline_repeat_i32, pipeline_repeat_back_f32;
    vk_pipeline pipeline_repeat_i16;
    vk_pipeline pipeline_cpy_f32_f32, pipeline_cpy_f32_f16, pipeline_cpy_f16_f16, pipeline_cpy_f16_f32, pipeline_cpy_f32_bf16, pipeline_cpy_bf16_f32, pipeline_cpy_f32_i32, pipeline_cpy_i32_f32;
    vk_pipeline pipeline_contig_cpy_f32_f32, pipeline_contig_cpy_f32_f16, pipeline_contig_cpy_f16_f16, pipeline_contig_cpy_f16_f32, pipeline_contig_cpy_f32_bf16, pipeline_contig_cpy_bf16_f32, pipeline_contig_cpy_f32_i32, pipeline_contig_cpy_i32_f32;
    vk_pipeline pipeline_cpy_f32_quant[GGML_TYPE_COUNT];
    vk_pipeline pipeline_cpy_quant_f32[GGML_TYPE_COUNT];
    vk_pipeline pipeline_cpy_transpose_16, pipeline_cpy_transpose_32;
    vk_pipeline pipeline_cpy_transpose_02_16, pipeline_cpy_transpose_02_32;
    // [src0 0=fp32,1=fp16][dst]
    vk_pipeline pipeline_set_rows_i32[2][GGML_TYPE_COUNT];
    vk_pipeline pipeline_set_rows_i64[2][GGML_TYPE_COUNT];
    vk_pipeline pipeline_norm_f32;
    vk_pipeline pipeline_group_norm_f32;
    vk_pipeline pipeline_rms_norm_f32;
    vk_pipeline pipeline_rms_norm_mul_f32;
    vk_pipeline pipeline_rms_norm_partials_f32;
    vk_pipeline pipeline_rms_norm_mul_partials_f32;
    vk_pipeline pipeline_rms_norm_mul_rope_f32_f32;
    vk_pipeline pipeline_rms_norm_mul_rope_f32_f16;
    vk_pipeline pipeline_rms_norm_back_f32;
    vk_pipeline pipeline_l2_norm_f32;

    // [src/dst 0=fp32,1=fp16]
    vk_pipeline pipeline_exp[2];
    vk_pipeline pipeline_expm1[2];
    vk_pipeline pipeline_elu[2];
    vk_pipeline pipeline_gelu[2];
    vk_pipeline pipeline_gelu_erf[2];
    vk_pipeline pipeline_gelu_quick[2];
    vk_pipeline pipeline_silu[2];
    vk_pipeline pipeline_relu[2];
    vk_pipeline pipeline_sqr[2];
    vk_pipeline pipeline_sqrt[2];
    vk_pipeline pipeline_sin[2];
    vk_pipeline pipeline_cos[2];
    vk_pipeline pipeline_xielu[2];
    vk_pipeline pipeline_neg[2];
    vk_pipeline pipeline_tanh[2];
    vk_pipeline pipeline_sigmoid[2];
    vk_pipeline pipeline_hardsigmoid[2];
    vk_pipeline pipeline_hardswish[2];
    vk_pipeline pipeline_abs[2];
    vk_pipeline pipeline_softplus[2];
    vk_pipeline pipeline_step[2];
    vk_pipeline pipeline_round[2];
    vk_pipeline pipeline_ceil[2];
    vk_pipeline pipeline_floor[2];
    vk_pipeline pipeline_trunc[2];
    vk_pipeline pipeline_sgn[2];

    vk_pipeline pipeline_add1_f16_f16;
    vk_pipeline pipeline_add1_f16_f32;
    vk_pipeline pipeline_add1_f32_f32;

    vk_pipeline pipeline_arange_f32;

    vk_pipeline pipeline_fill_f32;
    vk_pipeline pipeline_fill_f16;

    vk_pipeline pipeline_geglu[2];
    vk_pipeline pipeline_reglu[2];
    vk_pipeline pipeline_swiglu[2];
    vk_pipeline pipeline_swiglu_oai[2];
    vk_pipeline pipeline_geglu_erf[2];
    vk_pipeline pipeline_geglu_quick[2];

    vk_pipeline pipeline_leaky_relu[2];
    vk_pipeline pipeline_silu_back_f32;
    vk_pipeline pipeline_diag_mask_inf_f32;
    vk_pipeline pipeline_soft_max_f32, pipeline_soft_max_f32_f16;
    vk_pipeline pipeline_soft_max_f32_wg512, pipeline_soft_max_f32_f16_wg512;
    vk_pipeline pipeline_soft_max_back_f32;

    vk_pipeline pipeline_soft_max_large1_f32, pipeline_soft_max_large1_f32_f16;
    vk_pipeline pipeline_soft_max_large2_f32, pipeline_soft_max_large2_f32_f16;
    vk_pipeline pipeline_soft_max_large3_f32, pipeline_soft_max_large3_f32_f16;

    vk_pipeline pipeline_rope_norm_f32, pipeline_rope_norm_f16, pipeline_rope_norm_f32_f16;
    vk_pipeline pipeline_rope_neox_f32, pipeline_rope_neox_f16, pipeline_rope_neox_f32_f16;
    vk_pipeline pipeline_rope_multi_f32, pipeline_rope_multi_f16, pipeline_rope_multi_f32_f16;
    vk_pipeline pipeline_rope_vision_f32, pipeline_rope_vision_f16;
    vk_pipeline pipeline_argsort_f32[num_argsort_pipelines];
    vk_pipeline pipeline_argsort_large_f32[num_argsort_pipelines];
    vk_pipeline pipeline_topk_f32[num_topk_pipelines];
    vk_pipeline pipeline_topk_radix_f32;
    vk_pipeline pipeline_topk_radix_qsa; // qwen4 QSA indexer fusion (f16 mask)
    vk_pipeline pipeline_topk_radix_qsa_blocks; // [TAG_QSA_WHOLE_BLOCKS] ggml_qsa_top_k_blocks (f16 mask)
    // [TAG_QSA_TOPK_V2] the distributed radix select (topk_radix_select_v2.comp): one pipeline per pass
    // (0..3 histogram rounds, 4 count, 5 emit). Created only when qsa_topk_v2 (GGML_VK_QSA_TOPK, device init).
    vk_pipeline pipeline_topk_v2_qsa[6];
    // [TAG_QSA_TOPK_V2] [TAG_QSA_WHOLE_BLOCKS] the same shader in the block-level form (spec constant 3 = 1): passes
    // 0..4 over the block keys, 5 flag, 6 cell count, 7 cell emit
    vk_pipeline pipeline_topk_v2_qsa_blocks[8];
    // [TAG_QSA_VIS] (A4 T3) the same selections over the visibility metadata (ggml_qsa_top_k_vis): the QSA_VIS SPIR-V
    // variants of both kernels, binding 3 = the cell planes, binding 5 = the token records (6 bindings)
    vk_pipeline pipeline_topk_radix_qsa_vis, pipeline_topk_radix_qsa_blocks_vis;
    vk_pipeline pipeline_topk_v2_qsa_vis[6];
    vk_pipeline pipeline_topk_v2_qsa_blocks_vis[8];
    // [TAG_QSA_TOPK_NOKEYS] the metadata variant's cell form without the key rows (binding 6 = the CHECK word)
    vk_pipeline pipeline_topk_v2_qsa_vis_nk[6];
    vk_pipeline pipeline_qsa_bias;       // [TAG_QSA_COMPACT_BIAS] GGML_OP_QSA_BIAS
    vk_pipeline pipeline_sum_rows_f32;
    vk_pipeline pipeline_cross_entropy_loss_f32, pipeline_cross_entropy_loss_f32_wg512;
    vk_pipeline pipeline_cross_entropy_loss_back_f32, pipeline_cross_entropy_loss_back_f32_wg512;
    vk_pipeline pipeline_fwht_f32[4];
    vk_pipeline pipeline_cumsum_f32;
    vk_pipeline pipeline_cumsum_small_f32;
    vk_pipeline pipeline_cumsum_multipass1_f32;
    vk_pipeline pipeline_cumsum_multipass2_f32;
    vk_pipeline pipeline_argmax_f32;
    vk_pipeline pipeline_count_equal_i32;
    std::map<vk_solve_tri_pipeline_state, vk_pipeline> pipeline_solve_tri_f32;
    vk_pipeline pipeline_im2col_f32, pipeline_im2col_f32_f16;
    vk_pipeline pipeline_im2col_3d_f32, pipeline_im2col_3d_f32_f16;
    vk_pipeline pipeline_timestep_embedding_f32;
    vk_pipeline pipeline_conv_transpose_1d_f32;
    vk_pipeline pipeline_col2im_1d_f32;
    vk_pipeline pipeline_col2im_1d_f16;
    vk_pipeline pipeline_col2im_1d_bf16;
    vk_pipeline pipeline_out_prod_f32;
    vk_pipeline pipeline_hc_combine_f32;
    vk_pipeline pipeline_add_softplus_mul_f32;
    vk_pipeline pipeline_snake_f32;
    vk_pipeline pipeline_snake_f16;
    vk_pipeline pipeline_snake_bf16;
    vk_pipeline pipeline_pool1d_f32;
    vk_pipeline pipeline_pool2d_f32;
    vk_pipeline pipeline_rwkv_wkv6_f32;
    vk_pipeline pipeline_rwkv_wkv7_f32;
    vk_pipeline pipeline_gated_linear_attn_f32;
    vk_pipeline pipeline_lightning_indexer_f32[GGML_TYPE_COUNT];
    // [size_idx][kda] where size_idx: 0=d16, 1=d32, 2=d64, 3=d128
    vk_pipeline pipeline_gated_delta_net[4][2];
    vk_pipeline pipeline_ssm_scan_f32_d128;
    vk_pipeline pipeline_ssm_scan_f32_d256;
    vk_pipeline pipeline_ssm_conv_f32;
    vk_pipeline pipeline_ssm_conv_silu_f32;
    vk_pipeline pipeline_ssm_conv_bias_silu_f32;
    // [TAG_CONV_INPUT_SPLIT] CONCAT(state, x) + SSM_CONV (+ SILU / + ADD + SILU), by the number of fused ops after the conv
    vk_pipeline pipeline_ssm_conv_split_f32[3];
    vk_pipeline pipeline_opt_step_adamw_f32;
    vk_pipeline pipeline_opt_step_sgd_f32;
    std::map<vk_conv2d_pipeline_state, vk_pipeline> pipeline_conv2d_f32[CONV_SHAPE_COUNT];
    std::map<vk_conv2d_pipeline_state, vk_pipeline> pipeline_conv2d_f16_f32[CONV_SHAPE_COUNT];
    std::map<vk_conv2d_pipeline_state, vk_pipeline> pipeline_conv_transpose_2d_f32[CONV_SHAPE_COUNT];
    std::map<vk_conv2d_pipeline_state, vk_pipeline> pipeline_conv_transpose_2d_f16_f32[CONV_SHAPE_COUNT];
    std::map<vk_conv3d_pipeline_state, vk_pipeline> pipeline_conv3d_f32[CONV_SHAPE_COUNT];
    std::map<vk_conv3d_pipeline_state, vk_pipeline> pipeline_conv3d_f16_f32[CONV_SHAPE_COUNT];
    vk_pipeline pipeline_conv2d_dw_whcn_f32, pipeline_conv2d_dw_whcn_f16_f32;
    vk_pipeline pipeline_conv2d_dw_cwhn_f32, pipeline_conv2d_dw_cwhn_f16_f32;

    std::map<vk_fa_pipeline_state, vk_pipeline> pipeline_flash_attn_f32_f16;

    std::map<std::pair<uint32_t, uint32_t>, vk_pipeline> pipeline_fa_mask_opt;
    // [TAG_KQ_VIS] the same classification from the visibility metadata, and GGML_OP_KQ_MASK
    std::map<std::pair<uint32_t, uint32_t>, vk_pipeline> pipeline_fa_vis_opt;
    vk_pipeline pipeline_kq_mask_f16, pipeline_kq_mask_f32;
    vk_pipeline pipeline_kq_mask_ids_f16; // [TAG_QSA_VIS] ggml_kq_mask_ids (the QSA gather's window mask)

    vk_pipeline pipeline_flash_attn_split_k_reduce;
    vk_pipeline pipeline_count_experts;        // N_EXPERTS_MAX = BLOCK_SIZE, counting only
    vk_pipeline pipeline_count_experts_hoist;   // N_EXPERTS_MAX = vk_count_experts_max_experts

    // [2] is for whether to take n_experts from spec constant (0) or push constant (1)
    vk_pipeline pipeline_topk_moe[num_topk_moe_pipelines][2];

    std::vector<vk_pipeline_ref> all_pipelines;

    std::vector<std::tuple<void*, size_t, vk_buffer>> pinned_memory;

    vk::Fence fence;
    vk_buffer sync_staging;

    ggml_backend_buffer_type buffer_type;

    bool disable_fusion;
    // [TAG_UP29280] GGML_VK_DISABLE_DESCRIPTOR_REUSE: always rewrite descriptor sets (the pre-#29280 behaviour)
    bool disable_descriptor_reuse;
    // [TAG_UP29280] bumped by every ~vk_buffer_struct before its VkBuffer is destroyed: a new buffer can get the
    // handle of a destroyed one, so the contexts drop their cached descriptor bindings when this moves
    std::atomic<uint64_t> buffer_destroy_count {};
    // per-fusion kill switches (all default on, GGML_VK_FUSE_<NAME>=0 turns one off)
    bool fuse_hc_combine;
    bool fuse_sigmoid_mul;
    bool fuse_gdn_pre;
    // [TAG_HC_MIX_TAIL] GGML_VK_FUSE_MULTI_ADD_SCALE / GGML_VK_FUSE_SCALE_SILU
    bool fuse_multi_add_scale;
    bool fuse_scale_silu;
    // [TAG_CONV_INPUT_SPLIT] GGML_VK_FUSE_CONCAT_SSM_CONV
    bool fuse_concat_ssm_conv;
    // [TAG_VK_DISPATCH_LOG] GGML_VK_DISPATCH_LOG=1: one [vk-dispatch] line per MUL_MAT / MUL_MAT_VEC / MUL_MAT_ID dispatch
    bool dispatch_log;
    // [TAG_QSA_SCORE_KREUSE] GGML_VK_QSA_SCORE_KREUSE (default on; 0 = the A2a dispatch order); the kr dispatch's workgroup
    // count limit (maxComputeWorkGroupCount[0], or the smaller GGML_VK_QSA_SCORE_KREUSE_MAX_WG test hook)
    bool     qsa_score_kreuse;
    uint32_t qsa_score_kreuse_max_wg;
    // [TAG_MMID_PRECAST_B] GGML_VK_MMID_PRECAST_B (default on)
    bool mmid_precast_b;
    // split a dim-0 concat with a transposed src1 into copy + tiled transpose-copy
    // (default on, GGML_VK_CONCAT_TRANSPOSE=0 turns it off)
    bool concat_transpose;
    bool disable_host_visible_vidmem;
    bool allow_sysmem_fallback;
    bool disable_graph_optimize;

    std::unique_ptr<vk_memory_logger> memory_logger;

    ~vk_device_struct() {
        VK_LOG_DEBUG("destroy device " << name);

        device.destroyFence(fence);

        ggml_vk_destroy_buffer(sync_staging);

        if (compute_queue) compute_queue->cmd_pool.destroy(device);
        if (transfer_queue) transfer_queue->cmd_pool.destroy(device);

        // Explicitly clear to ensure queues drop their shared_ptrs to handles
        // before the Vulkan logical device instance is destroyed
        compute_queue.reset();
        transfer_queue.reset();

        for (auto& pipeline : all_pipelines) {
            if (pipeline.expired()) {
                continue;
            }

            vk_pipeline pl = pipeline.lock();
            ggml_vk_destroy_pipeline(device, pl);
        }
        all_pipelines.clear();

        device.destroyDescriptorSetLayout(dsl);

        device.destroy();
    }
};

void vk_command_pool::init(vk_device& device, vk_queue *q_) {
    cmd_buffers.clear();
    q = q_;

    vk::CommandPoolCreateInfo command_pool_create_info(
        vk::CommandPoolCreateFlags(VK_COMMAND_POOL_CREATE_TRANSIENT_BIT | VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT),
        q->queue_family_index);
    pool = device->device.createCommandPool(command_pool_create_info);
}

void vk_command_pool::destroy(vk::Device& device) {
    device.destroyCommandPool(pool);
    pool = nullptr;
    cmd_buffers.clear();
}

static void ggml_vk_print_device_fault_info(const vk_device& device) {
    if (!device->device_fault || !device->pfn_vkGetDeviceFaultInfoEXT) {
        return;
    }

    VkDeviceFaultCountsEXT fault_counts {};
    fault_counts.sType = VK_STRUCTURE_TYPE_DEVICE_FAULT_COUNTS_EXT;
    VkResult res = device->pfn_vkGetDeviceFaultInfoEXT(device->device, &fault_counts, nullptr);
    if (res != VK_SUCCESS) {
        GGML_LOG_ERROR("ggml_vulkan: vkGetDeviceFaultInfoEXT (counts) failed: %d\n", res);
        return;
    }

    std::vector<VkDeviceFaultAddressInfoEXT> address_infos(fault_counts.addressInfoCount);
    std::vector<VkDeviceFaultVendorInfoEXT> vendor_infos(fault_counts.vendorInfoCount);

    VkDeviceFaultInfoEXT fault_info {};
    fault_info.sType = VK_STRUCTURE_TYPE_DEVICE_FAULT_INFO_EXT;
    fault_info.pAddressInfos = address_infos.data();
    fault_info.pVendorInfos = vendor_infos.data();

    res = device->pfn_vkGetDeviceFaultInfoEXT(device->device, &fault_counts, &fault_info);
    if (res != VK_SUCCESS) {
        GGML_LOG_ERROR("ggml_vulkan: vkGetDeviceFaultInfoEXT (info) failed: %d\n", res);
        return;
    }

    if (fault_counts.addressInfoCount == 0 && fault_counts.vendorInfoCount == 0 && fault_info.description[0] == '\0') {
        return;
    }

    if (fault_info.description[0] != '\0') {
        GGML_LOG_ERROR("ggml_vulkan: device fault on %s: %s\n", device->name.c_str(), fault_info.description);
    }

    for (uint32_t i = 0; i < fault_counts.addressInfoCount; i++) {
        const auto& info = address_infos[i];
        GGML_LOG_CONT("  address fault %u: type=%d address=0x%llx precision=0x%llx\n",
                i, (int)info.addressType,
                (unsigned long long)info.reportedAddress,
                (unsigned long long)info.addressPrecision);
    }
    for (uint32_t i = 0; i < fault_counts.vendorInfoCount; i++) {
        const auto& info = vendor_infos[i];
        GGML_LOG_CONT("  vendor fault %u: %s (code=0x%llx data=0x%llx)\n",
                i, info.description,
                (unsigned long long)info.vendorFaultCode,
                (unsigned long long)info.vendorFaultData);
    }
}

// [TAG_VK_FREE_WAIT_IDLE] (M4.2b item 3) buffers of at least this size get timestamped alloc/free lines in the memory
// logger (GGML_VK_MEMORY_LOGGER) and, with GGML_VK_FREE_WAIT_IDLE=1, a queue wait before they are destroyed
static constexpr size_t vk_big_buffer_bytes = 256ull*1024*1024;
static int64_t ggml_vk_now_us();
static void    ggml_vk_log_free_memory_done(size_t size, int64_t t0_us);

struct vk_buffer_struct {
    vk::Buffer buffer = VK_NULL_HANDLE;
    vk::DeviceMemory device_memory = VK_NULL_HANDLE;
    vk::MemoryPropertyFlags memory_property_flags;
    void * ptr;
    size_t size = 0;
    vk::DeviceAddress bda_addr {};

    vk_device device;

    ~vk_buffer_struct() {
        if (size == 0) {
            return;
        }
        VK_LOG_DEBUG("~vk_buffer_struct(" << buffer << ", " << size << ")");

        const int64_t t0_us = size >= vk_big_buffer_bytes ? ggml_vk_now_us() : 0; // [TAG_VK_FREE_WAIT_IDLE]
        // [TAG_UP29280] bump before destroying, so a thread that sees the buffer gone also sees the new count
        device->buffer_destroy_count.fetch_add(1, std::memory_order_release);
        device->device.freeMemory(device_memory);
        device->device.destroyBuffer(buffer);
        if (t0_us != 0) {
            ggml_vk_log_free_memory_done(size, t0_us);
        }
    }
};

struct vk_subbuffer {
    vk_buffer buffer;
    uint64_t offset;
    uint64_t size;

    operator vk::DescriptorBufferInfo() const {
        return { buffer->buffer, offset, size };
    }
};

struct vk_semaphore {
    vk::Semaphore s;
    uint64_t value;
};

// vk_event is used for the event-related backend interfaces. It uses vk::Events for
// event_wait and a timeline semaphore for event_synchronize. Polling on an event for
// event_synchronize wouldn't be sufficient to wait for command buffers to complete,
// and would lead to validation errors.
struct vk_event {
    std::vector<vk::Event> events_free; // Events available for reuse
    std::vector<vk::Event> events_submitted; // Events that are fully submitted and can be reused on next synchronize
    vk::Event event;
    bool has_event;

    vk_semaphore tl_semaphore;
    vk_command_buffer* cmd_buffer = nullptr;
    uint64_t cmd_buffer_use_counter = 0;
};

struct vk_submission {
    vk_command_buffer* buffer = nullptr;
    std::vector<vk_semaphore> wait_semaphores;
    std::vector<vk_semaphore> signal_semaphores;
};

typedef std::vector<vk_submission> vk_sequence;

