static bool vk_memory_logger_enabled = false;

#define VK_LOG_MEMORY(msg) if (vk_memory_logger_enabled) { std::cerr << "ggml_vulkan memory: " << msg << std::endl; }

// [TAG_VK_FREE_WAIT_IDLE] wall-clock microseconds (the same clock as the docker log and the 1-s GTT sampler)
static int64_t ggml_vk_now_us() {
    return std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
}

// [TAG_VK_FREE_WAIT_IDLE] ~vk_buffer_struct of a big buffer: the moment vkFreeMemory returned. Paired with the
// "[vk-free] destroy" line of ggml_vk_destroy_buffer it shows whether the memory was released when the backend buffer
// was freed (refs=1: same microsecond) or later, when a retained reference dropped.
static void ggml_vk_log_free_memory_done(size_t size, int64_t t0_us) {
    if (!vk_memory_logger_enabled) {
        return;
    }
    const int64_t t1_us = ggml_vk_now_us();
    VK_LOG_MEMORY("[vk-free] freeMemory " << size << " B completed t_us=" << t1_us << " (vkFreeMemory took " << (t1_us - t0_us) << " us)");
}

// [TAG_VK_FREE_WAIT_IDLE] (M4.2b item 3) GGML_VK_FREE_WAIT_IDLE=1 (default off, a diagnostic): wait until the device's
// queues are idle before a buffer of >= 256 MiB is destroyed. If the 1-s GTT spikes at a compute-buffer regrow vanish
// with it, the old buffer's pages were held by in-flight command buffers; if they stay, it is driver/TTM reclamation
// or accounting lag, and only fewer regrows help (GGML_ALLOC_GROW_SLACK, LLAMA_RESERVE_RUNTIME_SHAPE).
static bool ggml_vk_free_wait_idle() {
    static const bool enabled = [] {
        const char * s = getenv("GGML_VK_FREE_WAIT_IDLE");
        return s != nullptr && atoi(s) != 0;
    }();
    return enabled;
}

static std::string format_size(size_t size) {
    const size_t kib = 1024;
    const size_t mib = kib * 1024;
    const size_t gib = mib * 1024;

    std::ostringstream oss;
    oss << std::fixed << std::setprecision(2);

    if (size >= gib) {
        oss << static_cast<double>(size) / gib << " GiB";
    } else if (size >= mib) {
        oss << static_cast<double>(size) / mib << " MiB";
    } else if (size >= kib) {
        oss << static_cast<double>(size) / kib << " KiB";
    } else {
        oss << size << " B";
    }

    return oss.str();
}

class vk_memory_logger {
public:
    vk_memory_logger(): total_device(0), total_host(0) {}
    void log_allocation(vk_buffer_ref buf_ref, size_t size);
    void log_deallocation(vk_buffer_ref buf_ref);

private:
    std::map<vk::Buffer, size_t> allocations; // Track allocations
    size_t total_device;
    size_t total_host;
    static std::mutex log_mutex;
};

std::mutex vk_memory_logger::log_mutex;

static bool vk_perf_logger_enabled = false;
static bool vk_perf_logger_concurrent = false;
static bool vk_enable_sync_logger = false;
// GGML_VK_FLOPS_SEED_LEGACY=1 restores the pre-fix behaviour of seeding the per-submit flop
// threshold from the *previous* graph_compute call (i.e. the previous scheduler split).
static bool vk_flops_seed_legacy = false;
// GGML_VK_SUBMIT_LOG=1 prints one line per graph_compute with the submit count and the seed.
static bool vk_submit_log_enabled = false;
// GGML_VK_OPT_WINDOW=<n> sets ggml_vk_graph_optimize's independence lookahead (default 20).
// Clamped to vk_graph_opt_window_max: the lookahead is only ever used as a bound on a node index,
// so anything at or above the largest graph is already "the whole graph", and letting it reach
// INT_MAX makes first_unused + window overflow.
static constexpr int vk_graph_opt_window_max = 1 << 20;
static int vk_graph_opt_window = 20;
// GGML_VK_ASYNC_READ_COPYBUF=1 keeps the async readback on the vkCmdCopyBuffer path even when the
// source buffer is host-visible UMA memory that the host could read directly.
static bool vk_async_read_copybuf = false;
// GGML_VK_ASYNC_READ_UMA=1 takes the direct-host-read shortcut even when the source memory type is
// not HOST_CACHED (i.e. possibly write-combined). For the A/B only - see the eHostCached note in
// ggml_vk_buffer_read_2d_async.
static bool vk_async_read_uma_force = false;
// [TAG_VK_BUF_LOG] GGML_VK_BUF_LOG=1: one "[vk-buf]" line per buffer allocation (kind, size, memory type, heap,
// VkMemoryPropertyFlags, wc = host-visible but not HOST_CACHED, i.e. write-combined for CPU reads). Diagnostic only.
static bool vk_buf_log_enabled = false;
static thread_local const char * vk_buf_log_kind = nullptr;
// number of calls between perf logger prints
static uint32_t vk_perf_logger_frequency = 1;
static std::string vk_pipeline_stats_filter;

// [TAG_ENV_BOOL] value-parsed boolean knob: absent (or empty) leaves the default, otherwise the
// value is parsed, so =0 means off and =1 means on. A presence test would make FOO=0 turn the
// feature *on*, which is a foot-gun for a benchmark matrix that sets every knob to 0 or 1.
// Only 0 and 1 are meaningful; any other integer reads as 1 and any non-numeric value as 0.
// Note that every caller below caches the result, so changing the environment later has no effect.
static bool ggml_vk_env_bool(const char * name, bool def) {
    const char * s = getenv(name);
    if (s == nullptr || *s == '\0') {
        return def;
    }
    return atoi(s) != 0;
}

// [TAG_MMID_TILE_B1] GGML_VK_MMID_TILE_BM128 (default on, =0 off): the coopmat1 mul_mat_id l tile = BM 128 x BN 64 on AMD
// RDNA (see ggml_vk_load_shaders). Read once (static).
static bool ggml_vk_mmid_tile_b1(const vk_device & device) {
    static const bool on = ggml_vk_env_bool("GGML_VK_MMID_TILE_BM128", true);
    return on && device->vendor_id == VK_VENDOR_ID_AMD && device->coopmat_support && !device->coopmat2 &&
           device->driver_id != vk::DriverId::eAmdProprietary;
}

// [TAG_INJECT_TILE_M16] GGML_VK_DENSE_TILE_M16 (default on, =0 off): the AMD coopmat1 dense quantized-A matmul with
// m <= 16 (the qwen4exp hc inject, m = 4, n = the ubatch, k = 4 x n_embd) runs a BM 16 x BN 16 tile instead of the
// s tile (BM 32 x BN 32): twice the workgroups along N at the same per-element accumulation (same shader, BK, TM / TN / TK
// coopmat fragments, K order). Types: q4_K (brain inject), q8_0 (balkon hands inject). Read once (static).
static bool ggml_vk_inject_tile_m16(const vk_device & device) {
    static const bool on = ggml_vk_env_bool("GGML_VK_DENSE_TILE_M16", true);
    return on && device->vendor_id == VK_VENDOR_ID_AMD && device->coopmat_support && !device->coopmat2 &&
           device->driver_id != vk::DriverId::eAmdProprietary;
}

// [TAG_MMID_TILE_B1] [TAG_MMID_PRECAST_B] the quantized expert types the B1 byte classifier covers (balkon 780M, vs a v59
// binary): q4_K (brain gate/up), q5_0 / q8_0 (brain down), q6_K, iq3_s (balkon hands experts). Both B1 changes apply to
// these only.
static bool ggml_vk_b1_classified_type(ggml_type t) {
    return t == GGML_TYPE_Q4_K || t == GGML_TYPE_Q5_0 || t == GGML_TYPE_Q8_0 || t == GGML_TYPE_Q6_K || t == GGML_TYPE_IQ3_S;
}

// [TAG_DENSE_TILE_B2] GGML_VK_DENSE_TILE_B2 (default OFF since run4, =1 on): the AMD coopmat1 dense quantized-A matmul B2 tiles
// (ggml_vk_mul_mat_q_f16): hc = BM 64 x BN 128 for m <= 384 (default on), and, only with GGML_VK_DENSE_TILE_B2_XL=1
// (default off: 10-20 % SLOWER on the 780M for the large shapes; for the gfx1151 screen arm), xl = BM 128 x BN 256 for
// m >= 2048. Both EXACT. Read once (static). Transfer note: on the 780M the hc gain is largest on 320 x 10240 at n 512-1024,
// but gfx1151 (more cores) runs that shape with split_k > 1 up to n 1024 (S0.3 S4 raw), where B2 does not apply - on gfx1151
// only the split_k == 1 widths (n >= ~2044) can gain. The production-graph byte check is pending the oracle gate.
static bool ggml_vk_dense_tile_b2(const vk_device & device) {
    // default OFF (ruling 2026-10-15, gfx1151 interim run4 per-op: the hc tile made q4_K 320 x 10240 at n 2048 137 -> 356 ms
    // and q6_K 49 -> 93 ms per ubatch; the 780M gain does not transfer). =1 enables it (A/B only).
    static const bool on = ggml_vk_env_bool("GGML_VK_DENSE_TILE_B2", false);
    return on && device->vendor_id == VK_VENDOR_ID_AMD && device->coopmat_support && !device->coopmat2 &&
           device->driver_id != vk::DriverId::eAmdProprietary;
}
static bool ggml_vk_dense_tile_b2_xl() {
    static const bool on = ggml_vk_env_bool("GGML_VK_DENSE_TILE_B2_XL", false);
    return on;
}

// GGML_VK_DISABLE_FUSION_PATTERNS=name1,name2,... disables individual graph-fusion patterns by
// name, so a fusion-caused divergence can be bisected pattern by pattern (GGML_VK_DISABLE_FUSION
// still turns every fusion off at once). Comma-separated, case-insensitive; a trailing '*' matches
// a prefix (topk_moe* = every topk_moe_* mode). Read once in ggml_vk_instance_init and cached:
// when the variable is unset every match site costs exactly one load of the cached bool
// vk_fusion_patterns_disabled_any and nothing else changes. Unknown names are warned about at
// startup. The names are the lower-case fusion_string of the match site in
// ggml_backend_vk_graph_compute; the sites are tried in this order, so disabling a longer pattern
// lets its shorter prefix match instead (no mul_mat_add_add -> mul_mat_add fires):
//   multi_add                        ADD+ADD(+ADD...)                     ggml_vk_fuse_multi_add
//   multi_add_scale                  the trailing SCALE appended to a multi_add (qwen4exp hc_mix stream mean and
//                                    the QSA pooled-key mean); nested in the multi_add match, so disabling
//                                    multi_add disables it too; disabling it leaves the plain multi_add + SCALE
//   mul_mat_add_add                  MUL_MAT+ADD+ADD                      (mat-vec bias adds)
//   mul_mat_add                      MUL_MAT+ADD
//   mul_mat_id_add_id_mul            MUL_MAT_ID+ADD_ID+MUL
//   mul_mat_id_add_id                MUL_MAT_ID+ADD_ID
//   mul_mat_id_mul                   MUL_MAT_ID+MUL                       (MoE expert-weight multiply)
//   rms_norm_mul_rope_view_set_rows  RMS_NORM+MUL+ROPE+VIEW+SET_ROWS
//   rms_norm_mul_rope                RMS_NORM+MUL+ROPE
//   rms_norm_mul                     RMS_NORM+MUL
//   concat_ssm_conv_bias_silu        CONCAT+SSM_CONV+ADD+SILU             (qwen4exp GDN conv input read from state | x,
//   concat_ssm_conv_silu             CONCAT+SSM_CONV+SILU                  the concat never written; prefill only - see
//   concat_ssm_conv                  CONCAT+SSM_CONV                       ggml_vk_can_fuse_concat_ssm_conv;
//                                                                          GGML_VK_FUSE_CONCAT_SSM_CONV=0 turns all three off)
//   ssm_conv_bias_silu               SSM_CONV+ADD+SILU
//   ssm_conv_silu                    SSM_CONV+SILU
//   rope_view_set_rows               ROPE+VIEW+SET_ROWS
//   hc_combine                       REPEAT+SCALE+SIGMOID+SCALE+RESHAPE+MUL+ADD   (qwen4exp hyper-connection combine)
//   snake                            MUL+SIN+SQR+MUL+ADD
//   topk_qsa                         GET_ROWS+PERMUTE+CONT+CPY+RESHAPE+ADD+TOP_K   (qwen4 QSA indexer selection)
//   topk_moe_early_softmax_norm      SOFT_MAX+RESHAPE+ARGSORT+VIEW+GET_ROWS+RESHAPE+SUM_ROWS+CLAMP+DIV+RESHAPE
//   topk_moe_sigmoid_norm_bias       SIGMOID+RESHAPE+ADD+ARGSORT+VIEW+GET_ROWS+RESHAPE+SUM_ROWS+CLAMP+DIV+RESHAPE
//   topk_moe_sqrt_softplus_norm_bias SOFTPLUS+SQRT+RESHAPE+ADD+ARGSORT+VIEW+GET_ROWS+RESHAPE+SUM_ROWS+CLAMP+DIV+RESHAPE
//   topk_moe_early_softmax           SOFT_MAX+RESHAPE+ARGSORT+VIEW+GET_ROWS
//   topk_moe_late_softmax            ARGSORT+VIEW+GET_ROWS+RESHAPE+SOFT_MAX+RESHAPE
//   topk_moe_scale                   the optional trailing DIV+RESHAPE+SCALE / GET_ROWS+SCALE appended to any topk_moe_*
//   add_softplus_mul                 ADD+SOFTPLUS+MUL                     (qwen4exp GDN decay pre-chain)
//   scale_silu                       SCALE+SILU                           (qwen4exp hc_mix down projection)
//   sigmoid_mul                      SIGMOID+MUL
//   add_rms                          ADD that also writes the sum-of-squares partials consumed by the RMS_NORM
//                                    right after it (ggml_vk_build_graph; decode only, rows == 1)
// ggml_vk_graph_optimize's keep_pattern list is deliberately not gated: it only keeps a pattern's
// nodes adjacent (GGML_VK_DISABLE_FUSION does not gate it either), so the node order of a run with
// a pattern disabled is the same as with the pattern enabled.
// [TAG_HC_MIX_TAIL] multi_add_scale and scale_silu add no graph_optimize carve-out (fix round 1: carve-outs
// moved independent nodes and cost the QSA pool mean its multi_add), so the node order is the v59 order with
// the knobs on or off (GGML_VK_FUSE_MULTI_ADD_SCALE=0 / GGML_VK_FUSE_SCALE_SILU=0, default on); the fusions
// fire wherever v59's order already has the pair adjacent.
// [TAG_CONV_INPUT_SPLIT] Exception: concat_ssm_conv_silu's keep_pattern (CONCAT -> SSM_CONV -> SILU, edges checked)
// and the guard that stops graph_optimize hoisting that CONCAT ARE gated, by GGML_VK_FUSE_CONCAT_SSM_CONV (default
// on; =0, or GGML_VK_DISABLE_FUSION, gives the v59 order), and they apply only where the conv is the concat's single
// use (the prefill shape; decode / short-verify graphs keep the v59 order). Without them the CONCAT is hoisted into an
// earlier set and the pattern never forms. Disabling the concat_ssm_conv* patterns by name keeps the knob-on order.
// Only the SILU form is protected: concat_ssm_conv and concat_ssm_conv_bias_silu fire only where the order happens to
// be adjacent (qwen4exp emits the SILU form). qwen4exp reads the same knob (qwen4exp_conv_input_split): =0 also
// restores its v59 graph (history tails viewing the concat, expanded before the conv).
//
// Port note vs the source commit: the gate is the *last* term of each match condition instead of
// the first, so a veto is only recorded for a pattern that really matched at this node and
// GGML_VK_FUSION_COUNT can report it as disabled:<name>=<count>. Every ggml_vk_can_fuse*/
// ggml_vk_fuse_multi_add predicate is side-effect free (none of them writes ctx->), so evaluating
// the predicate before the gate changes nothing but the cost of a run that sets the knob.
//
// [TAG_MMID_TILE_B1] GGML_VK_MMID_TILE_BM128 (default on; =0 off): on AMD coopmat1 the mul_mat_id l tile is BM 128 x BN 64
// (the m tile's warp structure with twice the warps along M), used when m > 64 and n > 64; per-element accumulation unchanged.
// [TAG_MMID_PRECAST_B] GGML_VK_MMID_PRECAST_B (default on; =0 off): coopmat1 quantized-A mul_mat_id converts the f32 B once
// to f16 (the y staging cpy, shared by gate / up) and runs the f16-B twin of the same shader instead of converting per tile.
// Staging cost: prealloc_y holds the f16 B - gate/up 2 560 x 2 048 = 10 MiB, the down projection 640 x 10 x 2 048 = 25 MiB at
// n = 2 048 (grows prealloc_y to the largest); the conversion pass itself reads 4 B and writes 2 B per B element (≈ 5 GB
// per 2 048 ubatch over 48 layers), so the pre-cast must show a net gain ALONE on gfx1151 (s1 gate) or ship the tile only.
// Scope (both): AMD coopmat1, the classified quantized types q4_K / q5_0 / q8_0 / q6_K / iq3_s (ggml_vk_b1_classified_type).
// The TILE knob is a process-wide static read on the first shader load, PRECAST a device field read at device init.
// The dispatch log names the f16-B / _l pipelines and adds a "path=mmid_precast ... reuse=0|1" line per staging cpy.
// Exactness of both: byte-identical on the balkon 780M classifier vs a v59 binary - b1-cases 90/90 (n 1..2048, uniform /
// skewed / hot), b1fix-cases (n 9/63/64/65, partial expert tiles) and b1fix2-cases (iq3_s, q6_K): see contrib 0231/0232 for
// the counts; the gfx1151 production-graph byte comparison, the gate/up staging reuse, repeated execution and the GTT effect
// are measured by the s1 gate.
//
// [TAG_VK_DISPATCH_LOG] GGML_VK_DISPATCH_LOG=1 (default off, read once at device init) prints one stderr line
// "[vk-dispatch] op=... path=mm|mmv|mmv_p021|mmv_nc|mmv_rows|mm_id|mmv_id src0= src1= m= n= k= batch= [n_as= n_used=]
// pipeline= split_k= mmvq= mmq= fused= node=" per MUL_MAT / MUL_MAT_ID / MUL_MAT_ROWS dispatch (mat-vec or matmul), from
// the decision point (see ggml_vk_dispatch_log); no barrier, no numeric effect.
//
// GGML_VK_FUSION_LIST=1 prints one stderr line "[vk-fusion] name: OP1+OP2+..." the first time
// each distinct (pattern name, fused op names) tuple fires - after the src/dst overlap veto, so
// only fusions that were really dispatched - so the fusion sets of two runs can be diffed.
static const char * const vk_fusion_pattern_names[] = {
    "multi_add", "mul_mat_add_add", "mul_mat_add", "mul_mat_id_add_id_mul", "mul_mat_id_add_id",
    "mul_mat_id_mul", "rms_norm_mul_rope_view_set_rows", "rms_norm_mul_rope", "rms_norm_mul",
    "ssm_conv_bias_silu", "ssm_conv_silu", "rope_view_set_rows", "hc_combine", "snake", "topk_qsa",
    "topk_moe_early_softmax_norm", "topk_moe_sigmoid_norm_bias", "topk_moe_sqrt_softplus_norm_bias",
    "topk_moe_early_softmax", "topk_moe_late_softmax", "topk_moe_scale", "add_softplus_mul",
    "sigmoid_mul", "add_rms", "multi_add_scale", "scale_silu",
    "concat_ssm_conv_bias_silu", "concat_ssm_conv_silu", "concat_ssm_conv",
};
static bool vk_fusion_patterns_disabled_any = false;
static std::vector<std::string> vk_fusion_patterns_disabled; // lower-case; trailing '*' = prefix match
static bool vk_fusion_list_enabled = false;

static bool ggml_vk_fusion_pattern_matches(const std::string & pat, const char * name) {
    if (!pat.empty() && pat.back() == '*') {
        return strncmp(name, pat.c_str(), pat.size() - 1) == 0;
    }
    return pat == name;
}

static bool ggml_vk_fusion_disabled_slow(const char * name) {
    for (const std::string & pat : vk_fusion_patterns_disabled) {
        if (ggml_vk_fusion_pattern_matches(pat, name)) {
            return true;
        }
    }
    return false;
}

static void ggml_vk_fusion_patterns_init() {
    vk_fusion_list_enabled = ggml_vk_env_bool("GGML_VK_FUSION_LIST", false);
    vk_fusion_patterns_disabled.clear();
    vk_fusion_patterns_disabled_any = false;
    const char * s = getenv("GGML_VK_DISABLE_FUSION_PATTERNS");
    if (s == nullptr) {
        return;
    }
    std::string tok;
    for (const char * p = s; ; ++p) {
        if (*p == ',' || *p == ';' || *p == ' ' || *p == '\0') {
            if (!tok.empty()) {
                vk_fusion_patterns_disabled.push_back(tok);
                tok.clear();
            }
            if (*p == '\0') {
                break;
            }
        } else {
            tok += (char) tolower((unsigned char) *p);
        }
    }
    vk_fusion_patterns_disabled_any = !vk_fusion_patterns_disabled.empty();
    for (const std::string & pat : vk_fusion_patterns_disabled) {
        bool known = false;
        for (const char * n : vk_fusion_pattern_names) {
            known = known || ggml_vk_fusion_pattern_matches(pat, n);
        }
        if (!known) {
            GGML_LOG_WARN("ggml_vulkan: GGML_VK_DISABLE_FUSION_PATTERNS: \"%s\" matches no fusion pattern\n", pat.c_str());
        }
    }
    if (vk_fusion_patterns_disabled_any) {
        GGML_LOG_INFO("ggml_vulkan: fusion patterns disabled: %s\n", s);
    }
}

// GGML_VK_FUSION_LIST: report a fusion the first time its (name, fused op names) tuple fires.
// n_fused nodes starting at node_idx are listed with ggml_op_desc (SILU, not UNARY).
static void ggml_vk_fusion_list_report(const char * name, const struct ggml_cgraph * cgraph, int node_idx, int n_fused,
                                       const char * suffix = nullptr) {
    std::string key = name;
    if (suffix) {
        key += suffix;
    }
    key += ": ";
    for (int k = 0; k < n_fused; ++k) {
        if (k) {
            key += '+';
        }
        key += ggml_op_desc(cgraph->nodes[node_idx + k]);
    }
    static std::mutex mutex;
    static std::set<std::string> seen;
    std::lock_guard<std::mutex> guard(mutex);
    if (seen.insert(key).second) {
        fprintf(stderr, "[vk-fusion] %s\n", key.c_str());
    }
}

// env: GGML_SCHED_PROFILE=1 - host-side timing of ggml_backend_vk_graph_compute, printed to stderr as
// "[sched-prof]" lines (the same env drives llama-context.cpp and ggml_backend_sched_compute_splits).
// Read once and cached: with the env off every instrumented site is a single branch on this bool. It does
// not touch the GGML_VK_PERF_LOGGER timestamp-query path, which perturbs the GPU timeline.
static bool ggml_vk_sched_prof_enabled() {
    static const bool enabled = ggml_vk_env_bool("GGML_SCHED_PROFILE", false);
    return enabled;
}

// env: GGML_VK_FUSION_COUNT=1 - one stderr line per graph_compute call,
//   [vk-fusion-count] graph nodes=N name1=c1 name2=c2 ... vetoed:name=c ...
// with the number of times each fusion pattern was dispatched in that graph (after the src/dst overlap
// veto) and, as vetoed:<name>, the number of matches the veto turned back into unfused ops. GGML_VK_FUSION_DIAG
// only logs the individual vetoes, so it cannot tell "the router fused in 47 layers" from "in 12"; this can,
// per graph, and two runs (or the two arms of an A/B) can be compared line by line.
// Read once and cached: when unset the cost is one load per node and an empty std::map per graph.
// Two keys on the line are not fusions: add_rms (a per-graph offset decision) and
// [TAG_QSA_FUSED_SELECT] topk_qsa_op (QSA selections that arrived as one GGML_OP_QSA_TOP_K node
// instead of as the seven-node topk_qsa pattern, i.e. GGML_VK_QSA_FUSED_SELECT=1). Neither can be
// vetoed, so neither ever appears with a vetoed:/disabled: prefix.
// [TAG_HC_MIX_TAIL] overlap:multi_add_scale counts multi_adds whose trailing SCALE matched but whose destination
// overlapped a stream source: they ran as the plain multi_add (+ SCALE), so they also show in multi_add=.
static bool ggml_vk_fusion_count_enabled() {
    static const bool enabled = ggml_vk_env_bool("GGML_VK_FUSION_COUNT", false);
    return enabled;
}

// GGML_VK_FUSION_COUNT: the per-graph tally. Keys are the lower-case fusion_string of the match
// site, optionally prefixed (with "vetoed:" for a match the overlap veto undid).
static void ggml_vk_fusion_count_add(std::map<std::string, int> & counts, const char * prefix, const char * fusion_string) {
    std::string key = prefix;
    for (const char * c = fusion_string; *c; ++c) {
        key += (char) tolower((unsigned char) *c);
    }
    counts[key]++;
}

// GGML_VK_FUSION_COUNT: FNV-1a, the mixer of the per-graph numerics signature (sig=0x...).
// Only ever fed under ggml_vk_fusion_count_enabled(), so the knob stays free when it is off.
static const uint64_t vk_fnv1a_seed = 0xcbf29ce484222325ull;

static uint64_t ggml_vk_fnv1a(uint64_t h, const void * data, size_t n) {
    const uint8_t * p = (const uint8_t *) data;
    for (size_t i = 0; i < n; ++i) {
        h = (h ^ p[i]) * 0x100000001b3ull;
    }
    return h;
}

static uint64_t ggml_vk_fnv1a_str(uint64_t h, const char * s) {
    return ggml_vk_fnv1a(h, s, strlen(s));
}

// [TAG_DMMV_RM] G50a: rows-per-workgroup knob for the dense mat-vec (dmmv) pipelines.  Same
// "absent leaves the default, otherwise the value is parsed" convention as [TAG_ENV_BOOL].
//
// The value becomes the NUM_ROWS specialization constant (and wg_denoms[0]) of a dmmv pipeline.
// NUM_ROWS only decides *which* output rows one workgroup owns - every mul_mat_vec*.comp starts
// with `first_row = NUM_ROWS * (gl_WorkGroupID.x + gl_NumWorkGroups.x * gl_WorkGroupID.z)` and
// keeps one independent accumulator per (col, row) in `temp[NUM_COLS][NUM_ROWS]`.  The per-thread
// k partition is a function of tid and BLOCK_SIZE only, and reduce_result()
// (mul_mat_vec_base.glsl) does exactly one subgroupAdd per (col, row) whatever NUM_ROWS is, so
// the summation order of every individual output element is untouched: all accepted values are
// bit-identical, only the memory-level parallelism per wave and the workgroup count change.
//
// Accepted: 1, 2, 4, 8.  `max_rm` is the largest value whose worst-case
// `shared FLOAT_TYPE tmpsh[NUM_COLS][NUM_ROWS][BLOCK_SIZE]` (mul_mat_vec_base.glsl, used by the
// SHMEM and HYBRID reduction variants) still fits the device's shared-memory limit.  Anything
// else leaves the default in place with a warning rather than failing pipeline creation.
static uint32_t ggml_vk_env_dmmv_rm(const char * name, uint32_t def, uint32_t max_rm) {
    const char * s = getenv(name);
    if (s == nullptr || *s == '\0') {
        return def;
    }
    const int v = atoi(s);
    if (v != 1 && v != 2 && v != 4 && v != 8) {
        GGML_LOG_WARN("ggml_vulkan: %s=%s ignored, accepted values are 1, 2, 4, 8 (using %u)\n", name, s, def);
        return def;
    }
    if ((uint32_t) v > max_rm) {
        GGML_LOG_WARN("ggml_vulkan: %s=%s ignored, at most %u rows/workgroup fit in shared memory here (using %u)\n",
                      name, s, max_rm, def);
        return def;
    }
    return (uint32_t) v;
}

static uint64_t ggml_vk_get_node_flops(const ggml_tensor * node) {
    if (node->op == GGML_OP_MUL_MAT || node->op == GGML_OP_MUL_MAT_ID || node->op == GGML_OP_MUL_MAT_ROWS) {
        const uint64_t m     = node->ne[0];
        const uint64_t n     = node->ne[1];
        const uint64_t k     = node->src[1]->ne[0];
        const uint64_t batch = node->ne[2] * node->ne[3];
        return m * n * (k + (k - 1)) * batch;
    }
    if (node->op == GGML_OP_CONV_2D || node->op == GGML_OP_CONV_TRANSPOSE_2D) {
        const ggml_tensor * knl = node->src[0];
        const uint64_t Cout  = node->ne[2];
        const uint64_t size_K = node->src[1]->ne[2] * knl->ne[0] * knl->ne[1];
        const uint64_t size_N = node->ne[3] * node->ne[0] * node->ne[1];
        return Cout * size_N * (size_K + (size_K - 1));
    }
    if (node->op == GGML_OP_CONV_3D) {
        const ggml_tensor * knl = node->src[0];
        const uint64_t OC     = ggml_get_op_params_i32(node, 11);
        const uint64_t IC     = ggml_get_op_params_i32(node, 9);
        const uint64_t size_K = IC * knl->ne[0] * knl->ne[1] * knl->ne[2];
        const uint64_t size_N = node->ne[3] / OC * node->ne[0] * node->ne[1] * node->ne[2];
        return OC * size_N * (size_K + (size_K - 1));
    }
    if (node->op == GGML_OP_FLASH_ATTN_EXT) {
        const ggml_tensor * q = node->src[0];
        const ggml_tensor * k = node->src[1];
        const ggml_tensor * v = node->src[2];
        return 2ull * q->ne[1] * q->ne[2] * (k->ne[0] + v->ne[0]) * (node->src[5] ? node->src[5]->ne[0] : k->ne[1]) * q->ne[3]; // [TAG_QSA_INDEXED_FA] W ids
    }
    return 0;
}

static void ggml_vk_print_node_list(const ggml_cgraph * cgraph, int start, int end) {
    uint64_t total_flops = 0;
    int n_ops = 0;
    for (int j = start; j <= end && j < cgraph->n_nodes; j++) {
        uint64_t flops = ggml_vk_get_node_flops(cgraph->nodes[j]);
        total_flops += flops;
        n_ops++;
        if (flops > 0) {
            GGML_LOG_CONT("  node %d: %s (%s) [%.2f GFLOP]\n",
                    j, cgraph->nodes[j]->name, ggml_op_name(cgraph->nodes[j]->op),
                    flops / 1e9);
        } else {
            GGML_LOG_CONT("  node %d: %s (%s)\n",
                    j, cgraph->nodes[j]->name, ggml_op_name(cgraph->nodes[j]->op));
        }
    }
    GGML_LOG_CONT("  total: %d ops, %.2f GFLOP\n", n_ops, total_flops / 1e9);
}

static void ggml_vk_print_device_lost_info(const vk_device& device) {
    ggml_vk_print_device_fault_info(device);
    if (device->serialize_submissions && device->diag_cgraph != nullptr && device->diag_prev_start >= 0) {
        GGML_LOG_ERROR("ggml_vulkan: device lost on %s, likely caused by previous submission (nodes %d to %d):\n",
                device->name.c_str(), device->diag_prev_start, device->diag_prev_end);
        ggml_vk_print_node_list(device->diag_cgraph, device->diag_prev_start, device->diag_prev_end);
    } else {
        GGML_LOG_ERROR("ggml_vulkan: device lost on %s\n", device->name.c_str());
    }
}

class vk_perf_logger {
  public:
    void print_timings(bool force = false) {
        if (timings.empty()) {
            return;
        }
        print_count++;
        if ((print_count % vk_perf_logger_frequency) != 0 && !force) {
            return;
        }
        print_count = 0;
        uint64_t total_all_op_times = 0;
        std::cerr << "----------------\nVulkan Timings:" << std::endl;
        for (const auto & t : timings) {
            uint64_t total_op_times = 0;
            for (const auto & time : t.second) {
                total_op_times += time;
            }
            std::cerr << t.first << ": " << t.second.size() << " x " << (total_op_times / t.second.size() / 1000.0)
                      << " us = " << (total_op_times / 1000.0) << " us";

            // If we have as many flops entries as timing entries for the op, then compute and log the flops/S.
            auto it = flops.find(t.first);
            if (it != flops.end() && (it->second).size() == t.second.size()) {
                uint64_t total_op_flops = 0;
                for (const auto & elem : it->second) {
                    total_op_flops += elem;
                }
                std::cerr << " ("
                          << (double(total_op_flops) / (1000.0 * 1000.0 * 1000.0)) /
                                 (double(total_op_times) / (1000.0 * 1000.0 * 1000.0))
                          << " GFLOPS/s)";
            }

            total_all_op_times += total_op_times;

            std::cerr << std::endl;
        }

        if (timings.size() > 0) {
            std::cerr << "Total time: " << total_all_op_times / 1000.0 << " us." << std::endl;
        }

        timings.clear();
        flops.clear();
    }

    std::string get_node_fusion_name(const ggml_tensor * node, const char *fusion_name, uint64_t *n_flops) {
        *n_flops = ggml_vk_get_node_flops(node);
        std::string fusion_str;
        if (fusion_name) {
            fusion_str = fusion_name + std::string(" ");
        }
        if (node->op == GGML_OP_UNARY) {
            return fusion_str + ggml_unary_op_name(ggml_get_unary_op(node));
        }
        // [TAG_QSA_POOL_REMAP] MUL_MAT_ROWS[_VEC] f32 m=<blocks> n=<heads x queries> k=<idx_dim>, the indexer score
        if (node->op == GGML_OP_MUL_MAT || node->op == GGML_OP_MUL_MAT_ID || node->op == GGML_OP_MUL_MAT_ROWS) {
            const uint64_t m     = node->ne[0];
            const uint64_t n     = node->ne[1];
            const uint64_t k     = node->src[1]->ne[0];
            const uint64_t batch = node->ne[2] * node->ne[3];
            std::string    name  = ggml_op_name(node->op);
            if (((node->op == GGML_OP_MUL_MAT || node->op == GGML_OP_MUL_MAT_ROWS) && n <= mul_mat_vec_max_cols) ||
                (node->op == GGML_OP_MUL_MAT_ID && node->src[2]->ne[1] == 1)) {
                name += "_VEC";
            }
            name += " ";
            name += ggml_type_name(node->src[0]->type);
            name += " m=" + std::to_string(m) + " n=" + std::to_string(n) + " k=" + std::to_string(k);
            if (node->op == GGML_OP_MUL_MAT_ID) {
                name += " n_expert=" + std::to_string(node->src[0]->ne[2]);
            }
            if (batch > 1) {
                name += " batch=" + std::to_string(batch);
            }
            return fusion_str + name;
        }
        if (node->op == GGML_OP_CONV_2D || node->op == GGML_OP_CONV_TRANSPOSE_2D) {
            std::string   name    = ggml_op_name(node->op);
            const ggml_tensor * knl = node->src[0];
            uint64_t      Cout    = node->ne[2];
            uint64_t      size_K  = node->src[1]->ne[2] * knl->ne[0] * knl->ne[1];
            uint64_t      size_N  = node->ne[3] * node->ne[0] * node->ne[1];
            name += " M=Cout=" + std::to_string(Cout) + ", K=Cin*KW*KH=" + std::to_string(size_K) +
                    ", N=N*OW*OH=" + std::to_string(size_N);
            return fusion_str + name;
        }
        if (node->op == GGML_OP_RMS_NORM) {
            std::string   name    = ggml_op_name(node->op);
            name += "(" + std::to_string(node->ne[0]) + "," + std::to_string(node->ne[1]) + "," + std::to_string(node->ne[2]) + "," + std::to_string(node->ne[3]) + ")";
            return fusion_str + name;
        }
        if (node->op == GGML_OP_FLASH_ATTN_EXT) {
            const ggml_tensor * dst = node;
            const ggml_tensor * q = node->src[0];
            const ggml_tensor * k = node->src[1];
            const ggml_tensor * v = node->src[2];
            const ggml_tensor * m = node->src[3];
            std::stringstream name;
            name << fusion_str;
            name << ggml_op_name(node->op) <<
                " dst(" << dst->ne[0] << "," << dst->ne[1] << "," << dst->ne[2] << "," << dst->ne[3] << "), " <<
                " q(" << q->ne[0] << "," << q->ne[1] << "," << q->ne[2] << "," << q->ne[3] << "), " <<
                " k(" << k->ne[0] << "," << k->ne[1] << "," << k->ne[2] << "," << k->ne[3] << "), " <<
                " v(" << v->ne[0] << "," << v->ne[1] << "," << v->ne[2] << "," << v->ne[3] << "), " <<
                " m(" << (m?m->ne[0]:0) << "," << (m?m->ne[1]:0) << "," << (m?m->ne[2]:0) << "," << (m?m->ne[3]:0) << ")";
            if (node->src[5]) {
                name << " ids(" << node->src[5]->ne[0] << ")"; // [TAG_QSA_INDEXED_FA] W: indexed vs dense in the profile
            }
            return name.str();
        }
        if (node->op == GGML_OP_TOP_K) {
            std::stringstream name;
            name << fusion_str;
            name << ggml_op_name(node->op) <<
                " K=" << node->ne[0] <<
                " (" << node->src[0]->ne[0] << "," << node->src[0]->ne[1] << "," << node->src[0]->ne[2] << "," << node->src[0]->ne[3] << ")";
            return name.str();
        }
        return fusion_str + ggml_op_name(node->op);
    }

    void log_timing(const ggml_tensor * node, const char *fusion_name, uint64_t time) {
        uint64_t n_flops;
        std::string name = get_node_fusion_name(node, fusion_name, &n_flops);
        if (n_flops) {
            flops[name].push_back(n_flops);
        }
        timings[name].push_back(time);
    }

    void log_timing(const std::vector<ggml_tensor *> &nodes, const std::vector<const char *> &names, uint64_t time) {
        uint64_t total_flops = 0;
        std::string name;
        for (size_t n = 0; n < nodes.size(); ++n) {
            uint64_t n_flops = 0;
            name += get_node_fusion_name(nodes[n], names[n], &n_flops);
            total_flops += n_flops;

            if (n != nodes.size() - 1) {
                name += ", ";
            }
        }
        if (total_flops) {
            flops[name].push_back(total_flops);
        }
        timings[name].push_back(time);
    }

  private:
    std::map<std::string, std::vector<uint64_t>> timings;
    std::map<std::string, std::vector<uint64_t>> flops;
    uint32_t print_count {};
};

struct ggml_backend_vk_context {
    std::string name;

    vk_device device;

    size_t semaphore_idx, event_idx;
    ggml_vk_garbage_collector gc;
    size_t prealloc_size_x, prealloc_size_y, prealloc_size_split_k, prealloc_size_add_rms_partials, prealloc_size_add_rms_partials_offset;
    vk_buffer prealloc_x, prealloc_y, prealloc_split_k, prealloc_add_rms_partials, sync_staging;
    // [TAG_VK_EXPERT_OCC] GGML_VK_EXPERT_OCCUPANCY=1 debug telemetry: a host-visible staging buffer of
    // vk_expert_occ_slots per-expert count snapshots, the eligible-dispatch counter that drives the
    // 1-in-N sampling, and the snapshots recorded since the last fence wait (drained and logged by
    // ggml_vk_synchronize). All three stay empty/zero while the knob is off.
    struct vk_expert_occ_sample {
        size_t      offset;  // byte offset of the snapshot in expert_occ_staging
        uint32_t    n_as;    // experts in the weight tensor (= count words copied)
        uint32_t    topk;    // experts per token (ids->ne[0])
        uint32_t    tile_n;  // BN of the chosen matmul_id pipeline (wg_denoms[1])
        uint64_t    rows;    // tokens in the batch (ids->ne[1])
        std::string name;    // dst tensor name
        std::string pipeline;
    };
    vk_buffer expert_occ_staging;
    uint64_t expert_occ_counter {};
    std::vector<vk_expert_occ_sample> expert_occ_pending;
    // [TAG_QSA_SCRATCH] GGML_VK_QSA_SCRATCH_PRESIZE=1: the largest fused TOPK_QSA select scratch any
    // graph handed to ggml_vk_graph_optimize would need. ggml_backend_sched optimizes every split of
    // every graph, and the *reserve* graphs are optimized at context creation, i.e. before the first
    // dispatch - so the first QSA dispatch can raise the shared prealloc_x straight to the graph
    // span's extent instead of regrowing it once per prefill ubatch. prealloc_x_qsa_presized only
    // labels the log line (first raise vs. a later growth). Both stay 0/false while the knob is off.
    size_t prealloc_size_qsa_hint {};
    bool prealloc_x_qsa_presized {};
    bool prealloc_x_qsa_range_warned {};
    vk::Fence fence, almost_ready_fence;
    bool submit_pending {};
    bool almost_ready_fence_pending {};
    // Set before op_add and unset after op_rms_norm to indicate that the add should
    // write partial sums to accumulate the square of the vector components
    bool do_add_rms_partials_offset_calculation;
    bool do_add_rms_partials;

    uint64_t last_total_flops {UINT64_MAX};

    // Cache most recent tensor that was converted into prealloc_y, and what pipeline it used to convert.
    vk_pipeline_struct * prealloc_y_last_pipeline_used {};
    const ggml_tensor * prealloc_y_last_tensor_used {};
    // True when prealloc_y holds the padded fp16 layout used by the coopmat2 B decode-vector callback.
    // If false, then it's contiguous.
    bool prealloc_y_last_decode_vector_staging {};

    // Track which nodes have been used since the last sync, and whether they were written to
    std::vector<const ggml_tensor *> unsynced_nodes_written;
    std::vector<const ggml_tensor *> unsynced_nodes_read;
    // Track which prealloc buffers have pending reads that need to be synchronized.
    // These are checked before writing to the buffer (and call ggml_vk_sync_buffers if set),
    // and set to true after the buffer contents are consumed.
    bool prealloc_x_need_sync, prealloc_y_need_sync, prealloc_split_k_need_sync;

    vk_context_ref compute_ctx;

    // [TAG_ASYNC_READ_UMA] true while compute_ctx carries a host memcpy queued by the direct-read
    // shortcut in ggml_vk_buffer_read_2d_async, i.e. a read that is not yet performed and whose
    // source is still live device memory. See ggml_vk_flush_pending_host_reads.
    bool pending_host_read {};

    vk_context_ref transfer_ctx;
    vk_semaphore transfer_semaphore;
    uint64_t transfer_semaphore_last_submitted {};

    std::vector<vk_context_ref> tensor_ctxs;

    std::vector<vk::DescriptorPool> descriptor_pools;
    std::vector<vk::DescriptorSet> descriptor_sets;
    // [TAG_UP29280] last bindings written to each set; descriptor_sets is append-only so an index always names the same set
    std::vector<std::vector<vk::DescriptorBufferInfo>> descriptor_set_bindings;
    uint64_t descriptor_set_bindings_destroy_count {};
    uint32_t descriptor_set_idx {};
    uint32_t pipeline_descriptor_set_requirements {};

    vk_command_pool compute_cmd_pool;
    vk_command_pool transfer_cmd_pool;

    // number of additional consecutive nodes that are being fused with the
    // node currently being processed
    int num_additional_fused_ops {};
    // Bitmask of which fused ops need to write an intermediate value to memory.
    // Bit 'i' means nodes[start_of_fusion + i] writes to memory.
    // If there's no fusion, bit 0 is still set.
    int fused_ops_write_mask {};
    topk_moe_mode fused_topk_moe_mode {};
    bool fused_topk_moe_scale {};
    // UNARY(SIGMOID) + MUL: the mul reads the sigmoid's source and applies the sigmoid itself
    bool fused_mul_sigmoid {};
    // ADD + UNARY(SOFTPLUS) + MUL: the GDN decay pre-chain, one dispatch off the ADD node
    bool fused_gdn_pre {};
    // [TAG_HC_MIX_TAIL] multi_add whose last fused node is the trailing SCALE (num_additional_fused_ops
    // then counts the adds AND the scale), and SCALE + SILU dispatched off the SCALE node
    bool fused_multi_add_scale {};
    bool fused_scale_silu {};
    // [TAG_CONV_INPUT_SPLIT] CONCAT + SSM_CONV (+ ...) dispatched off the CONCAT node
    bool fused_concat_ssm_conv {};
    // GGML_VK_FUSION_COUNT: add_rms fusions of the current graph (decided inside ggml_vk_build_graph)
    int fusion_count_add_rms {};
    // GGML_VK_FUSION_COUNT: running numerics signature of the current graph. Fed once per node
    // (op, fused pattern, applied misalignment) and once per dispatch (pipeline name + workgroup
    // counts, which is where the shader and the split_k/rows-per-wg choice show up).
    uint64_t fusion_sig {};
    // GGML_VK_FUSION_COUNT: matches GGML_VK_DISABLE_FUSION_PATTERNS vetoed in the current graph,
    // reported as disabled:<name>=<count> so a bisect arm can be proven to have acted
    std::map<std::string, int> fusion_count_disabled;
    // QSA indexer gather+add+top_k fused into one radix-select
    bool fused_topk_qsa {};

    // for GGML_VK_PERF_LOGGER
    std::unique_ptr<vk_perf_logger> perf_logger;
    vk::QueryPool query_pool;
    std::vector<const char *> query_fusion_names;
    std::vector<int> query_fusion_node_count;
    std::vector<ggml_tensor *> query_nodes;
    std::vector<int> query_node_idx;
    int32_t num_queries {};
    int32_t query_idx {};

    // for GGML_SCHED_PROFILE: host time spent inside ggml_vk_submit() during the current graph_compute
    int64_t sched_prof_submit_us {};
};

// The gate at every fusion match site, evaluated *after* the pattern's own match test so that a
// veto belongs to a pattern that really matched at this node: returns true when
// GGML_VK_DISABLE_FUSION_PATTERNS names this pattern, and then records it for the
// GGML_VK_FUSION_COUNT tally. One load of a cached bool when the knob is unset.
static inline bool vk_fusion_veto(ggml_backend_vk_context * ctx, const char * name) {
    if (!vk_fusion_patterns_disabled_any || !ggml_vk_fusion_disabled_slow(name)) {
        return false;
    }
    if (ggml_vk_fusion_count_enabled()) {
        ctx->fusion_count_disabled[name]++;
    }
    return true;
}

static void * const vk_ptr_base = (void *)(uintptr_t) 0x1000;  // NOLINT

static uint64_t vk_tensor_offset(const ggml_tensor * tensor) {
    if (tensor->view_src) {
        return (uint8_t *) tensor->view_src->data - (uint8_t *) vk_ptr_base;
    }
    return (uint8_t *) tensor->data - (uint8_t *) vk_ptr_base;
}

static uint32_t get_misalign_bytes(const ggml_backend_vk_context * ctx, const ggml_tensor * t)
{
    return ((vk_tensor_offset(t) + t->view_offs) & (ctx->device->properties.limits.minStorageBufferOffsetAlignment - 1));;
}

static uint32_t ggml_vk_concat_unit_size(ggml_type type) {
    const uint32_t type_size = ggml_type_size(type);

    if (!ggml_is_quantized(type)) {
        return type_size;
    }

    // Use the widest existing concat shader that evenly divides a quant block.
    if (type_size % 8 == 0) {
        return 8;
    }
    if (type_size % 4 == 0) {
        return 4;
    }
    if (type_size % 2 == 0) {
        return 2;
    }
    return 1;
}

static bool ggml_vk_concat_supported(const ggml_tensor * src0, const ggml_tensor * src1, const ggml_tensor * dst) {
    if (src0->type != src1->type || src0->type != dst->type) {
        return false;
    }

    if (!ggml_is_quantized(src0->type)) {
        const size_t type_size = ggml_type_size(src0->type);
        return type_size == 1 || type_size == 2 || type_size == 4 || type_size == 8;
    }

    // Quantized tensor rows are block-aligned when created.
    return ggml_is_contiguous_rows(src0) && ggml_is_contiguous_rows(src1) && ggml_is_contiguous_rows(dst);
}

template <typename T> void init_pushconst_tensor_offsets(ggml_backend_vk_context * ctx, T &p, const ggml_tensor * src0, const ggml_tensor * src1, const ggml_tensor * src2, const ggml_tensor * src3, ggml_tensor * dst) {
    GGML_UNUSED(p);
    GGML_UNUSED(src0);
    GGML_UNUSED(src1);
    GGML_UNUSED(src2);
    GGML_UNUSED(src3);
    GGML_UNUSED(dst);
    static_assert(!std::is_const<T>::value, "unexpected type");
    GGML_ASSERT(!src0 || get_misalign_bytes(ctx, src0) == 0);
    GGML_ASSERT(!src1 || get_misalign_bytes(ctx, src1) == 0);
    GGML_ASSERT(!src2 || get_misalign_bytes(ctx, src2) == 0);
    GGML_ASSERT(!src3 || get_misalign_bytes(ctx, src3) == 0);
    GGML_ASSERT(!dst  || get_misalign_bytes(ctx, dst) == 0);
}

template <> void init_pushconst_tensor_offsets(ggml_backend_vk_context * ctx, vk_mat_vec_p021_push_constants &p, const ggml_tensor * src0, const ggml_tensor * src1, const ggml_tensor * src2, const ggml_tensor * src3, ggml_tensor * dst) {
    const uint32_t b_offset = get_misalign_bytes(ctx, src1) / ggml_type_size(src1->type);
    const uint32_t d_offset = get_misalign_bytes(ctx, dst) / ggml_type_size(dst->type);

    p.b_offset = b_offset;
    p.d_offset = d_offset;

    GGML_UNUSED(src0);
    GGML_UNUSED(src2);
    GGML_UNUSED(src3);
}

template <> void init_pushconst_tensor_offsets(ggml_backend_vk_context * ctx, vk_mat_vec_nc_push_constants &p, const ggml_tensor * src0, const ggml_tensor * src1, const ggml_tensor * src2, const ggml_tensor * src3, ggml_tensor * dst) {
    const uint32_t b_offset = get_misalign_bytes(ctx, src1) / ggml_type_size(src1->type);
    const uint32_t d_offset = get_misalign_bytes(ctx, dst) / ggml_type_size(dst->type);

    p.b_offset = b_offset;
    p.d_offset = d_offset;

    GGML_UNUSED(src0);
    GGML_UNUSED(src2);
    GGML_UNUSED(src3);
}

template <> void init_pushconst_tensor_offsets(ggml_backend_vk_context * ctx, vk_op_fwht_push_constants &p, const ggml_tensor * src0, const ggml_tensor * src1, const ggml_tensor * src2, const ggml_tensor * src3, ggml_tensor * dst) {
    p.src_offset = get_misalign_bytes(ctx, src0) / ggml_type_size(src0->type);
    p.dst_offset = get_misalign_bytes(ctx, dst)  / ggml_type_size(dst->type);

    GGML_UNUSED(src1);
    GGML_UNUSED(src2);
    GGML_UNUSED(src3);
}

struct ggml_backend_vk_buffer_context {
    vk_device_ref device;
    vk_buffer dev_buffer;
    std::string name;

    ggml_backend_vk_buffer_context(vk_device_ref device, vk_buffer&& dev_buffer, std::string& name) :
        device(device),
        dev_buffer(dev_buffer),
        name(name) {
    }

    ~ggml_backend_vk_buffer_context() {
        ggml_vk_destroy_buffer(dev_buffer);
    }
};

void vk_memory_logger::log_allocation(vk_buffer_ref buf_ref, size_t size) {
    if (!vk_memory_logger_enabled) {
        return;
    }
    std::lock_guard<std::mutex> guard(log_mutex);
    vk_buffer buf = buf_ref.lock();
    const bool device = bool(buf->memory_property_flags & vk::MemoryPropertyFlagBits::eDeviceLocal);
    const std::string type = device ? "device" : "host";
    allocations[buf->buffer] = size;
    total_device += device ? size : 0;
    total_host += device ? 0 : size;
    VK_LOG_MEMORY(buf->device->name << ": +" << format_size(size) << " " << type << " at " << buf->buffer << ". Total device: " << format_size(total_device) << ", total host: " << format_size(total_host));
}

void vk_memory_logger::log_deallocation(vk_buffer_ref buf_ref) {
    if (buf_ref.expired() || buf_ref.lock()->size == 0 || !vk_memory_logger_enabled) {
        return;
    }

    std::lock_guard<std::mutex> guard(log_mutex);
    vk_buffer buf = buf_ref.lock();
    const bool device = bool(buf->memory_property_flags & vk::MemoryPropertyFlagBits::eDeviceLocal);
    std::string type = device ? "device" : "host";
    auto it = allocations.find(buf->buffer);
    if (it != allocations.end()) {
        total_device -= device ? it->second : 0;
        total_host -= device ? 0 : it->second;
        VK_LOG_MEMORY(buf->device->name << ": -" << format_size(it->second) << " " << type << " at " << buf->buffer << ". Total device: " << format_size(total_device) << ", total host: " << format_size(total_host));
        allocations.erase(it);
    } else {
        VK_LOG_MEMORY("ERROR " << buf->device->name << ": Attempted to deallocate unknown " << type << " memory at " << buf->buffer);
    }
}

