static void ggml_vk_test_dequant_matmul(ggml_backend_vk_context * ctx, size_t m, size_t n, size_t k, size_t batch, size_t num_it, size_t split_k, size_t shader_size, ggml_type quant, bool mmq = false) {
    VK_LOG_DEBUG("ggml_vk_test_dequant_matmul(" << m << ", " << n << ", " << k << ", " << batch << ", " << num_it << ", " << split_k << ", " << ggml_type_name(quant) << ")");
    const size_t x_ne = m * k * batch;
    const size_t y_ne = k * n * batch;
    const size_t d_ne = m * n * batch;

    vk_matmul_pipeline2 * pipelines;

    if (mmq) {
        pipelines = ctx->device->pipeline_dequant_mul_mat_mat_q8_1;
    } else {
        pipelines = ctx->device->pipeline_dequant_mul_mat_mat;
    }

    const bool fp16acc = ctx->device->fp16;

    vk_pipeline p;
    std::string shname;
    if (shader_size == 0) {
        p = fp16acc ? pipelines[quant].f16acc->a_s : pipelines[quant].f32acc->a_s;
        shname = std::string(ggml_type_name(quant)) + "_ALIGNED_S";
    } else if (shader_size == 1) {
        p = fp16acc ? pipelines[quant].f16acc->a_m : pipelines[quant].f32acc->a_m;
        shname = std::string(ggml_type_name(quant)) + "_ALIGNED_M";
    } else if (shader_size == 2) {
        p = fp16acc ? pipelines[quant].f16acc->a_l : pipelines[quant].f32acc->a_l;
        shname = std::string(ggml_type_name(quant)) + "_ALIGNED_L";
    } else {
        GGML_ASSERT(0);
    }

    const size_t kpad = mmq ? 0 : ggml_vk_align_size(k, p->align);

    if (mmq || k != kpad) {
        if (shader_size == 0) {
            p = fp16acc ? pipelines[quant].f16acc->s : pipelines[quant].f32acc->s;
            shname = std::string(ggml_type_name(quant)) + "_S";
        } else if (shader_size == 1) {
            p = fp16acc ? pipelines[quant].f16acc->m : pipelines[quant].f32acc->m;
            shname = std::string(ggml_type_name(quant)) + "_M";
        } else if (shader_size == 2) {
            p = fp16acc ? pipelines[quant].f16acc->l : pipelines[quant].f32acc->l;
            shname = std::string(ggml_type_name(quant)) + "_L";
        } else {
            GGML_ASSERT(0);
        }
    }

    if (p == nullptr) {
        std::cerr << "error: no pipeline for ggml_vk_test_dequant_matmul " << ggml_type_name(quant) << std::endl;
        return;
    }

    const size_t x_sz = sizeof(float) * x_ne;
    const size_t y_sz = sizeof(float) * y_ne;
    const size_t qx_sz = x_ne * ggml_type_size(quant)/ggml_blck_size(quant);
    const size_t qy_sz = mmq ? y_ne * ggml_type_size(GGML_TYPE_Q8_1)/ggml_blck_size(GGML_TYPE_Q8_1) : y_sz;
    const size_t d_sz = sizeof(float) * d_ne;
    float * x = (float *) malloc(x_sz);
    float * y = (float *) malloc(y_sz);
    void * qx = malloc(qx_sz);
    vk_buffer qx_buf = ggml_vk_create_buffer_check(ctx->device, qx_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
    vk_buffer y_buf = ggml_vk_create_buffer_check(ctx->device, y_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
    vk_buffer qy_buf = ggml_vk_create_buffer_check(ctx->device, qy_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
    vk_buffer d_buf = ggml_vk_create_buffer_check(ctx->device, d_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
    float * d = (float *) malloc(d_sz);
    float * d_chk = (float *) malloc(d_sz);

    for (size_t i = 0; i < x_ne; i++) {
        x[i] = (rand() / (float)RAND_MAX) * 2.0f - 1.0f;
        // x[i] = (i % k == i / k) ? 1.0f : 0.0f;
        // x[i] = i % k;
    }

    ggml_vk_quantize_data(x, qx, x_ne, quant);

    for (size_t i = 0; i < y_ne; i++) {
        y[i] = (rand() / (float)RAND_MAX) * 2.0f - 1.0f;
        // y[i] = (i % k == i / k) ? 1.0f : 0.0f;
        // y[i] = i % k;
    }

    if (split_k > 1) {
        ggml_pipeline_request_descriptor_sets(ctx, ctx->device->pipeline_matmul_split_k_reduce, num_it);

        if (ctx->prealloc_split_k == nullptr || ctx->prealloc_split_k->size < sizeof(float) * d_ne * split_k) {
            // Resize buffer
            if (ctx->prealloc_split_k != nullptr) {
                ggml_vk_destroy_buffer(ctx->prealloc_split_k);
            }
            ctx->prealloc_split_k = ggml_vk_create_buffer_check(ctx->device, sizeof(float) * d_ne * split_k, {vk::MemoryPropertyFlagBits::eDeviceLocal});
        }
    }
    if (mmq) {
        vk_pipeline pipeline_quantize_q8_1 = ggml_vk_get_quantize_pipeline(ctx, GGML_TYPE_Q8_1);
        ggml_pipeline_request_descriptor_sets(ctx, pipeline_quantize_q8_1, num_it);
    }

    ggml_pipeline_allocate_descriptor_sets(ctx);

    ggml_vk_buffer_write(qx_buf, 0, qx, qx_sz);
    ggml_vk_buffer_write(y_buf, 0, y, y_sz);

    vk_context subctx = ggml_vk_create_context(ctx, ctx->compute_cmd_pool);
    ggml_vk_ctx_begin(ctx->device, subctx);
    if (mmq) {
        for (size_t i = 0; i < num_it; i++) {
            ggml_vk_quantize_q8_1(ctx, subctx, { y_buf, 0, y_sz }, { qy_buf, 0, qy_sz }, y_ne);
            ggml_vk_matmul(
                ctx, subctx, p, { qx_buf, 0, qx_sz }, { qy_buf, 0, qy_sz }, { d_buf, 0, d_sz }, { ctx->prealloc_split_k, 0, ctx->prealloc_size_split_k },
                m, n, k,
                k, k, m, k*m, k*n, m*n,
                split_k, batch, batch, batch, 1, 1, n
            );
        }
    } else {
        for (size_t i = 0; i < num_it; i++) {
            ggml_vk_matmul(
                ctx, subctx, p, { qx_buf, 0, qx_sz }, { y_buf, 0, y_sz }, { d_buf, 0, d_sz }, { ctx->prealloc_split_k, 0, ctx->prealloc_size_split_k },
                m, n, k,
                k, k, m, k*m, k*n, m*n,
                split_k, batch, batch, batch, 1, 1, n
            );
        }
    }
    ggml_vk_ctx_end(subctx);

    auto begin = std::chrono::high_resolution_clock::now();

    ggml_vk_submit(subctx, ctx->fence);
    VK_CHECK(ctx->device->device.waitForFences({ ctx->fence }, true, UINT64_MAX), "ggml_vk_test_dequant waitForFences", ctx->device);
    ctx->device->device.resetFences({ ctx->fence });
    ggml_vk_queue_command_pools_cleanup(ctx->device);

    auto end = std::chrono::high_resolution_clock::now();

    double time_ms = std::chrono::duration_cast<std::chrono::microseconds>(end-begin).count() / 1000.0;
    ggml_vk_buffer_read(d_buf, 0, d, d_sz);

    ggml_init_params iparams = {
        /*.mem_size   =*/ 1024*1024*1024,
        /*.mem_buffer =*/ NULL,
        /*.no_alloc   =*/ true,
    };

    ggml_context * ggml_ctx = ggml_init(iparams);

    ggml_tensor * src0_ggml = ggml_new_tensor_3d(ggml_ctx, quant, k, m, batch);
    ggml_tensor * src1_ggml = ggml_new_tensor_3d(ggml_ctx, GGML_TYPE_F32, k, n, batch);
    ggml_tensor * tensor_ggml = ggml_mul_mat(ggml_ctx, src0_ggml, src1_ggml);

    src0_ggml->data = qx;
    src1_ggml->data = y;
    tensor_ggml->data = d_chk;

    ggml_cgraph * cgraph = ggml_new_graph(ggml_ctx);
    ggml_build_forward_expand(cgraph, tensor_ggml);

    ggml_graph_compute_with_ctx(ggml_ctx, cgraph, 1);

    ggml_free(ggml_ctx);

    double avg_err = 0.0;
    int first_err_n = -1;
    int first_err_m = -1;
    int first_err_b = -1;

    for (size_t i = 0; i < m*n*batch; i++) {
        double err = std::fabs(d[i] - d_chk[i]);
        avg_err += err;

        if ((err > 0.05f || std::isnan(err)) && first_err_n == -1) {
            first_err_b = i / (m * n);
            first_err_n = (i % (m * n)) / m;
            first_err_m = (i % (m * n)) % m;
        }
    }

    avg_err /= m * n;

    double tflops = 2.0*m*n*k*batch*num_it / (time_ms / 1000.0) / (1000.0*1000.0*1000.0*1000.0);

    std::cerr << "TEST dequant matmul " << shname;
    if (mmq) {
        std::cerr << " mmq";
    }
    std::cerr << " m=" << m << " n=" << n << " k=" << k << " batch=" << batch << " split_k=" << split_k << " matmul " << time_ms / num_it << "ms " << tflops << " TFLOPS avg_err=" << avg_err << std::endl;

    if (avg_err > 0.01 || std::isnan(avg_err)) {
        std::cerr << "m = " << first_err_m << " n = " << first_err_n << " b = " << first_err_b << std::endl;
        std::cerr << "Actual result: " << std::endl << std::endl;
        ggml_vk_print_matrix_area(d, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);
        std::cerr << std::endl;
        std::cerr << "Expected result: " << std::endl << std::endl;
        ggml_vk_print_matrix_area(d_chk, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

        std::cerr << "src0: " << std::endl << std::endl;
        ggml_vk_print_matrix_area(x, GGML_TYPE_F32, k, m, first_err_m, first_err_n, first_err_b);
        std::cerr << std::endl;
        std::cerr << "src1: " << std::endl << std::endl;
        ggml_vk_print_matrix_area(y, GGML_TYPE_F32, k, n, first_err_m, first_err_n, first_err_b);

        if (split_k > 1) {
            float * split_k_buf = (float *) malloc(sizeof(float) * d_ne * split_k);
            ggml_vk_buffer_read(ctx->prealloc_split_k, 0, split_k_buf, sizeof(float) * d_ne * split_k);

            std::cerr << "d_buf0: " << std::endl << std::endl;
            ggml_vk_print_matrix_area(split_k_buf, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

            std::cerr << "d_buf1: " << std::endl << std::endl;
            ggml_vk_print_matrix_area(split_k_buf + d_ne, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

            std::cerr << "d_buf2: " << std::endl << std::endl;
            ggml_vk_print_matrix_area(split_k_buf + 2 * d_ne, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

            std::cerr << "d_buf3: " << std::endl << std::endl;
            ggml_vk_print_matrix_area(split_k_buf + 3 * d_ne, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

            free(split_k_buf);
        }
    }

    ggml_vk_destroy_buffer(qx_buf);
    ggml_vk_destroy_buffer(y_buf);
    ggml_vk_destroy_buffer(qy_buf);
    ggml_vk_destroy_buffer(d_buf);

    free(x);
    free(qx);
    free(y);
    free(d);
    free(d_chk);
}
#endif

static void ggml_vk_preallocate_buffers(ggml_backend_vk_context * ctx, vk_context subctx) {
#if defined(GGML_VULKAN_RUN_TESTS)
    const std::vector<size_t> vals {
        512, 512, 128,
        128, 512, 512,
        4096, 512, 4096,
        11008, 512, 4096,
        4096, 512, 11008,
        32000, 512, 4096,
        8, 8, 8,
        100, 46, 576,
        623, 111, 128,
        100, 46, 558,
        512, 1, 256,
        128, 110, 622,
        511, 511, 127,
        511, 511, 7,
        511, 511, 17,
        49, 49, 128,
        128, 49, 49,
        4096, 49, 4096,
    };
    const size_t num_it = 100;

    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q4_0);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q4_0);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q4_0);

    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q4_0, true);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q4_0, true);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q4_0, true);

    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q8_0);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q8_0);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q8_0);

    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q8_0, true);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q8_0, true);
    ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q8_0, true);

    abort();

    for (size_t i = 0; i < vals.size(); i += 3) {
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 0);
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 1);
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 2);
        std::cerr << '\n';
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 0);
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 1);
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 2);
        std::cerr << '\n';
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 0);
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 1);
        ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 2);
        std::cerr << '\n' << std::endl;

        if (vals[i + 2] % 32 == 0) {
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 0, GGML_TYPE_Q4_0);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 1, GGML_TYPE_Q4_0);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 2, GGML_TYPE_Q4_0);
            std::cerr << '\n';
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 0, GGML_TYPE_Q4_0);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 1, GGML_TYPE_Q4_0);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 2, GGML_TYPE_Q4_0);
            std::cerr << '\n';
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 0, GGML_TYPE_Q4_0);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 1, GGML_TYPE_Q4_0);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 2, GGML_TYPE_Q4_0);
            std::cerr << '\n' << std::endl;
        }

        if (vals[i + 2] % 256 == 0) {
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 0, GGML_TYPE_Q4_K);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 1, GGML_TYPE_Q4_K);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 2, GGML_TYPE_Q4_K);
            std::cerr << '\n';
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 0, GGML_TYPE_Q4_K);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 1, GGML_TYPE_Q4_K);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 2, GGML_TYPE_Q4_K);
            std::cerr << '\n';
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 0, GGML_TYPE_Q4_K);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 1, GGML_TYPE_Q4_K);
            ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 2, GGML_TYPE_Q4_K);
            std::cerr << '\n' << std::endl;
        }
    }

    GGML_ABORT("fatal error");
#endif

    if (subctx) {
        // Submit and wait for any pending work before reallocating the buffers
        ggml_vk_ctx_end(subctx);
        ggml_vk_submit(subctx, {});
        ctx->submit_pending = true;
        ggml_vk_synchronize(ctx);
        GGML_ASSERT(ctx->compute_ctx.expired());
        ggml_vk_ctx_begin(ctx->device, subctx);
        ctx->compute_ctx = subctx;
    }

    if (ctx->prealloc_x == nullptr || (ctx->prealloc_size_x > 0 && ctx->prealloc_x->size < ctx->prealloc_size_x)) {
        VK_LOG_MEMORY("ggml_vk_preallocate_buffers(x_size: " << ctx->prealloc_size_x << ")");
        // Resize buffer
        if (ctx->prealloc_x != nullptr) {
            ggml_vk_destroy_buffer(ctx->prealloc_x);
        }
        ctx->prealloc_x = ggml_vk_create_buffer_device(ctx->device, ctx->prealloc_size_x);
    }
    if (ctx->prealloc_y == nullptr || (ctx->prealloc_size_y > 0 && ctx->prealloc_y->size < ctx->prealloc_size_y)) {
        VK_LOG_MEMORY("ggml_vk_preallocate_buffers(y_size: " << ctx->prealloc_size_y << ")");
        // Resize buffer
        if (ctx->prealloc_y != nullptr) {
            ggml_vk_destroy_buffer(ctx->prealloc_y);
        }
        ctx->prealloc_y = ggml_vk_create_buffer_device(ctx->device, ctx->prealloc_size_y);
        ctx->prealloc_y_last_pipeline_used = nullptr;
        ctx->prealloc_y_last_tensor_used = nullptr;
        ctx->prealloc_y_last_decode_vector_staging = false;
    }
    if (ctx->prealloc_split_k == nullptr || (ctx->prealloc_size_split_k > 0 && ctx->prealloc_split_k->size < ctx->prealloc_size_split_k)) {
        VK_LOG_MEMORY("ggml_vk_preallocate_buffers(split_k_size: " << ctx->prealloc_size_split_k << ")");
        // Resize buffer
        if (ctx->prealloc_split_k != nullptr) {
            ggml_vk_destroy_buffer(ctx->prealloc_split_k);
        }
        ctx->prealloc_split_k = ggml_vk_create_buffer_device(ctx->device, ctx->prealloc_size_split_k);
    }
    if (ctx->prealloc_add_rms_partials == nullptr || (ctx->prealloc_size_add_rms_partials > 0 && ctx->prealloc_add_rms_partials->size < ctx->prealloc_size_add_rms_partials)) {
        VK_LOG_MEMORY("ggml_vk_preallocate_buffers(add_partials_size: " << ctx->prealloc_add_rms_partials << ")");
        // Resize buffer
        if (ctx->prealloc_add_rms_partials != nullptr) {
            ggml_vk_destroy_buffer(ctx->prealloc_add_rms_partials);
        }
        ctx->prealloc_add_rms_partials = ggml_vk_create_buffer_device(ctx->device, ctx->prealloc_size_add_rms_partials);
    }
}

static void ggml_vk_compute_forward(ggml_backend_vk_context* ctx, ggml_cgraph * cgraph, ggml_tensor* tensor, int tensor_idx, bool almost_ready);

// Returns true if node has enqueued work into the queue, false otherwise
// If submit is true the current all operations queued so far are being submitted to Vulkan to overlap cmdlist creation and GPU execution.
static bool ggml_vk_build_graph(ggml_backend_vk_context * ctx, ggml_cgraph * cgraph, int node_idx, ggml_tensor *node_begin, int node_idx_begin, bool last_node, bool almost_ready, bool submit){
    ggml_tensor * node = cgraph->nodes[node_idx];
    if (ggml_is_empty(node) || ggml_op_is_empty(node->op) || !node->buffer) {
        return false;
    }
    if ((node->flags & GGML_TENSOR_FLAG_COMPUTE) == 0) {
        return false;
    }

    VK_LOG_DEBUG("ggml_vk_build_graph(" << node << ", " << ggml_op_name(node->op) << ")");
    ctx->semaphore_idx = 0;

    ggml_tensor * src0 = node->src[0];
    ggml_tensor * src1 = node->src[1];
    ggml_tensor * src2 = node->src[2];
    ggml_tensor * src3 = node->src[3];

    // [TAG_HC_MIX_TAIL] not after multi_add_scale: the partials would be of the sum, not of the
    // scaled value the RMS_NORM reads
    if (node->op == GGML_OP_ADD && !ctx->fused_multi_add_scale) {
        int next_node_idx = node_idx + 1 + ctx->num_additional_fused_ops;
        if (next_node_idx < cgraph->n_nodes &&
            cgraph->nodes[next_node_idx]->op == GGML_OP_RMS_NORM &&
            cgraph->nodes[next_node_idx]->src[0] == cgraph->nodes[next_node_idx - 1] &&
            ggml_nrows(cgraph->nodes[next_node_idx]) == 1 &&
            ctx->device->add_rms_fusion &&
            !vk_fusion_veto(ctx, "add_rms")) {
            uint32_t size = ggml_vk_rms_partials_size(ctx, cgraph->nodes[node_idx]);
            ctx->do_add_rms_partials_offset_calculation = true;
            if (ctx->prealloc_size_add_rms_partials_offset + size <= ctx->prealloc_size_add_rms_partials) {
                ctx->do_add_rms_partials = true;
                if (ggml_vk_fusion_count_enabled()) {
                    ctx->fusion_count_add_rms++;
                }
                if (vk_fusion_list_enabled) {
                    // the ADD (or the whole multi_add chain) plus the RMS_NORM that consumes the partials
                    ggml_vk_fusion_list_report("add_rms", cgraph, node_idx, ctx->num_additional_fused_ops + 2);
                }
            }
        }
    }

    vk_context compute_ctx = ggml_vk_get_compute_ctx(ctx);

    {
        // This logic detects dependencies between modes in the graph and calls ggml_vk_sync_buffers
        // to synchronize them. This handles most "normal" synchronization when computing the graph, and when
        // there is no auxiliary memory use, it shouldn't be necessary to call ggml_vk_sync_buffers
        // outside of this logic. When a node uses one of the prealloc buffers for something like
        // dequantization or split_k, additional synchronization is needed between those passes.
        bool need_sync = false;

        // Check whether "node" requires synchronization. The node requires synchronization if it
        // overlaps in memory with another unsynchronized node and at least one of them is a write.
        // Destination nodes are checked against both the written/read lists. Source nodes are only
        // checked against the written list. Two nodes overlap in memory if they come from the same
        // buffer and the tensor or view ranges overlap.
        auto const &overlaps_unsynced = [&](const ggml_tensor *node, const std::vector<const ggml_tensor *> &unsynced_nodes) -> bool {
            if (unsynced_nodes.size() == 0) {
                return false;
            }
            auto n_base = vk_tensor_offset(node) + node->view_offs;
            auto n_size = ggml_nbytes(node);
            ggml_backend_vk_buffer_context * a_buf_ctx = (ggml_backend_vk_buffer_context *)node->buffer->context;
            vk_buffer a_buf = a_buf_ctx->dev_buffer;
            for (auto &other : unsynced_nodes) {
                ggml_backend_vk_buffer_context * o_buf_ctx = (ggml_backend_vk_buffer_context *)other->buffer->context;
                vk_buffer o_buf = o_buf_ctx->dev_buffer;
                if (a_buf == o_buf) {
                    auto o_base = vk_tensor_offset(other) + other->view_offs;
                    auto o_size = ggml_nbytes(other);

                    if ((o_base <= n_base && n_base < o_base + o_size) ||
                        (n_base <= o_base && o_base < n_base + n_size)) {
                        return true;
                    }
                }
            }
            return false;
        };

        // For all fused ops, check if the destination node or any of the source
        // nodes require synchronization.
        for (int32_t i = 0; i < ctx->num_additional_fused_ops + 1 && !need_sync; ++i) {
            const ggml_tensor *cur_node = cgraph->nodes[node_idx + i];
            // If the node actually writes to memory, then check if it needs to sync
            if (ctx->fused_ops_write_mask & (1 << i)) {
                if (overlaps_unsynced(cur_node, ctx->unsynced_nodes_read) || overlaps_unsynced(cur_node, ctx->unsynced_nodes_written)) {
                    need_sync = true;
                    break;
                }
            }
            for (uint32_t j = 0; j < GGML_MAX_SRC; ++j) {
                if (!cur_node->src[j]) {
                    continue;
                }
                if (overlaps_unsynced(cur_node->src[j], ctx->unsynced_nodes_written)) {
                    need_sync = true;
                    break;
                }
            }
            // A source the node writes through (ggml_gated_delta_net_ext) also conflicts with earlier reads.
            const ggml_tensor * mut = ggml_vk_mutated_src(cur_node);
            if (mut && overlaps_unsynced(mut, ctx->unsynced_nodes_read)) {
                need_sync = true;
                break;
            }
        }

        if (need_sync) {
            if (vk_enable_sync_logger) {
                std::cerr <<  "sync" << std::endl;
            }
            ctx->unsynced_nodes_written.clear();
            ctx->unsynced_nodes_read.clear();
            ggml_vk_sync_buffers(ctx, compute_ctx);

            if (vk_perf_logger_enabled && vk_perf_logger_concurrent) {
                ctx->query_node_idx[ctx->query_idx] = node_idx;
                compute_ctx->s->buffer->buf.writeTimestamp(vk::PipelineStageFlagBits::eAllCommands, ctx->query_pool, ctx->query_idx++);
                ggml_vk_sync_buffers(ctx, compute_ctx);
            }
        }
        // Add all fused nodes to the unsynchronized lists.
        for (int32_t i = 0; i < ctx->num_additional_fused_ops + 1; ++i) {
            const ggml_tensor *cur_node = cgraph->nodes[node_idx + i];
            // Multiple outputs could be written, e.g. in topk_moe. Add them all to the list.
            if (ctx->fused_ops_write_mask & (1 << i)) {
                ctx->unsynced_nodes_written.push_back(cur_node);
            }
            for (uint32_t j = 0; j < GGML_MAX_SRC; ++j) {
                if (!cur_node->src[j]) {
                    continue;
                }
                ctx->unsynced_nodes_read.push_back(cur_node->src[j]);
            }
            if (const ggml_tensor * mut = ggml_vk_mutated_src(cur_node)) {
                ctx->unsynced_nodes_written.push_back(mut);
            }
        }
    }
    if (vk_enable_sync_logger) {
        for (int i = 0; i < ctx->num_additional_fused_ops + 1; ++i) {
            auto *n = cgraph->nodes[node_idx + i];
            std::cerr << node_idx + i << " " << ggml_op_name(n->op) << " " <<  n->name;
            if (n->op == GGML_OP_GLU) {
                std::cerr << " " << ggml_glu_op_name(ggml_get_glu_op(n)) << " " << (n->src[1] ? "split" : "single") << " ";
            }
            if (n->op == GGML_OP_ROPE) {
                const int mode = ((const int32_t *) n->op_params)[2];
                std::cerr << " rope mode: " << mode;
            }
            std::cerr << std::endl;
        }
    }

    switch (node->op) {
    case GGML_OP_REPEAT:
        if (ctx->num_additional_fused_ops) {
            ggml_vk_hc_combine_dispatch_fused(ctx, compute_ctx, cgraph, node_idx);
        } else {
            ggml_vk_repeat(ctx, compute_ctx, src0, node);
        }

        break;
    case GGML_OP_REPEAT_BACK:
        ggml_vk_repeat_back(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_ACC:
    case GGML_OP_SET:
        ggml_vk_acc(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_GET_ROWS:
        if (ctx->fused_topk_qsa) {
            ggml_vk_topk_qsa(ctx, compute_ctx, cgraph, node_idx);
        } else {
            ggml_vk_get_rows(ctx, compute_ctx, src0, src1, node);
        }

        break;
    case GGML_OP_GET_ROWS_BACK:
        ggml_vk_get_rows_back(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_ADD:
        if (ctx->fused_gdn_pre) {
            ggml_vk_add_softplus_mul_dispatch_fused(ctx, compute_ctx, cgraph, node_idx);
        } else if (ctx->num_additional_fused_ops) {
            ggml_vk_multi_add(ctx, compute_ctx, cgraph, node_idx);
        } else {
            ggml_vk_add(ctx, compute_ctx, src0, src1, node);
        }
        break;
    case GGML_OP_OUT_PROD:
        ggml_vk_out_prod(ctx, compute_ctx, src0, src1, node);
        break;
    case GGML_OP_SUB:
        ggml_vk_sub(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_MUL:
        if (ctx->num_additional_fused_ops) {
            ggml_vk_snake_dispatch_fused(ctx, compute_ctx, cgraph, node_idx);
        } else {
            ggml_vk_mul(ctx, compute_ctx, src0, src1, node);
        }

        break;
    case GGML_OP_DIV:
        ggml_vk_div(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_ADD_ID:
        ggml_vk_add_id(ctx, compute_ctx, src0, src1, src2, node);

        break;
    case GGML_OP_CONCAT:
        if (ctx->fused_concat_ssm_conv) {
            ggml_vk_ssm_conv_split(ctx, compute_ctx, cgraph, node_idx);   // [TAG_CONV_INPUT_SPLIT]
        } else {
            ggml_vk_concat(ctx, compute_ctx, src0, src1, node);
        }

        break;
    case GGML_OP_UPSCALE:
        ggml_vk_upscale(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_ADD1:
        ggml_vk_add1(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_ARANGE:
        ggml_vk_arange(ctx, compute_ctx, node);

        break;
    case GGML_OP_FILL:
        ggml_vk_fill(ctx, compute_ctx, node);

        break;
    case GGML_OP_SCALE:
        if (ctx->fused_scale_silu) {
            // [TAG_HC_MIX_TAIL] SCALE + SILU: the scale's params, the SILU's destination
            ggml_vk_scale(ctx, compute_ctx, src0, cgraph->nodes[node_idx + 1], node);
        } else {
            ggml_vk_scale(ctx, compute_ctx, src0, node);
        }

        break;
    case GGML_OP_SQR:
        ggml_vk_sqr(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_SQRT:
        ggml_vk_sqrt(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_SIN:
        ggml_vk_sin(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_COS:
        ggml_vk_cos(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_LOG:
        ggml_vk_log(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_TRI:
        ggml_vk_tri(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_DIAG:
        ggml_vk_diag(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_CLAMP:
        ggml_vk_clamp(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_PAD:
        ggml_vk_pad(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_PAD_REFLECT_1D:
        ggml_vk_pad_reflect_1d(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_ROLL:
        ggml_vk_roll(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_CPY:
    case GGML_OP_CONT:
    case GGML_OP_DUP:
        ggml_vk_cpy(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_SET_ROWS:
        ggml_vk_set_rows(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_SILU_BACK:
        ggml_vk_silu_back(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_NORM:
        ggml_vk_norm(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_GROUP_NORM:
        ggml_vk_group_norm(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_RMS_NORM:
        ggml_vk_rms_norm(ctx, compute_ctx, cgraph, node_idx, (float *)node->op_params);
        break;
    case GGML_OP_RMS_NORM_BACK:
        ggml_vk_rms_norm_back(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_L2_NORM:
        ggml_vk_l2_norm(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_UNARY:
        if (ctx->fused_topk_moe_mode != TOPK_MOE_COUNT) {
            ggml_vk_topk_moe(ctx, compute_ctx, cgraph, node_idx);
            break;
        }
        if (ctx->fused_mul_sigmoid) {
            ggml_vk_sigmoid_mul_dispatch_fused(ctx, compute_ctx, cgraph, node_idx);
            break;
        }

        switch (ggml_get_unary_op(node)) {
        case GGML_UNARY_OP_ELU:
        case GGML_UNARY_OP_EXP:
        case GGML_UNARY_OP_EXPM1:
        case GGML_UNARY_OP_SILU:
        case GGML_UNARY_OP_GELU:
        case GGML_UNARY_OP_GELU_ERF:
        case GGML_UNARY_OP_GELU_QUICK:
        case GGML_UNARY_OP_RELU:
        case GGML_UNARY_OP_NEG:
        case GGML_UNARY_OP_TANH:
        case GGML_UNARY_OP_SIGMOID:
        case GGML_UNARY_OP_HARDSIGMOID:
        case GGML_UNARY_OP_HARDSWISH:
        case GGML_UNARY_OP_ABS:
        case GGML_UNARY_OP_SOFTPLUS:
        case GGML_UNARY_OP_STEP:
        case GGML_UNARY_OP_ROUND:
        case GGML_UNARY_OP_CEIL:
        case GGML_UNARY_OP_FLOOR:
        case GGML_UNARY_OP_TRUNC:
        case GGML_UNARY_OP_SGN:
            ggml_vk_unary(ctx, compute_ctx, src0, node);
            break;
        case GGML_UNARY_OP_XIELU:
            ggml_vk_xielu(ctx, compute_ctx, src0, node);
            break;
        default:
            return false;
        }
        break;
    case GGML_OP_GLU:
        switch (ggml_get_glu_op(node)) {
        case GGML_GLU_OP_GEGLU:
        case GGML_GLU_OP_REGLU:
        case GGML_GLU_OP_SWIGLU:
        case GGML_GLU_OP_SWIGLU_OAI:
        case GGML_GLU_OP_GEGLU_ERF:
        case GGML_GLU_OP_GEGLU_QUICK:
            ggml_vk_glu(ctx, compute_ctx, src0, src1, node);
            break;
        default:
            return false;
        }
        break;
    case GGML_OP_DIAG_MASK_INF:
        ggml_vk_diag_mask_inf(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_SOFT_MAX:
        if (ctx->fused_topk_moe_mode != TOPK_MOE_COUNT) {
            ggml_vk_topk_moe(ctx, compute_ctx, cgraph, node_idx);
        } else {
            ggml_vk_soft_max(ctx, compute_ctx, src0, src1, src2, node);
        }

        break;
    case GGML_OP_SOFT_MAX_BACK:
        ggml_vk_soft_max_back(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_ROPE:
        ggml_vk_rope(ctx, compute_ctx, cgraph, node_idx, false);

        break;
    case GGML_OP_ROPE_BACK:
        ggml_vk_rope(ctx, compute_ctx, cgraph, node_idx, true);

        break;
    case GGML_OP_ARGSORT:
        if (ctx->fused_topk_moe_mode != TOPK_MOE_COUNT) {
            ggml_vk_topk_moe(ctx, compute_ctx, cgraph, node_idx);
        } else {
            ggml_vk_argsort(ctx, compute_ctx, src0, node);
        }

        break;
    case GGML_OP_TOP_K:
        ggml_vk_topk(ctx, compute_ctx, src0, node);

        break;
    // [TAG_QSA_FUSED_SELECT] one node, three live srcs; no fusion bookkeeping and no alias veto
    case GGML_OP_QSA_TOP_K:
        ggml_vk_qsa_top_k(ctx, compute_ctx, node);

        break;
    case GGML_OP_KQ_MASK:
        ggml_vk_kq_mask(ctx, compute_ctx, node);

        break;
    // [TAG_QSA_COMPACT_BIAS]
    case GGML_OP_QSA_BIAS:
        ggml_vk_qsa_bias(ctx, compute_ctx, node);

        break;
    case GGML_OP_SUM:
        ggml_vk_sum(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_SUM_ROWS:
        ggml_vk_sum_rows(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_CUMSUM:
        ggml_vk_cumsum(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_MEAN:
        ggml_vk_mean(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_ARGMAX:
        ggml_vk_argmax(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_CROSS_ENTROPY_LOSS:
        ggml_vk_cross_entropy_loss(ctx, compute_ctx, node);

        break;
    case GGML_OP_CROSS_ENTROPY_LOSS_BACK:
        ggml_vk_cross_entropy_loss_back(ctx, compute_ctx, node);

        break;
    case GGML_OP_COUNT_EQUAL:
        ggml_vk_count_equal(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_SOLVE_TRI:
        ggml_vk_solve_tri(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_IM2COL:
        ggml_vk_im2col(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_IM2COL_3D:
        ggml_vk_im2col_3d(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_TIMESTEP_EMBEDDING:
        ggml_vk_timestep_embedding(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_COL2IM_1D:
        ggml_vk_col2im_1d(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_CONV_TRANSPOSE_1D:
        ggml_vk_conv_transpose_1d(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_POOL_1D:
        ggml_vk_pool_1d(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_POOL_2D:
        ggml_vk_pool_2d(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_CONV_2D:
    case GGML_OP_CONV_TRANSPOSE_2D:
        ggml_vk_conv_2d(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_CONV_3D:
        ggml_vk_conv_3d(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_CONV_2D_DW:
        ggml_vk_conv_2d_dw(ctx, compute_ctx, src0, src1, node);

        break;
    case GGML_OP_LEAKY_RELU:
        ggml_vk_leaky_relu(ctx, compute_ctx, src0, node);

        break;
    case GGML_OP_MUL_MAT:
        ggml_vk_mul_mat(ctx, compute_ctx, cgraph, node_idx);

        break;
    case GGML_OP_MUL_MAT_ID:
        ggml_vk_mul_mat_id(ctx, compute_ctx, cgraph, node_idx);

        break;
    case GGML_OP_MUL_MAT_ROWS: // [TAG_QSA_POOL_REMAP]
        ggml_vk_mul_mat_rows(ctx, compute_ctx, cgraph, node_idx);

        break;
    case GGML_OP_QSA_SCORE: // [TAG_QSA_SCORE_EPILOGUE]
        ggml_vk_qsa_score(ctx, compute_ctx, node);

        break;

    case GGML_OP_FLASH_ATTN_EXT:
        ggml_vk_flash_attn(ctx, compute_ctx, src0, src1, src2, src3, node->src[4], node->src[5], node);

        break;

    case GGML_OP_RWKV_WKV6:
        ggml_vk_rwkv_wkv6(ctx, compute_ctx, node);

        break;

    case GGML_OP_RWKV_WKV7:
        ggml_vk_rwkv_wkv7(ctx, compute_ctx, node);

        break;

    case GGML_OP_GATED_LINEAR_ATTN:
        ggml_vk_gated_linear_attn(ctx, compute_ctx, node);

        break;

    case GGML_OP_LIGHTNING_INDEXER:
        ggml_vk_lightning_indexer(ctx, compute_ctx, node);

        break;

    case GGML_OP_GATED_DELTA_NET:
        ggml_vk_gated_delta_net(ctx, compute_ctx, node);

        break;

    case GGML_OP_SSM_SCAN:
        ggml_vk_ssm_scan(ctx, compute_ctx, node);

        break;

    case GGML_OP_SSM_CONV:
        ggml_vk_ssm_conv(ctx, compute_ctx, cgraph, node_idx);

        break;

    case GGML_OP_OPT_STEP_ADAMW:
        ggml_vk_opt_step_adamw(ctx, compute_ctx, node);

        break;

    case GGML_OP_OPT_STEP_SGD:
        ggml_vk_opt_step_sgd(ctx, compute_ctx, src0, src1, src2, node);

        break;
    default:
        return false;
    }

    ctx->tensor_ctxs[node_idx] = compute_ctx;

#if defined(GGML_VULKAN_CHECK_RESULTS)
    // Force context reset on each node so that each tensor ends up in its own context
    // and can be run and compared to its CPU equivalent separately
    last_node = true;
#endif

    if (submit || last_node) {
        ggml_vk_ctx_end(compute_ctx);

        // TODO probably it'd be better to pass a exit_node flag to ggml_vk_compute_forward
        if (last_node) {
            compute_ctx->exit_tensor_idx = node_idx_begin;
        }
        else {
            compute_ctx->exit_tensor_idx = -1;
        }

        ctx->compute_ctx.reset();

        ggml_vk_compute_forward(ctx, cgraph, node_begin, node_idx_begin, almost_ready);
    }
    return true;
}

static void ggml_vk_compute_forward(ggml_backend_vk_context * ctx, ggml_cgraph * cgraph, ggml_tensor * tensor, int tensor_idx, bool almost_ready = false) {
    GGML_UNUSED(cgraph);
    GGML_UNUSED(tensor);

    VK_LOG_DEBUG("ggml_vk_compute_forward(" << tensor << ", name=" << tensor->name << ", op=" << ggml_op_name(tensor->op) << ", type=" << tensor->type << ", ne0=" << tensor->ne[0] << ", ne1=" << tensor->ne[1] << ", ne2=" << tensor->ne[2] << ", ne3=" << tensor->ne[3] << ", nb0=" << tensor->nb[0] << ", nb1=" << tensor->nb[1] << ", nb2=" << tensor->nb[2] << ", nb3=" << tensor->nb[3] << ", view_src=" << tensor->view_src << ", view_offs=" << tensor->view_offs << ")");

    vk_context subctx = ctx->tensor_ctxs[tensor_idx].lock();

    // Only run if ctx hasn't been submitted yet
    if (!subctx->seqs.empty()) {
#ifdef GGML_VULKAN_CHECK_RESULTS
        ggml_vk_check_results_0(ctx, cgraph, tensor_idx);
#endif

        // Do staging buffer copies
        for (auto& cpy : subctx->in_memcpys) {
            memcpy(cpy.dst, cpy.src, cpy.n);
        }

        for (auto& mset : subctx->memsets) {
            memset(mset.dst, mset.val, mset.n);
        }

        int64_t prof_t_submit_us = 0;
        if (ggml_vk_sched_prof_enabled()) {
            prof_t_submit_us = ggml_time_us();
        }

        if (ctx->device->serialize_submissions) {
            ggml_vk_submit(subctx, ctx->fence);
        } else if (almost_ready && !ctx->almost_ready_fence_pending) {
            ggml_vk_submit(subctx, ctx->almost_ready_fence);
            ctx->almost_ready_fence_pending = true;
        } else {
            ggml_vk_submit(subctx, {});
        }
        ctx->submit_pending = true;

        if (ggml_vk_sched_prof_enabled()) {
            ctx->sched_prof_submit_us += ggml_time_us() - prof_t_submit_us;
        }

#ifdef GGML_VULKAN_CHECK_RESULTS
        ggml_vk_synchronize(ctx);
        ggml_vk_check_results_1(ctx, cgraph, tensor_idx);
#endif
    }

    if (tensor_idx == subctx->exit_tensor_idx) {
        // Do staging buffer copies
        for (auto& cpy : subctx->out_memcpys) {
            memcpy(cpy.dst, cpy.src, cpy.n);
        }
        subctx->in_memcpys.clear();
        subctx->out_memcpys.clear();
        subctx->memsets.clear();
    }
}

// Clean up after graph processing is done
static void ggml_vk_graph_cleanup(ggml_backend_vk_context * ctx) {
    VK_LOG_DEBUG("ggml_vk_graph_cleanup()");
    ctx->prealloc_y_last_pipeline_used = {};
    ctx->prealloc_y_last_tensor_used = nullptr;
    ctx->prealloc_y_last_decode_vector_staging = false;

    ctx->unsynced_nodes_written.clear();
    ctx->unsynced_nodes_read.clear();
    ctx->prealloc_x_need_sync = ctx->prealloc_y_need_sync = ctx->prealloc_split_k_need_sync = false;

    ggml_vk_command_pool_cleanup(ctx->device, ctx->compute_cmd_pool);
    if (ctx->device->async_use_transfer_queue) {
        ggml_vk_command_pool_cleanup(ctx->device, ctx->transfer_cmd_pool);
    }

    for (size_t i = 0; i < ctx->gc.semaphores.size(); i++) {
        ctx->device->device.destroySemaphore({ ctx->gc.semaphores[i].s });
    }
    ctx->gc.semaphores.clear();

    for (size_t i = 0; i < ctx->gc.tl_semaphores.size(); i++) {
        ctx->device->device.destroySemaphore({ ctx->gc.tl_semaphores[i].s });
    }
    ctx->gc.tl_semaphores.clear();
    ctx->semaphore_idx = 0;

    ctx->event_idx = 0;

    for (auto& event : ctx->gc.events) {
        ctx->device->device.resetEvent(event);
    }

    ctx->tensor_ctxs.clear();
    ctx->gc.contexts.clear();
    ctx->pipeline_descriptor_set_requirements = 0;
    ctx->descriptor_set_idx = 0;
}

// Clean up on backend free
static void ggml_vk_cleanup(ggml_backend_vk_context * ctx) {
    VK_LOG_DEBUG("ggml_vk_cleanup(" << ctx->name << ")");
    // discard any unsubmitted command buffers
    ctx->compute_ctx.reset();
    // wait for any pending command buffers to finish
    ggml_vk_synchronize(ctx);

    ggml_vk_graph_cleanup(ctx);

    ggml_vk_destroy_buffer(ctx->prealloc_x);
    ggml_vk_destroy_buffer(ctx->prealloc_y);
    ggml_vk_destroy_buffer(ctx->prealloc_split_k);
    ggml_vk_destroy_buffer(ctx->prealloc_add_rms_partials);
    ggml_vk_destroy_buffer(ctx->sync_staging);
    ctx->expert_occ_pending.clear();                  // [TAG_VK_EXPERT_OCC]
    ggml_vk_destroy_buffer(ctx->expert_occ_staging);  // [TAG_VK_EXPERT_OCC]

    ctx->prealloc_y_last_pipeline_used = nullptr;
    ctx->prealloc_y_last_tensor_used = nullptr;
    ctx->prealloc_y_last_decode_vector_staging = false;

    ctx->prealloc_size_x = 0;
    ctx->prealloc_size_y = 0;
    ctx->prealloc_size_split_k = 0;
    ctx->prealloc_size_qsa_hint      = 0;     // [TAG_QSA_SCRATCH]
    ctx->prealloc_x_qsa_presized     = false; // [TAG_QSA_SCRATCH]
    ctx->prealloc_x_qsa_range_warned = false; // [TAG_QSA_SCRATCH]

    for (auto& event : ctx->gc.events) {
        ctx->device->device.destroyEvent(event);
    }
    ctx->gc.events.clear();

    ctx->device->device.destroyFence(ctx->fence);
    ctx->device->device.destroyFence(ctx->almost_ready_fence);

    for (auto& pool : ctx->descriptor_pools) {
        ctx->device->device.destroyDescriptorPool(pool);
    }
    ctx->descriptor_pools.clear();
    ctx->descriptor_sets.clear();
    ctx->descriptor_set_bindings.clear(); // [TAG_UP29280]

    ctx->compute_cmd_pool.destroy(ctx->device->device);
    if (ctx->device->async_use_transfer_queue) {
        ctx->device->device.destroySemaphore(ctx->transfer_semaphore.s);

        ctx->transfer_cmd_pool.destroy(ctx->device->device);
    }
    if (vk_perf_logger_enabled) {
        ctx->perf_logger->print_timings(true);
    }
}

static int ggml_vk_get_device_count() {
    ggml_vk_instance_init();

    return vk_instance.device_indices.size();
}

static void ggml_vk_get_device_description(int device, char * description, size_t description_size) {
    ggml_vk_instance_init();

    std::vector<vk::PhysicalDevice> devices = vk_instance.instance.enumeratePhysicalDevices();

    vk::PhysicalDeviceProperties props;
    devices[device].getProperties(&props);

    snprintf(description, description_size, "%s", props.deviceName.data());
}

// backend interface

#define UNUSED GGML_UNUSED

// device backend

static bool ggml_backend_buffer_is_vk(ggml_backend_buffer_t buffer) {
    return buffer->buft->iface.get_name == ggml_backend_vk_buffer_type_name;
}

static void ggml_backend_vk_buffer_free_buffer(ggml_backend_buffer_t buffer) {
    VK_LOG_MEMORY("ggml_backend_vk_buffer_free_buffer()");
    ggml_backend_vk_buffer_context * ctx = (ggml_backend_vk_buffer_context *)buffer->context;
    ggml_vk_destroy_buffer(ctx->dev_buffer);
    delete ctx;
}

static void * ggml_backend_vk_buffer_get_base(ggml_backend_buffer_t buffer) {
    return vk_ptr_base;

    UNUSED(buffer);
}

static enum ggml_status ggml_backend_vk_buffer_init_tensor(ggml_backend_buffer_t buffer, ggml_tensor * tensor) {
    VK_LOG_DEBUG("ggml_backend_vk_buffer_init_tensor(" << buffer << " (" << buffer->context << "), " << tensor << ")");
    if (tensor->view_src != nullptr) {
        GGML_ASSERT(tensor->view_src->buffer->buft == buffer->buft);
    }
    return GGML_STATUS_SUCCESS;
}

static void ggml_backend_vk_buffer_memset_tensor(ggml_backend_buffer_t buffer, ggml_tensor * tensor, uint8_t value, size_t offset, size_t size) {
    VK_LOG_DEBUG("ggml_backend_vk_buffer_memset_tensor(" << buffer << ", " << tensor << ", " << value << ", " << offset << ", " << size << ")");
    ggml_backend_vk_buffer_context * buf_ctx = (ggml_backend_vk_buffer_context *)buffer->context;
    vk_buffer buf = buf_ctx->dev_buffer;

    if (size == 0) {
        return;
    }

    uint32_t val32 = (uint32_t)value * 0x01010101;
    ggml_vk_buffer_memset(buf, vk_tensor_offset(tensor) + tensor->view_offs + offset, val32, size);
}

static void ggml_backend_vk_buffer_set_tensor(ggml_backend_buffer_t buffer, ggml_tensor * tensor, const void * data, size_t offset, size_t size) {
    VK_LOG_DEBUG("ggml_backend_vk_buffer_set_tensor(" << buffer << ", " << tensor << ", " << data << ", " << offset << ", " << size << ")");
    ggml_backend_vk_buffer_context * buf_ctx = (ggml_backend_vk_buffer_context *)buffer->context;
    vk_buffer buf = buf_ctx->dev_buffer;

    if (size == 0) {
        return;
    }

    ggml_vk_buffer_write(buf, vk_tensor_offset(tensor) + tensor->view_offs + offset, data, size);
}

static void ggml_backend_vk_buffer_set_tensor_2d(ggml_backend_buffer_t buffer, ggml_tensor * tensor, const void * data, size_t offset,
                                                 size_t size, size_t n_copies, size_t stride_tensor, size_t stride_data) {
    VK_LOG_DEBUG("ggml_backend_vk_buffer_set_tensor_2d(" << buffer << ", " << tensor << ", " << data << ", " << offset << ", " << size << ", " <<
                 n_copies << ", " << stride_tensor << ", " << stride_data << ")");
    ggml_backend_vk_buffer_context * buf_ctx = (ggml_backend_vk_buffer_context *)buffer->context;
    vk_buffer buf = buf_ctx->dev_buffer;

    if (size == 0) {
        return;
    }

    ggml_vk_buffer_write_2d(buf, vk_tensor_offset(tensor) + tensor->view_offs + offset, data, stride_data, stride_tensor, size, n_copies);
}

static void ggml_backend_vk_buffer_get_tensor(ggml_backend_buffer_t buffer, const ggml_tensor * tensor, void * data, size_t offset, size_t size) {
    VK_LOG_DEBUG("ggml_backend_vk_buffer_get_tensor(" << buffer << ", " << tensor << ", " << data << ", " << offset << ", " << size << ")");
    ggml_backend_vk_buffer_context * buf_ctx = (ggml_backend_vk_buffer_context *)buffer->context;

    if (size == 0) {
        return;
    }

    vk_buffer buf = buf_ctx->dev_buffer;

    ggml_vk_buffer_read(buf, vk_tensor_offset(tensor) + tensor->view_offs + offset, data, size);
}

static void ggml_backend_vk_buffer_get_tensor_2d(ggml_backend_buffer_t buffer, const ggml_tensor * tensor, void * data, size_t offset,
                                                 size_t size, size_t n_copies, size_t stride_tensor, size_t stride_data) {
    VK_LOG_DEBUG("ggml_backend_vk_buffer_get_tensor_2d(" << buffer << ", " << tensor << ", " << data << ", " << offset << ", " << size << ", " <<
                 n_copies << ", " << stride_tensor << ", " << stride_data << ")");
    ggml_backend_vk_buffer_context * buf_ctx = (ggml_backend_vk_buffer_context *)buffer->context;

    if (size == 0) {
        return;
    }

    vk_buffer buf = buf_ctx->dev_buffer;

    ggml_vk_buffer_read_2d(buf, vk_tensor_offset(tensor) + tensor->view_offs + offset, data, stride_tensor, stride_data, size, n_copies);
}

static bool ggml_backend_vk_buffer_cpy_tensor(ggml_backend_buffer_t buffer, const ggml_tensor * src, ggml_tensor * dst) {
    if (ggml_nbytes(src) == 0) {
        return true;
    }

    if (ggml_backend_buffer_is_vk(src->buffer)) {
        ggml_backend_vk_buffer_context * src_buf_ctx = (ggml_backend_vk_buffer_context *)src->buffer->context;
        ggml_backend_vk_buffer_context * dst_buf_ctx = (ggml_backend_vk_buffer_context *)dst->buffer->context;

        vk_buffer src_buf = src_buf_ctx->dev_buffer;
        vk_buffer dst_buf = dst_buf_ctx->dev_buffer;

        ggml_vk_buffer_copy(dst_buf, vk_tensor_offset(dst) + dst->view_offs, src_buf, vk_tensor_offset(src) + src->view_offs, ggml_nbytes(src));

        return true;
    }
    return false;

    UNUSED(buffer);
}

static void ggml_backend_vk_buffer_clear(ggml_backend_buffer_t buffer, uint8_t value) {
    ggml_backend_vk_buffer_context * ctx = (ggml_backend_vk_buffer_context *)buffer->context;

    ggml_vk_buffer_memset(ctx->dev_buffer, 0, value, buffer->size);
}

static ggml_backend_buffer_i ggml_backend_vk_buffer_interface = {
    /* .free_buffer     = */ ggml_backend_vk_buffer_free_buffer,
    /* .get_base        = */ ggml_backend_vk_buffer_get_base,
    /* .init_tensor     = */ ggml_backend_vk_buffer_init_tensor,
    /* .memset_tensor   = */ ggml_backend_vk_buffer_memset_tensor,
    /* .set_tensor      = */ ggml_backend_vk_buffer_set_tensor,
    /* .get_tensor      = */ ggml_backend_vk_buffer_get_tensor,
    /* .set_tensor_2d   = */ ggml_backend_vk_buffer_set_tensor_2d,
    /* .get_tensor_2d   = */ ggml_backend_vk_buffer_get_tensor_2d,
    /* .cpy_tensor      = */ ggml_backend_vk_buffer_cpy_tensor,
    /* .clear           = */ ggml_backend_vk_buffer_clear,
    /* .reset           = */ NULL,
};

// vk buffer type
static const char * ggml_backend_vk_buffer_type_name(ggml_backend_buffer_type_t buft) {
    ggml_backend_vk_buffer_type_context * ctx = (ggml_backend_vk_buffer_type_context *)buft->context;

    return ctx->name.c_str();
}

static ggml_backend_buffer_t ggml_backend_vk_buffer_type_alloc_buffer(ggml_backend_buffer_type_t buft, size_t size) {
    VK_LOG_MEMORY("ggml_backend_vk_buffer_type_alloc_buffer(" << size << ")");
    ggml_backend_vk_buffer_type_context * ctx = (ggml_backend_vk_buffer_type_context *) buft->context;

    vk_buffer dev_buffer = nullptr;
    try {
        dev_buffer = ggml_vk_create_buffer_device(ctx->device, size);
    } catch (const vk::SystemError& e) {
        return nullptr;
    }

    ggml_backend_vk_buffer_context * bufctx = new ggml_backend_vk_buffer_context(ctx->device, std::move(dev_buffer), ctx->name);

    return ggml_backend_buffer_init(buft, ggml_backend_vk_buffer_interface, bufctx, size);
}

static size_t ggml_backend_vk_buffer_type_get_alignment(ggml_backend_buffer_type_t buft) {
    ggml_backend_vk_buffer_type_context * ctx = (ggml_backend_vk_buffer_type_context *) buft->context;
    return ctx->device->properties.limits.minStorageBufferOffsetAlignment;
}

static size_t ggml_backend_vk_buffer_type_get_max_size(ggml_backend_buffer_type_t buft) {
    ggml_backend_vk_buffer_type_context * ctx = (ggml_backend_vk_buffer_type_context *) buft->context;
    return ctx->device->suballocation_block_size;
}

static size_t ggml_backend_vk_buffer_type_get_alloc_size(ggml_backend_buffer_type_t buft, const ggml_tensor * tensor) {
    return ggml_nbytes(tensor);

    UNUSED(buft);
}

ggml_backend_buffer_type_t ggml_backend_vk_buffer_type(size_t dev_num) {
    ggml_vk_instance_init();

    VK_LOG_DEBUG("ggml_backend_vk_buffer_type(" << dev_num << ")");

    vk_device dev = ggml_vk_get_device(dev_num);

    return &dev->buffer_type;
}

// host buffer type

static const char * ggml_backend_vk_host_buffer_type_name(ggml_backend_buffer_type_t buft) {
    return GGML_VK_NAME "_Host";

    UNUSED(buft);
}

static void ggml_backend_vk_host_buffer_free_buffer(ggml_backend_buffer_t buffer) {
    VK_LOG_MEMORY("ggml_backend_vk_host_buffer_free_buffer()");
    ggml_vk_host_free(vk_instance.devices[0], buffer->context);
}

static ggml_backend_buffer_t ggml_backend_vk_host_buffer_type_alloc_buffer(ggml_backend_buffer_type_t buft, size_t size) {
    VK_LOG_MEMORY("ggml_backend_vk_host_buffer_type_alloc_buffer(" << size << ")");

    size += 32;  // Behave like the CPU buffer type
    void * ptr = nullptr;
    try {
        ptr = ggml_vk_host_malloc(vk_instance.devices[0], size);
    } catch (vk::SystemError& e) {
        GGML_LOG_WARN("ggml_vulkan: Failed to allocate pinned memory (%s)\n", e.what());
        // fallback to cpu buffer
        return ggml_backend_buft_alloc_buffer(ggml_backend_cpu_buffer_type(), size);
    }

    ggml_backend_buffer_t buffer = ggml_backend_cpu_buffer_from_ptr(ptr, size);
    buffer->buft = buft;
    buffer->iface.free_buffer = ggml_backend_vk_host_buffer_free_buffer;

    return buffer;

    UNUSED(buft);
}

static size_t ggml_backend_vk_host_buffer_type_get_alignment(ggml_backend_buffer_type_t buft) {
    return vk_instance.devices[0]->properties.limits.minMemoryMapAlignment;

    UNUSED(buft);
}

static size_t ggml_backend_vk_host_buffer_type_get_max_size(ggml_backend_buffer_type_t buft) {
    return vk_instance.devices[0]->suballocation_block_size;

    UNUSED(buft);
}

// Should be changed to return device-specific host buffer type
// but that probably requires changes in llama.cpp
ggml_backend_buffer_type_t ggml_backend_vk_host_buffer_type() {
    static struct ggml_backend_buffer_type ggml_backend_vk_buffer_type_host = {
        /* .iface    = */ {
            /* .get_name         = */ ggml_backend_vk_host_buffer_type_name,
            /* .alloc_buffer     = */ ggml_backend_vk_host_buffer_type_alloc_buffer,
            /* .get_alignment    = */ ggml_backend_vk_host_buffer_type_get_alignment,
            /* .get_max_size     = */ ggml_backend_vk_host_buffer_type_get_max_size,
            /* .get_alloc_size   = */ ggml_backend_cpu_buffer_type()->iface.get_alloc_size,
            /* .is_host          = */ ggml_backend_cpu_buffer_type()->iface.is_host,
        },
        /* .device   = */ ggml_backend_reg_dev_get(ggml_backend_vk_reg(), 0),
        /* .context  = */ nullptr,
    };

    // Make sure device 0 is initialized
    ggml_vk_instance_init();
    ggml_vk_get_device(0);

    return &ggml_backend_vk_buffer_type_host;
}


// backend

static const char * ggml_backend_vk_name(ggml_backend_t backend) {
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;

    return ctx->name.c_str();
}

static void ggml_backend_vk_free(ggml_backend_t backend) {
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;
    VK_LOG_DEBUG("ggml_backend_vk_free(" << ctx->name << ")");

    ggml_vk_cleanup(ctx);

    delete ctx;
    delete backend;
}

static ggml_backend_buffer_type_t ggml_backend_vk_get_default_buffer_type(ggml_backend_t backend) {
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;

    return &ctx->device->buffer_type;
}

// [TAG_ASYNC_READ_UMA]
// The UMA direct-read shortcut in ggml_vk_buffer_read_2d_async leaves a host memcpy queued on the
// compute context (subctx->out_memcpys) instead of recording a vkCmdCopyBuffer. That list is only
// drained by ggml_vk_synchronize, and only while ctx->compute_ctx still points at the context that
// holds it. Anything that records further work into the same context breaks both halves of that:
//
//   * graph compute reuses ctx->compute_ctx, then ends it, submits it and resets ctx->compute_ctx
//     at its first submit boundary. ggml_vk_compute_forward only drains out_memcpys when the
//     submitted batch is the graph's *exit* batch, so on any earlier batch the queued read is
//     stranded in a context nothing will look at again and the destination is never written; on the
//     exit batch it is executed immediately after vkQueueSubmit, without waiting for the fence.
//   * the memcpy reads the live source buffer at drain time, so dispatches recorded after it can
//     overwrite the bytes before the host copies them.
//   * ggml_backend_vk_event_record does the same end/submit/reset to signal an event, with the
//     same result: the queued read ends up in a context ggml_vk_synchronize no longer looks at.
//
// Every entry point that can end or submit ctx->compute_ctx therefore calls
// ggml_vk_flush_pending_host_reads first: graph compute, set_tensor_2d_async,
// cpy_tensor_async and event_record.  (ggml_vk_cleanup discards the context outright, but it
// only runs on backend free, when no destination is still worth writing.)
//
// llama.cpp reaches this ordering: llama_context::decode extracts logits / embeddings / the MTP
// h_nextn rows with ggml_backend_tensor_get_async at the end of each ubatch iteration and only
// synchronizes after the last one, so a multi-ubatch batch does get_async(A), graph_compute(B).
// Fence the pending reads off before recording anything else. In the ordinary
// graph_compute -> get_async... -> synchronize sequence nothing is pending and this is free.
static void ggml_vk_flush_pending_host_reads(ggml_backend_vk_context * ctx) {
    if (ctx->pending_host_read) {
        ggml_vk_synchronize(ctx);
    }
}

static void ggml_backend_vk_set_tensor_2d_async(ggml_backend_t backend, ggml_tensor * tensor, const void * data, size_t offset,
                                                size_t size, size_t n_copies, size_t stride_tensor, size_t stride_data) {
    VK_LOG_DEBUG("ggml_backend_vk_set_tensor_2d_async(" << size << ", " << n_copies << ")");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;
    GGML_ASSERT((tensor->buffer->buft == ggml_backend_vk_get_default_buffer_type(backend) || tensor->buffer->buft == ggml_backend_vk_host_buffer_type()) && "unsupported buffer type");

    if (size == 0) {
        return;
    }

    ggml_vk_flush_pending_host_reads(ctx);

    ggml_backend_vk_buffer_context * buf_ctx = (ggml_backend_vk_buffer_context *)tensor->buffer->context;

    vk_context cpy_ctx;

    if (ctx->device->async_use_transfer_queue) {
        cpy_ctx = ggml_vk_get_transfer_ctx(ctx);
    } else {
        cpy_ctx = ggml_vk_get_compute_ctx(ctx);
    }

    vk_buffer buf = buf_ctx->dev_buffer;

    auto dst_offset = vk_tensor_offset(tensor) + tensor->view_offs + offset;

    bool ret = ggml_vk_buffer_write_2d_async(cpy_ctx, buf, dst_offset, data, stride_data, stride_tensor, size, n_copies);

    if (!ret) {
        const size_t staging_size = size * n_copies;
        ggml_vk_ensure_sync_staging_buffer(ctx, staging_size);
        ggml_vk_sync_buffers(nullptr, cpy_ctx);

        std::vector<vk::BufferCopy> slices(1);
        if (size == stride_tensor) {
            slices[0].srcOffset = 0;
            slices[0].dstOffset = dst_offset;
            slices[0].size = staging_size;
        } else {
            slices.resize(n_copies);
            for (size_t i = 0; i < n_copies; i++) {
                slices[i].srcOffset = i * size;
                slices[i].dstOffset = dst_offset + i * stride_tensor;
                slices[i].size = size;
            }
        }

        cpy_ctx->s->buffer->buf.copyBuffer(ctx->sync_staging->buffer, buf->buffer, slices);

        if (size == stride_data) {
            deferred_memcpy(ctx->sync_staging->ptr, data, staging_size, &cpy_ctx->in_memcpys);
        } else {
            for (size_t i = 0; i < n_copies; i++) {
                deferred_memcpy((uint8_t *)ctx->sync_staging->ptr + i * size, (const uint8_t *)data + i * stride_data, size, &cpy_ctx->in_memcpys);
            }
        }
        ggml_vk_synchronize(ctx);
    }
}

static void ggml_backend_vk_set_tensor_async(ggml_backend_t backend, ggml_tensor * tensor, const void * data, size_t offset, size_t size) {
    VK_LOG_DEBUG("ggml_backend_vk_set_tensor_async(" << size << ")");
    ggml_backend_vk_set_tensor_2d_async(backend, tensor, data, offset, size, 1, size, size);
}

static void ggml_backend_vk_get_tensor_2d_async(ggml_backend_t backend, const ggml_tensor * tensor, void * data, size_t offset,
                                                size_t size, size_t n_copies, size_t stride_tensor, size_t stride_data) {
    VK_LOG_DEBUG("ggml_backend_vk_get_tensor_2d_async(" << size << ", " << n_copies << ")");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;
    GGML_ASSERT((tensor->buffer->buft == ggml_backend_vk_get_default_buffer_type(backend) || tensor->buffer->buft == ggml_backend_vk_host_buffer_type()) && "unsupported buffer type");

    if (size == 0) {
        return;
    }

    ggml_backend_vk_buffer_context * buf_ctx = (ggml_backend_vk_buffer_context *)tensor->buffer->context;

    vk_context compute_ctx = ggml_vk_get_compute_ctx(ctx);

    vk_buffer buf = buf_ctx->dev_buffer;

    auto src_offset = vk_tensor_offset(tensor) + tensor->view_offs + offset;
    bool ret = ggml_vk_buffer_read_2d_async(compute_ctx, buf, src_offset, data, stride_tensor, stride_data, size, n_copies);

    // [TAG_ASYNC_READ_UMA] the direct-read shortcut queued the memcpy instead of recording a copy;
    // it must be fenced and drained before anything else is recorded into this context.
    if (!compute_ctx->out_memcpys.empty()) {
        ctx->pending_host_read = true;
    }

    if (!ret) {
        const size_t staging_size = size * n_copies;
        ggml_vk_ensure_sync_staging_buffer(ctx, staging_size);
        ggml_vk_sync_buffers(nullptr, compute_ctx);

        std::vector<vk::BufferCopy> slices(1);
        if (size == stride_tensor) {
            slices[0].srcOffset = src_offset;
            slices[0].dstOffset = 0;
            slices[0].size = staging_size;
        } else {
            slices.resize(n_copies);
            for (size_t i = 0; i < n_copies; i++) {
                slices[i].srcOffset = src_offset + i * stride_tensor;
                slices[i].dstOffset = i * size;
                slices[i].size = size;
            }
        }

        compute_ctx->s->buffer->buf.copyBuffer(buf->buffer, ctx->sync_staging->buffer, slices);

        if (size == stride_data) {
            deferred_memcpy(data, ctx->sync_staging->ptr, staging_size, &compute_ctx->out_memcpys);
        } else {
            for (size_t i = 0; i < n_copies; i++) {
                deferred_memcpy((uint8_t *)data + i * stride_data, (const uint8_t *)ctx->sync_staging->ptr + i * size, size, &compute_ctx->out_memcpys);
            }
        }
        ggml_vk_synchronize(ctx);
    }
}

static void ggml_backend_vk_get_tensor_async(ggml_backend_t backend, const ggml_tensor * tensor, void * data, size_t offset, size_t size) {
    VK_LOG_DEBUG("ggml_backend_vk_get_tensor_async(" << size << ")");
    ggml_backend_vk_get_tensor_2d_async(backend, tensor, data, offset, size, 1, size, size);
}

static bool ggml_backend_vk_cpy_tensor_async(ggml_backend_t backend_src, ggml_backend_t backend_dst, const ggml_tensor * src, ggml_tensor * dst) {
    VK_LOG_DEBUG("ggml_backend_vk_cpy_tensor_async(" << src << " -> " << dst << ", size=" << ggml_nbytes(src) << ")");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend_dst->context;

    // Skip zero-size tensors
    if (ggml_nbytes(src) == 0) {
        return true;
    }

    if (dst->buffer->buft != ggml_backend_vk_get_default_buffer_type(backend_dst)) {
        return false;
    }

    ggml_vk_flush_pending_host_reads(ctx);

    ggml_backend_vk_buffer_context * dst_buf_ctx = (ggml_backend_vk_buffer_context *)dst->buffer->context;
    vk_buffer dst_buf = dst_buf_ctx->dev_buffer;

    if (ggml_backend_buffer_is_vk(src->buffer)) {
        ggml_backend_vk_buffer_context * src_buf_ctx = (ggml_backend_vk_buffer_context *)src->buffer->context;

        // Async copy only works within the same device
        if (src_buf_ctx->dev_buffer->device != dst_buf->device) {
            return false;
        }

        vk_context compute_ctx = ggml_vk_get_compute_ctx(ctx);

        ggml_vk_buffer_copy_async(compute_ctx, dst_buf, vk_tensor_offset(dst) + dst->view_offs,
                                   src_buf_ctx->dev_buffer, vk_tensor_offset(src) + src->view_offs,
                                   ggml_nbytes(src));
        return true;
    }

    if (ggml_backend_buffer_is_host(src->buffer)) {
        vk_buffer pinned_buf = nullptr;
        size_t pinned_offset = 0;
        ggml_vk_host_get(ctx->device, src->data, pinned_buf, pinned_offset);
        if (pinned_buf == nullptr) {
            return false;
        }

        vk_context cpy_ctx;
        if (ctx->device->async_use_transfer_queue) {
            cpy_ctx = ggml_vk_get_transfer_ctx(ctx);
        } else {
            cpy_ctx = ggml_vk_get_compute_ctx(ctx);
        }

        return ggml_vk_buffer_write_async(cpy_ctx, dst_buf,
                                          vk_tensor_offset(dst) + dst->view_offs,
                                          src->data, ggml_nbytes(src));
    }

    GGML_UNUSED(backend_src);
    return false;
}

static void ggml_vk_synchronize(ggml_backend_vk_context * ctx) {
    VK_LOG_DEBUG("ggml_vk_synchronize()");

    bool do_transfer = !ctx->compute_ctx.expired();

    if (ggml_vk_submit_transfer_ctx(ctx)) {
        ctx->submit_pending = true;
    }

    vk_context compute_ctx;
    vk_command_buffer* cmd_buf = nullptr;
    if (do_transfer) {
        compute_ctx = ctx->compute_ctx.lock();
        if (compute_ctx->s) {
            cmd_buf = compute_ctx->s->buffer;
        }

        ggml_vk_ctx_end(compute_ctx);

        for (auto& cpy : compute_ctx->in_memcpys) {
            memcpy(cpy.dst, cpy.src, cpy.n);
        }

        if (ctx->device->serialize_submissions) {
            ggml_vk_submit(compute_ctx, ctx->fence);
            VK_CHECK(ctx->device->device.waitForFences({ ctx->fence }, true, UINT64_MAX), "synchronize waitForFences", ctx->device);
            ctx->device->device.resetFences({ ctx->fence });
        } else {
            ggml_vk_submit(compute_ctx, {});
        }
        ctx->submit_pending = true;
    }

    if (ctx->submit_pending) {
        if (ctx->device->serialize_submissions) {
            ctx->submit_pending = false;
        } else if (ctx->device->async_use_transfer_queue && ctx->transfer_semaphore_last_submitted < ctx->transfer_semaphore.value) {
            vk::TimelineSemaphoreSubmitInfo tl_info{
                1, &ctx->transfer_semaphore.value,
                0, nullptr,
            };
            vk::PipelineStageFlags stage = ctx->device->transfer_queue->stage_flags;
            vk::SubmitInfo si{
                1, &ctx->transfer_semaphore.s, &stage,
                0, nullptr,
                0, nullptr,
            };
            si.setPNext(&tl_info);
            ctx->device->compute_queue->handle->submit({ si }, ctx->fence);
            ctx->transfer_semaphore_last_submitted = ctx->transfer_semaphore.value;
        } else {
            ctx->device->compute_queue->handle->submit({}, ctx->fence);
        }
        if (!ctx->device->serialize_submissions) {
            ggml_vk_wait_for_fence(ctx);
        }
        ctx->submit_pending = false;
        if (cmd_buf) {
            cmd_buf->in_use = false;
            cmd_buf->buf.reset();
        }
    }

    if (do_transfer) {
        for (auto& cpy : compute_ctx->out_memcpys) {
            memcpy(cpy.dst, cpy.src, cpy.n);
        }
        // [TAG_ASYNC_READ_UMA] the context stays alive in ctx->gc until ggml_vk_graph_cleanup; clear
        // the drained list so it can never be replayed against a buffer that has moved on.
        compute_ctx->out_memcpys.clear();
        ctx->compute_ctx.reset();
    }

    ctx->pending_host_read = false;

    // [TAG_VK_EXPERT_OCC] every submitted batch has completed here
    ggml_vk_expert_occ_drain(ctx);
}

static void ggml_backend_vk_synchronize(ggml_backend_t backend) {
    VK_LOG_DEBUG("ggml_backend_vk_synchronize()");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;

    ggml_vk_synchronize(ctx);

    // [TAG_QSA_TOPK_NOKEYS] GGML_VK_QSA_TOPK_NOKEYS_CHECK=1: the work is done, the CHECK word says whether a NOKEYS selection
    // saw a visible cell whose score is outside the integer key's domain (diagnostic, not a guarantee)
    if (ctx->device->qsa_topk_nokeys_check && ctx->device->qsa_topk_nk_flag) {
        volatile uint32_t * w = (volatile uint32_t *) ctx->device->qsa_topk_nk_flag->ptr;
        const uint32_t f = w[0];
        if (f != 0 && !ctx->device->qsa_topk_nk_warned) {
            ctx->device->qsa_topk_nk_warned = true;
            GGML_LOG_WARN("ggml_vulkan: qsa_topk nokeys CHECK: visible cells with out-of-domain scores (%s%s%s) - the integer key "
                          "is not proven equal to the keyed f2ui(score + mask) for them (warned once)\n",
                          (f & 1u) ? "subnormal " : "", (f & 2u) ? "NaN " : "", (f & 4u) ? "+inf" : "");
        }
        w[0] = 0;
    }

    ggml_vk_graph_cleanup(ctx);
}

static bool ggml_vk_is_empty(ggml_tensor * node) {
    return ggml_is_empty(node) || node->op == GGML_OP_NONE || node->op == GGML_OP_RESHAPE || node->op == GGML_OP_TRANSPOSE || node->op == GGML_OP_VIEW || node->op == GGML_OP_PERMUTE;
}

static bool ggml_vk_can_fuse(const ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx, std::initializer_list<enum ggml_op> ops) {
    if (!ggml_can_fuse(cgraph, node_idx, ops)) {
        return false;
    }

    if (ops.size() == 2 && ops.begin()[0] == GGML_OP_RMS_NORM && ops.begin()[1] == GGML_OP_MUL) {
        // additional constraints specific to this fusion
        const ggml_tensor *rms_norm = cgraph->nodes[node_idx];
        const ggml_tensor *mul = cgraph->nodes[node_idx + 1];

        GGML_ASSERT(rms_norm->src[0]->type == GGML_TYPE_F32);
        GGML_ASSERT(rms_norm->type == GGML_TYPE_F32);
        // rms_norm only supports f32
        if (mul->src[0]->type != GGML_TYPE_F32 ||
            mul->src[1]->type != GGML_TYPE_F32 ||
            mul->type != GGML_TYPE_F32) {
            return false;
        }
        // if rms_norm is the B operand, then we don't handle broadcast
        if (rms_norm == mul->src[1] &&
            !ggml_are_same_shape(mul->src[0], rms_norm)) {
            return false;
        }
        // rms_norm shader assumes contiguous rows
        if (!ggml_is_contiguous_rows(mul->src[0]) || !ggml_is_contiguous_rows(mul->src[1])) {
            return false;
        }
    }
    auto const &mm_add_ok = [&](const ggml_tensor *mul, const ggml_tensor *add) {
        const ggml_tensor *bias = add->src[0] == mul ? add->src[1] : add->src[0];

        // mat-vec only
        if (ggml_nrows(mul) != 1) {
            return false;
        }
        // shaders assume the types match
        if (mul->type != bias->type) {
            return false;
        }
        // shaders reuse the D shape for bias
        if (!ggml_are_same_shape(mul, bias) ||
            !ggml_are_same_stride(mul, bias)) {
            return false;
        }
        // unaligned bias isn't handled
        if (get_misalign_bytes(ctx, bias) != 0) {
            return false;
        }
        return true;
    };

    if ((ops.size() == 2 || ops.size() == 3) && ops.begin()[0] == GGML_OP_MUL_MAT && ops.begin()[1] == GGML_OP_ADD) {
        // additional constraints specific to this fusion
        const ggml_tensor *mul = cgraph->nodes[node_idx];
        const ggml_tensor *add = cgraph->nodes[node_idx + 1];

        if (!mm_add_ok(mul, add)) {
            return false;
        }
        if (ops.size() == 3) {
            if (ops.begin()[2] != GGML_OP_ADD) {
                return false;
            }
            if (!mm_add_ok(add, cgraph->nodes[node_idx + 2])) {
                return false;
            }
        }
    }

    auto const &mmid_mul_ok = [&](const ggml_tensor *mmid, const ggml_tensor *mul) {
        const ggml_tensor *scale = mul->src[1];

        if (mmid != mul->src[0]) {
            return false;
        }
        // mat-vec only
        if (!ggml_vk_use_mul_mat_vec_id(cgraph, node_idx)) {
            return false;
        }
        // shaders assume the types match
        if (mmid->type != scale->type) {
            return false;
        }
        // shaders assume the bias is contiguous
        if (!ggml_is_contiguous(scale)) {
            return false;
        }
        // unaligned bias isn't handled
        if (get_misalign_bytes(ctx, scale) != 0) {
            return false;
        }
        // shader only indexes by expert index
        if (scale->ne[0] != 1 ||
            scale->ne[1] != mul->ne[1] ||
            scale->ne[2] != 1 ||
            scale->ne[3] != 1) {
            return false;
        }
        return true;
    };

    if ((ops.size() == 2 || ops.size() == 3) && ops.begin()[0] == GGML_OP_MUL_MAT_ID && ops.begin()[1] == GGML_OP_ADD_ID) {
        // additional constraints specific to this fusion
        const ggml_tensor *mul = cgraph->nodes[node_idx];
        const ggml_tensor *add = cgraph->nodes[node_idx + 1];
        const ggml_tensor *bias = add->src[1];

        if (mul != add->src[0]) {
            return false;
        }
        // mat-vec only
        if (!ggml_vk_use_mul_mat_vec_id(cgraph, node_idx)) {
            return false;
        }
        // shaders assume the types match
        if (mul->type != bias->type) {
            return false;
        }
        // shaders assume the bias is contiguous
        if (!ggml_is_contiguous(bias)) {
            return false;
        }
        // the ID tensor must be the same for mul_mat_id and add_id
        if (mul->src[2] != add->src[2]) {
            return false;
        }
        // unaligned bias isn't handled
        if (get_misalign_bytes(ctx, bias) != 0) {
            return false;
        }

        if (ops.size() == 3) {
            if (ops.begin()[2] != GGML_OP_MUL) {
                return false;
            }
            const ggml_tensor *mul = cgraph->nodes[node_idx + 2];
            return mmid_mul_ok(add, mul);
        }
    }

    if (ops.size() == 2 && ops.begin()[0] == GGML_OP_MUL_MAT_ID && ops.begin()[1] == GGML_OP_MUL) {
        // additional constraints specific to this fusion
        const ggml_tensor *mmid = cgraph->nodes[node_idx];
        const ggml_tensor *mul = cgraph->nodes[node_idx + 1];

        if (!mmid_mul_ok(mmid, mul)) {
            return false;
        }
    }

    return true;
}

// GGML_VK_FUSION_COUNT: name the *first* condition that keeps MUL_MAT_ID + MUL (the MoE
// expert-weight multiply) unfused at node_idx, or nullptr when nothing does. The tally alone says
// "47 of 47 fused" or "none fused"; only the reason distinguishes the classes that matter for
// determinism, because they are not all benign:
//   - scale_ne*  : a shape gate (scale_ne2 is n_tokens > 1) - a legitimate, shape-determined miss,
//   - not_adjacent / not_src / n_uses / view / output / no_compute_flag : the graph order that
//     ggml_vk_graph_optimize produced separated the pair, so the same shape can fuse or not
//     between two executions,
//   - misalign : ggml-alloc placed the scale operand at an offset the shader cannot fold in,
//   - not_matvec / type / scale_noncontig : backend capability gates.
// Mirrors ggml_can_fuse_ext() then mmid_mul_ok() in evaluation order so the key is the real cause.
static const char * ggml_vk_mmid_mul_nofuse_reason(const ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {
    const ggml_tensor * mmid = cgraph->nodes[node_idx];
    if (mmid->op != GGML_OP_MUL_MAT_ID) {
        return nullptr;
    }
    if (node_idx + 1 >= cgraph->n_nodes) {
        return "graph_end";
    }
    const ggml_tensor * mul = cgraph->nodes[node_idx + 1];
    if (mul->op == GGML_OP_ADD_ID) {
        // the {MUL_MAT_ID, ADD_ID, MUL} variant; it has its own fusion_string and its own key
        return "add_id";
    }
    if (mul->op != GGML_OP_MUL) {
        return "not_adjacent";
    }
    if ((mmid->flags & GGML_TENSOR_FLAG_COMPUTE) == 0 || (mul->flags & GGML_TENSOR_FLAG_COMPUTE) == 0) {
        return "no_compute_flag";
    }
    if (ggml_node_get_use_count(cgraph, node_idx) != 1) {
        return "n_uses";
    }
    if (mmid->view_src) {
        return "view";
    }
    if (mmid->flags & GGML_TENSOR_FLAG_OUTPUT) {
        return "output";
    }
    if (mul->src[0] != mmid && mul->src[1] != mmid) {
        return "not_src";
    }
    if (!ggml_are_same_shape(mul, mmid)) {
        return "shape_ne";
    }
    if (mul->src[0] != mmid) {
        return "mmid_is_src1";
    }
    if (!ggml_vk_use_mul_mat_vec_id(cgraph, node_idx)) {
        return "not_matvec";
    }
    const ggml_tensor * scale = mul->src[1];
    if (mmid->type != scale->type) {
        return "type";
    }
    if (!ggml_is_contiguous(scale)) {
        return "scale_noncontig";
    }
    if (get_misalign_bytes(ctx, scale) != 0) {
        return "misalign";
    }
    if (scale->ne[0] != 1) {
        return "scale_ne0";
    }
    if (scale->ne[1] != mul->ne[1]) {
        return "scale_ne1";
    }
    if (scale->ne[2] != 1) {
        return "scale_ne2";
    }
    if (scale->ne[3] != 1) {
        return "scale_ne3";
    }
    return nullptr;
}

// Match SSM_CONV + UNARY(SILU) or SSM_CONV + ADD + UNARY(SILU). num_extra is 1 or 2.
static bool ggml_vk_can_fuse_ssm_conv(const ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph,
                                      int node_idx, int num_extra) {
    const ggml_tensor * conv = cgraph->nodes[node_idx];
    if (conv->op != GGML_OP_SSM_CONV) {
        return false;
    }

    const ggml_tensor * silu = nullptr;
    const ggml_tensor * bias = nullptr;

    if (num_extra == 1) {
        if (!ggml_can_fuse(cgraph, node_idx, { GGML_OP_SSM_CONV, GGML_OP_UNARY })) {
            return false;
        }
        silu = cgraph->nodes[node_idx + 1];
    } else if (num_extra == 2) {
        if (!ggml_can_fuse(cgraph, node_idx, { GGML_OP_SSM_CONV, GGML_OP_ADD, GGML_OP_UNARY })) {
            return false;
        }
        const ggml_tensor * add = cgraph->nodes[node_idx + 1];
        silu = cgraph->nodes[node_idx + 2];
        bias = (add->src[0] == conv) ? add->src[1] : add->src[0];

        if (bias->type != GGML_TYPE_F32 || !ggml_is_contiguous(bias)) {
            return false;
        }
        // bias must be channel-wise (one element per channel of the conv output)
        if (ggml_nelements(bias) != conv->ne[0] || bias->ne[0] != conv->ne[0]) {
            return false;
        }
        if (add->type != GGML_TYPE_F32) {
            return false;
        }
        // The shader doesn't apply per-tensor offsets, so reject misaligned bias.
        if (get_misalign_bytes(ctx, bias) != 0) {
            return false;
        }
    } else {
        return false;
    }

    if (ggml_get_unary_op(silu) != GGML_UNARY_OP_SILU) {
        return false;
    }
    if (conv->type != GGML_TYPE_F32 || silu->type != GGML_TYPE_F32) {
        return false;
    }
    // The shader writes to the fused dst using its own strides, but the push constants don't
    // carry a per-tensor offset, so the binding must be naturally aligned.
    if (get_misalign_bytes(ctx, silu) != 0) {
        return false;
    }
    return true;
}

// [TAG_CONV_INPUT_SPLIT] CONCAT(state, x, dim 0) + SSM_CONV(concat, c) (+ SILU, or + ADD(bias) + SILU when
// num_extra = 1 / 2): the qwen4exp GDN conv input (build_conv_state_at, state = the conv history row, x = the
// transposed qkv_mixed). The concat is not written; the conv reads each window element from its source, the
// same float the concat would have copied there, so the dot product sees the same operands (bit-exact). The
// concat must feed only the conv: build_conv_state_at takes the rollback tails from x when the ubatch is long
// enough (prefill), so this matches prefill graphs; with a tail still reading the concat (decode) it does not.
static bool ggml_vk_can_fuse_concat_ssm_conv(const ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph,
                                             int node_idx, int num_extra) {
    if (!ctx->device->fuse_concat_ssm_conv || num_extra < 0 || num_extra > 2) {
        return false;
    }
    if (node_idx + 1 + num_extra >= cgraph->n_nodes) {
        return false;
    }
    const ggml_tensor * concat = cgraph->nodes[node_idx];
    const ggml_tensor * conv   = cgraph->nodes[node_idx + 1];
    if (concat->op != GGML_OP_CONCAT || conv->op != GGML_OP_SSM_CONV || conv->src[0] != concat) {
        return false;
    }
    if (ggml_get_op_params_i32(concat, 0) != 0) {
        return false;
    }
    // the concat (and the chain's intermediates) are used inside the pattern only
    bool uses_ok = false;
    switch (num_extra) {
        case 0: uses_ok = ggml_can_fuse_subgraph(cgraph, node_idx, { GGML_OP_CONCAT, GGML_OP_SSM_CONV }, { node_idx + 1 }); break;
        case 1: uses_ok = ggml_can_fuse_subgraph(cgraph, node_idx, { GGML_OP_CONCAT, GGML_OP_SSM_CONV, GGML_OP_UNARY }, { node_idx + 2 }); break;
        case 2: uses_ok = ggml_can_fuse_subgraph(cgraph, node_idx, { GGML_OP_CONCAT, GGML_OP_SSM_CONV, GGML_OP_ADD, GGML_OP_UNARY }, { node_idx + 3 }); break;
    }
    if (!uses_ok) {
        return false;
    }
    // the conv tail (silu / bias + silu) under the same rules as the plain ssm_conv fusions
    if (num_extra > 0 && !ggml_vk_can_fuse_ssm_conv(ctx, cgraph, node_idx + 1, num_extra)) {
        return false;
    }

    const ggml_tensor * state = concat->src[0];
    const ggml_tensor * x     = concat->src[1];
    const ggml_tensor * w     = conv->src[1];
    const ggml_tensor * dst   = cgraph->nodes[node_idx + 1 + num_extra];

    for (const ggml_tensor * t : { concat, state, x, conv, w, dst }) {
        if (t->type != GGML_TYPE_F32) {
            return false;
        }
    }
    const int64_t nc = w->ne[0];
    const int64_t nr = w->ne[1];
    const int64_t n_t = conv->ne[1];
    const int64_t n_s = conv->ne[2];
    // state [nc - 1, nr, n_s] with unit element stride (the shader indexes its columns directly)
    if (state->ne[0] != nc - 1 || state->ne[1] != nr || state->ne[2] != n_s || state->ne[3] != 1 ||
        state->nb[0] != sizeof(float) || state->nb[1] % sizeof(float) || state->nb[2] % sizeof(float)) {
        return false;
    }
    // x [n_t, nr, n_s], any strides in whole elements
    if (x->ne[0] != n_t || x->ne[1] != nr || x->ne[2] != n_s || x->ne[3] != 1 ||
        x->nb[0] % sizeof(float) || x->nb[1] % sizeof(float) || x->nb[2] % sizeof(float)) {
        return false;
    }
    if (concat->ne[0] != nc - 1 + n_t || concat->ne[3] != 1) {
        return false;
    }
    // no per-tensor offsets in the push constants
    if (get_misalign_bytes(ctx, state) || get_misalign_bytes(ctx, x) || get_misalign_bytes(ctx, w) || get_misalign_bytes(ctx, dst)) {
        return false;
    }
    return true;
}

static bool ggml_vk_can_fuse_topk_moe(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph,
                                      int node_idx, topk_moe_mode mode) {

    const ggml_tensor * softmax;
    const ggml_tensor * weights;
    const ggml_tensor * get_rows;
    const ggml_tensor * argsort;

    switch (mode) {
    case TOPK_MOE_EARLY_SOFTMAX_NORM:
        softmax = cgraph->nodes[node_idx + 0];
        weights = cgraph->nodes[node_idx + 9];
        get_rows = cgraph->nodes[node_idx + 4];
        argsort = cgraph->nodes[node_idx + 2];
        break;
    case TOPK_MOE_SIGMOID_NORM_BIAS:
        softmax = cgraph->nodes[node_idx + 0]; // really sigmoid
        weights = cgraph->nodes[node_idx + 10];
        get_rows = cgraph->nodes[node_idx + 5];
        argsort = cgraph->nodes[node_idx + 3];
        if (ggml_get_unary_op(softmax) != GGML_UNARY_OP_SIGMOID) {
            return false;
        }
        // bias is expected to be 1D
        if (ggml_nrows(cgraph->nodes[node_idx + 2]->src[1]) != 1 ||
            !ggml_is_contiguous(cgraph->nodes[node_idx + 2]->src[1])) {
            return false;
        }
        // sigmoid fusion seems to generate infinities on moltenvk
        if (ctx->device->driver_id == vk::DriverId::eMoltenvk) {
            return false;
        }
        break;
    case TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS:
        softmax = cgraph->nodes[node_idx + 0]; // really softplus
        weights = cgraph->nodes[node_idx + 11];
        get_rows = cgraph->nodes[node_idx + 6];
        argsort = cgraph->nodes[node_idx + 4];
        if (ggml_get_unary_op(softmax) != GGML_UNARY_OP_SOFTPLUS) {
            return false;
        }
        // bias is expected to be 1D
        if (ggml_nrows(cgraph->nodes[node_idx + 3]->src[1]) != 1 ||
            !ggml_is_contiguous(cgraph->nodes[node_idx + 3]->src[1])) {
            return false;
        }
        break;
    case TOPK_MOE_EARLY_SOFTMAX:
        softmax = cgraph->nodes[node_idx + 0];
        weights = cgraph->nodes[node_idx + 4];
        get_rows = cgraph->nodes[node_idx + 4];
        argsort = cgraph->nodes[node_idx + 2];
        break;
    case TOPK_MOE_LATE_SOFTMAX:
        softmax = cgraph->nodes[node_idx + 4];
        weights = cgraph->nodes[node_idx + 5];
        get_rows = cgraph->nodes[node_idx + 2];
        argsort = cgraph->nodes[node_idx + 0];
        break;
    default:
        return false;
    }

    ggml_tensor * probs = get_rows->src[0];
    if (probs->op != GGML_OP_RESHAPE) {
        return false;
    }
    probs = probs->src[0];
    ggml_tensor * selection_probs = argsort->src[0];

    if (probs != selection_probs &&
        mode != TOPK_MOE_SIGMOID_NORM_BIAS &&
        mode != TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS) {
        return false;
    }

    if (!ggml_is_contiguous(softmax->src[0]) || !ggml_is_contiguous(weights)) {
        return false;
    }

    if (softmax->op == GGML_OP_SOFT_MAX) {
        const float * op_params = (const float *)softmax->op_params;

        float scale = op_params[0];
        float max_bias = op_params[1];

        if (scale != 1.0f || max_bias != 0.0f) {
            return false;
        }

        // don't fuse when masks or sinks are present
        if (softmax->src[1] || softmax->src[2]) {
            return false;
        }
    }

    const int n_expert = softmax->ne[0];
    if (n_expert > (1 << (num_topk_moe_pipelines-1))) {
        return false;
    }

    if (!ctx->device->subgroup_arithmetic ||
        !ctx->device->subgroup_shuffle ||
        !ctx->device->subgroup_require_full_support ||
        ctx->device->disable_fusion) {
        return false;
    }

    return true;
}

// Manual op-sequence match (ggml_can_fuse_subgraph rejects the mask's external reshape/cpy).
static bool ggml_vk_match_ops(const struct ggml_cgraph * cgraph, int node_idx,
                              const std::initializer_list<ggml_op> & ops) {
    if (node_idx + (int) ops.size() > cgraph->n_nodes) {
        return false;
    }
    for (size_t j = 0; j < ops.size(); ++j) {
        const ggml_tensor * node = cgraph->nodes[node_idx + j];
        if (node->op != ops.begin()[j] ||
            (node->flags & GGML_TENSOR_FLAG_COMPUTE) == 0 ||
            (node->flags & GGML_TENSOR_FLAG_OUTPUT) != 0) {
            return false;
        }
    }
    return true;
}

// defined with the dispatcher's veto loop below; used here for the operands that loop cannot see
static bool ggml_vk_tensors_overlap(const ggml_tensor * a, const ggml_tensor * b, bool elementwise);

// GGML_VK_FUSION_DIAG=1: log every fusion that the src/dst overlap veto disables (declared here so
// ggml_vk_can_fuse_topk_qsa, which runs its own operand-vs-destination test, can log the same way).
static const bool vk_fusion_diag = getenv("GGML_VK_FUSION_DIAG") != nullptr;

// True if the qwen4 QSA indexer top-k can be fused at node_idx (the get_rows).
static bool ggml_vk_can_fuse_topk_qsa(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {
    if (ctx->device->disable_fusion || (!ctx->device->pipeline_topk_radix_qsa && !ctx->device->qsa_topk_v2)) {
        return false;
    }

    const int n_ops = topk_qsa_pattern.size();
    if (!ggml_vk_match_ops(cgraph, node_idx, topk_qsa_pattern) ||
        !ggml_check_edges(cgraph, node_idx, topk_qsa_edges)) {
        return false;
    }

    // elided nodes must be single-use (cpy counts its own src[1] self-reference)
    for (int j = 0; j < n_ops - 1; ++j) {
        const ggml_tensor * node = cgraph->nodes[node_idx + j];
        const int32_t want = node->op == GGML_OP_CPY ? 2 : 1;
        if (ggml_node_get_use_count(cgraph, node_idx + j) != want) {
            return false;
        }
    }

    const ggml_tensor * get_rows = cgraph->nodes[node_idx + 0];
    const ggml_tensor * add      = cgraph->nodes[node_idx + n_ops - 2];
    const ggml_tensor * top_k    = cgraph->nodes[node_idx + n_ops - 1];

    const ggml_tensor * scores   = get_rows->src[0]; // [n_tps, n_blocks, n_stream]
    const ggml_tensor * cell_blk = get_rows->src[1]; // [n_kv, n_stream]
    const ggml_tensor * expanded = add->src[0];      // [n_kv, n_tps, n_stream]

    // raw mask: follow the reshape/cpy chain back to the materialized f16 input
    const ggml_tensor * mask = add->src[1];
    while (mask && (mask->op == GGML_OP_RESHAPE || mask->op == GGML_OP_CPY)) {
        mask = mask->src[0];
    }
    if (!mask || mask->type != GGML_TYPE_F16) {
        return false;
    }

    if (scores->type != GGML_TYPE_F32 || cell_blk->type != GGML_TYPE_I32 || top_k->type != GGML_TYPE_I32) {
        return false;
    }
    if (!ggml_is_contiguous(scores) || !ggml_is_contiguous(cell_blk) || !ggml_is_contiguous(mask) ||
        !ggml_is_contiguous(expanded) || !ggml_is_contiguous(top_k)) {
        return false;
    }

    const int64_t n_tps    = scores->ne[0];
    const int64_t n_blocks = scores->ne[1];
    const int64_t n_stream = scores->ne[2];
    const int64_t n_kv     = cell_blk->ne[0];
    const int64_t width    = top_k->ne[0];

    // pin the indexer layout the shader's addressing assumes
    if (scores->ne[3] != 1 || cell_blk->ne[1] != n_stream || ggml_nrows(cell_blk) != n_stream ||
        ggml_nelements(mask) != n_kv * n_tps * n_stream ||
        expanded->ne[0] != n_kv || expanded->ne[1] != n_tps || expanded->ne[2] != n_stream ||
        top_k->ne[1] != n_tps || top_k->ne[2] != n_stream || top_k->ne[3] != 1 ||
        n_blocks <= 0 || n_kv <= 0 || width <= 0 || width > n_kv) {
        return false;
    }

    // only worth it in the radix regime; small k uses the faster tournament unfused
    const uint32_t k_min_pipeline = std::max((uint32_t) log2f(float(width)) + 1, ctx->device->subgroup_size_log2);
    if (k_min_pipeline < num_topk_pipelines && ctx->device->pipeline_topk_f32[k_min_pipeline]) {
        return false;
    }

    // The fused dispatch reads `scores`, `cell_blk` and the RAW f16 mask at the TOP_K node - several
    // nodes after ggml-alloc believes their last consumer ran - and writes the TOP_K there, so none
    // of the three may share bytes with it. The dispatcher's generic veto loop cannot decide this:
    // cell_blk and the mask are graph inputs, and it skips every src whose op is GGML_OP_NONE, so an
    // overlap on those would be a silently wrong selection instead of a veto. ggml-alloc really can
    // produce it - one cell_blk input serves every layer of the ratio, so its block is freed after
    // the LAST QSA layer's GET_ROWS, i.e. inside that layer's own pattern window, six nodes before
    // its TOP_K is allocated, and a CPU replay of the reserve caught exactly that placement. Unfused
    // the same graph is correct (every read precedes the TOP_K in graph order), so refuse the fusion
    // rather than read a buffer this dispatch is writing. `scores` is included for completeness: the
    // generic loop already tests it, but this keeps the shader's whole read set in one place.
    // test-backend-ops TOPK_QSA's alias=1|2|3 cases force each of the three aliases.
    auto overlaps_top_k = [&](const ggml_tensor * t) {
        return t && t->buffer && top_k->buffer &&
               ggml_backend_buffer_is_vk(t->buffer) && ggml_backend_buffer_is_vk(top_k->buffer) &&
               ggml_vk_tensors_overlap(t, top_k, false);
    };
    if (overlaps_top_k(scores) || overlaps_top_k(cell_blk) || overlaps_top_k(mask)) {
        if (vk_fusion_diag) {
            GGML_LOG_INFO("ggml_vulkan: fusion TOPK_QSA disabled at node %d: an operand (scores/cell_blk/mask) overlaps the top_k dst %s\n",
                          node_idx, top_k->name);
        }
        return false;
    }
    return true;
}

static bool ggml_vk_can_fuse_rope_set_rows(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph,
                                           int node_idx) {
    GGML_UNUSED(ctx);
    const ggml_tensor *rope = cgraph->nodes[node_idx + 0];
    const ggml_tensor *view = cgraph->nodes[node_idx + 1];
    const ggml_tensor *set_rows = cgraph->nodes[node_idx + 2];

    // ne3 not tested
    if (rope->src[0]->ne[3] != 1) {
        return false;
    }

    if (set_rows->type != GGML_TYPE_F32 && set_rows->type != GGML_TYPE_F16) {
        return false;
    }

    if (set_rows->src[1]->type != GGML_TYPE_I64) {
        return false;
    }

    // The view should flatten two dims of rope into one dim
    if (!ggml_is_contiguous(view) ||
        view->ne[0] != rope->ne[0] * rope->ne[1]) {
        return false;
    }

    // Only norm/neox/mrope shaders have the fusion code
    const int mode = ((const int32_t *) rope->op_params)[2];
    if (mode != GGML_ROPE_TYPE_NORMAL && mode != GGML_ROPE_TYPE_NEOX && mode != GGML_ROPE_TYPE_MROPE) {
        return false;
    }

    return true;
}

// UNARY(SIGMOID) + MUL where the sigmoid result is the second MUL operand -- the gated
// activations qwen4exp emits (build_hc_mix gate, build_norm_gated, the shared-expert gate,
// the attention output gate). Bit-exact for f32: the fused shader evaluates op_sigmoid
// exactly as unary.comp does and the elided store rounded to f32 too.
static bool ggml_vk_can_fuse_sigmoid_mul(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {
    if (!ctx->device->fuse_sigmoid_mul) {
        return false;
    }
    // ggml_can_fuse would additionally require the two nodes to have the same shape, which
    // rejects the broadcast gates (a [1, T] sigmoid over a [n_embd, T] activation). The fused
    // shader goes through src1_idx() like the unfused mul, so broadcasting is fine here.
    if (!ggml_can_fuse_subgraph(cgraph, node_idx, { GGML_OP_UNARY, GGML_OP_MUL }, { node_idx + 1 })) {
        return false;
    }

    const ggml_tensor * unary = cgraph->nodes[node_idx + 0];
    const ggml_tensor * mul   = cgraph->nodes[node_idx + 1];

    if (ggml_get_unary_op(unary) != GGML_UNARY_OP_SIGMOID) {
        return false;
    }
    // only the "sigmoid is src1" orientation has a shader, and src0 must be a real tensor:
    // the fused dispatch reads the sigmoid's source in place of the (never computed) unary
    if (mul->src[1] != unary || mul->src[0] == unary) {
        return false;
    }

    const ggml_tensor * b = unary->src[0];

    // f32 only: with an f16 unary the elided store would drop a rounding step
    if (unary->type != GGML_TYPE_F32 || mul->type != GGML_TYPE_F32 ||
        mul->src[0]->type != GGML_TYPE_F32 || b->type != GGML_TYPE_F32) {
        return false;
    }
    // the fused mul indexes b in place of the unary result, so the two must agree in shape
    if (!ggml_are_same_shape(b, unary)) {
        return false;
    }
    return true;
}

// ADD(alpha, ssm_dt) -> UNARY(SOFTPLUS) -> MUL(., ssm_a): the Gated-DeltaNet decay
// pre-chain qwen4exp emits once per GDN layer (build_layer_attn_linear). alpha is
// [num_v_heads, n_tokens] and both ssm_dt and ssm_a are one f32 per value-head,
// broadcast over the token axis.
//
// Bit-exactness. add_softplus_mul.comp evaluates the three steps in the same order,
// with the same f32 rounding after each, and with op_softplus copied character for
// character out of unary.comp. All six operands are f32, so the two stores the fusion
// elides rounded to f32 anyway and drop nothing. The match below therefore only has to
// pin the shape and the layout the shader assumes:
//   * the intermediates have no consumer outside the triple (the `outputs` argument),
//   * the chain edges are exactly add -> softplus -> mul->src[0],
//   * every tensor is f32,
//   * alpha and the destination are contiguous and identically shaped, so one linear
//     index reaches both,
//   * ssm_dt / ssm_a are contiguous with exactly ne0 elements, so `idx % ne0` is their
//     index (this is the qwen4exp shape; anything else is left to the unfused chain),
//   * no binding is misaligned (the push constants carry no per-tensor offset).
static bool ggml_vk_can_fuse_add_softplus_mul(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {
    if (!ctx->device->fuse_gdn_pre) {
        return false;
    }
    if (!ggml_can_fuse_subgraph(cgraph, node_idx, { GGML_OP_ADD, GGML_OP_UNARY, GGML_OP_MUL }, { node_idx + 2 })) {
        return false;
    }

    const ggml_tensor * add   = cgraph->nodes[node_idx + 0];
    const ggml_tensor * unary = cgraph->nodes[node_idx + 1];
    const ggml_tensor * mul   = cgraph->nodes[node_idx + 2];

    if (ggml_get_unary_op(unary) != GGML_UNARY_OP_SOFTPLUS) {
        return false;
    }
    // only the "chain is src0" orientation has a shader
    if (unary->src[0] != add || mul->src[0] != unary || mul->src[1] == unary) {
        return false;
    }

    const ggml_tensor * alpha = add->src[0];
    const ggml_tensor * bias  = add->src[1];
    const ggml_tensor * scale = mul->src[1];

    // f32 only: with an f16 intermediate the elided stores would drop a rounding step
    for (const ggml_tensor * t : { add, unary, mul, alpha, bias, scale }) {
        if (t->type != GGML_TYPE_F32) {
            return false;
        }
    }
    // the shader walks alpha and the destination with one linear index
    if (!ggml_are_same_shape(alpha, add) || !ggml_are_same_shape(add, unary) || !ggml_are_same_shape(unary, mul)) {
        return false;
    }
    if (!ggml_is_contiguous(alpha) || !ggml_is_contiguous(mul)) {
        return false;
    }
    // ssm_dt / ssm_a: one value per row element, broadcast over every row
    for (const ggml_tensor * t : { bias, scale }) {
        if (t->ne[0] != mul->ne[0] || ggml_nelements(t) != mul->ne[0] || !ggml_is_contiguous(t)) {
            return false;
        }
    }
    // the shader applies no per-tensor offset, so reject misaligned bindings
    for (const ggml_tensor * t : { alpha, bias, scale, mul }) {
        if (get_misalign_bytes(ctx, t) != 0) {
            return false;
        }
    }
    // one thread per element, 256 per workgroup
    const int64_t ne = ggml_nelements(mul);
    if (ne > (int64_t) UINT32_MAX ||
        CEIL_DIV((uint32_t) ne, 256u) > ctx->device->properties.limits.maxComputeWorkGroupCount[0]) {
        return false;
    }
    return true;
}

// Pattern check for the 7-op qwen4exp hyper-connection combine:
//   repeat(reshape(block)) , scale(inject) -> sigmoid -> scale -> reshape , mul, add.
// Verifies the chain edges, the f32-only types, the [ne0, hc, T] / [ne0, 1, T] / [hc, T]
// shapes and that every operand the shader indexes linearly is contiguous.
static bool ggml_vk_can_fuse_hc_combine(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {
    if (!ctx->device->fuse_hc_combine) {
        return false;
    }
    if (!ggml_can_fuse_subgraph(cgraph, node_idx, hc_combine_pattern, { node_idx + 6 })) {
        return false;
    }
    if (!ggml_check_edges(cgraph, node_idx, hc_combine_edges)) {
        return false;
    }

    const ggml_tensor * repeat  = cgraph->nodes[node_idx + 0];
    const ggml_tensor * scale1  = cgraph->nodes[node_idx + 1];
    const ggml_tensor * sigmoid = cgraph->nodes[node_idx + 2];
    const ggml_tensor * scale2  = cgraph->nodes[node_idx + 3];
    const ggml_tensor * reshape = cgraph->nodes[node_idx + 4];
    const ggml_tensor * mul     = cgraph->nodes[node_idx + 5];
    const ggml_tensor * add     = cgraph->nodes[node_idx + 6];

    if (ggml_get_unary_op(sigmoid) != GGML_UNARY_OP_SIGMOID) {
        return false;
    }

    const ggml_tensor * block    = repeat->src[0];
    const ggml_tensor * inject   = scale1->src[0];
    const ggml_tensor * residual = add->src[0];

    // the shader is f32 only
    for (const ggml_tensor * t : { repeat, scale1, sigmoid, scale2, mul, add, block, inject, residual }) {
        if (t->type != GGML_TYPE_F32) {
            return false;
        }
    }

    // ggml_scale with a non-zero bias is not what build_hc_combine emits
    if (((const float *)scale1->op_params)[1] != 0.0f ||
        ((const float *)scale2->op_params)[1] != 0.0f) {
        return false;
    }

    // out / residual / repeat / mul are [ne0, hc, T, 1]
    if (add->ne[3] != 1) {
        return false;
    }
    if (!ggml_are_same_shape(add, residual) ||
        !ggml_are_same_shape(add, mul) ||
        !ggml_are_same_shape(add, repeat)) {
        return false;
    }
    // the residual must be the other add operand, not the mul itself
    if (residual == mul) {
        return false;
    }
    // block is [ne0, 1, T, 1], broadcast over the hc dimension by the repeat
    if (block->ne[0] != add->ne[0] || block->ne[1] != 1 ||
        block->ne[2] != add->ne[2] || block->ne[3] != 1) {
        return false;
    }
    // inject is [hc, T, 1, 1] and the reshape presents it as [1, hc, T, 1]
    if (inject->ne[0] != add->ne[1] || inject->ne[1] != add->ne[2] ||
        inject->ne[2] != 1 || inject->ne[3] != 1) {
        return false;
    }
    if (reshape->ne[0] != 1 || reshape->ne[1] != add->ne[1] ||
        reshape->ne[2] != add->ne[2] || reshape->ne[3] != 1) {
        return false;
    }
    // the shader indexes every buffer linearly
    if (!ggml_is_contiguous(add) || !ggml_is_contiguous(residual) ||
        !ggml_is_contiguous(block) || !ggml_is_contiguous(inject)) {
        return false;
    }
    return true;
}

// Pattern check for the 5-op Snake fusion: mul -> sin -> sqr -> mul -> add.
// Verifies the chain shape, the closure x_in_add == x_in_mul0, and that
// the broadcast operands a and inv_b share a [1, C] layout.
static bool ggml_vk_can_fuse_snake(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {
    GGML_UNUSED(ctx);
    if (!ggml_can_fuse(cgraph, node_idx, snake_pattern)) {
        return false;
    }

    const ggml_tensor * mul0     = cgraph->nodes[node_idx + 0];
    const ggml_tensor * sin_node = cgraph->nodes[node_idx + 1];
    const ggml_tensor * sqr      = cgraph->nodes[node_idx + 2];
    const ggml_tensor * mul1     = cgraph->nodes[node_idx + 3];
    const ggml_tensor * add      = cgraph->nodes[node_idx + 4];

    const ggml_tensor * x = ggml_are_same_shape(mul0, mul0->src[0]) ? mul0->src[0] : mul0->src[1];
    const ggml_tensor * a = (x == mul0->src[0]) ? mul0->src[1] : mul0->src[0];

    const ggml_tensor * inv_b    = (mul1->src[0] == sqr) ? mul1->src[1] : mul1->src[0];
    const ggml_tensor * x_in_add = (add->src[0] == mul1) ? add->src[1] : add->src[0];

    if (x_in_add != x) {
        return false;
    }
    if (x->type != GGML_TYPE_F32 && x->type != GGML_TYPE_F16 && x->type != GGML_TYPE_BF16) {
        return false;
    }
    // Shader bindings: data_a is A_TYPE so it follows x's precision, while
    // data_b and data_c are hardcoded float, so the broadcast operands must
    // be F32 regardless of x's type.
    if (a->type     != GGML_TYPE_F32) return false;
    if (inv_b->type != GGML_TYPE_F32) return false;
    // Chain intermediates and output share x's precision (single A_TYPE / D_TYPE pipeline).
    if (mul0->type     != x->type) return false;
    if (sin_node->type != x->type) return false;
    if (sqr->type      != x->type) return false;
    if (mul1->type     != x->type) return false;
    if (add->type      != x->type) return false;
    if (!ggml_are_same_shape(a, inv_b)) {
        return false;
    }
    if (a->ne[0] != 1 || a->ne[1] != x->ne[1]) {
        return false;
    }
    // Dispatch is 2D over (ne0, ne1), so x and add must be 2D and a / inv_b
    // must collapse to [1, C, 1, 1]. Higher dims are not handled by the shader.
    if (x->ne[2]     != 1 || x->ne[3]     != 1) return false;
    if (add->ne[2]   != 1 || add->ne[3]   != 1) return false;
    if (a->ne[2]     != 1 || a->ne[3]     != 1) return false;
    if (inv_b->ne[2] != 1 || inv_b->ne[3] != 1) return false;
    // Shader uses idx = i0 + i1 * ne0 and reads data_b[i1] / data_c[i1],
    // so every operand must be contiguous.
    if (!ggml_is_contiguous(x) || !ggml_is_contiguous(add) ||
        !ggml_is_contiguous(a) || !ggml_is_contiguous(inv_b)) {
        return false;
    }
    return true;
}

// Check whether the tensors overlap in memory.
// Fusions can potentially overwrite src tensors in ways that are not prevented
// by ggml-alloc. If the fusion src is being applied in a way that's elementwise
// with the destination, then it's OK for them to overlap if they are exactly equal.
static bool ggml_vk_tensors_overlap(const ggml_tensor * a, const ggml_tensor * b, bool elementwise) {
    ggml_backend_vk_buffer_context * a_buf_ctx = (ggml_backend_vk_buffer_context *)a->buffer->context;
    vk_buffer a_buf = a_buf_ctx->dev_buffer;
    ggml_backend_vk_buffer_context * b_buf_ctx = (ggml_backend_vk_buffer_context *)b->buffer->context;
    vk_buffer b_buf = b_buf_ctx->dev_buffer;
    if (a_buf == b_buf) {
        auto a_base = vk_tensor_offset(a) + a->view_offs;
        auto a_size = ggml_nbytes(a);
        auto b_base = vk_tensor_offset(b) + b->view_offs;
        auto b_size = ggml_nbytes(b);

        if (elementwise && a_base == b_base && a_size == b_size) {
            return false;
        }

        if ((b_base <= a_base && a_base < b_base + b_size) ||
            (a_base <= b_base && b_base < a_base + a_size)) {
            return true;
        }
    }
    return false;
}

static bool ggml_vk_can_fuse_rms_norm_mul_rope(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph,
                                               int node_idx) {
    GGML_UNUSED(ctx);
    const ggml_tensor *rms = cgraph->nodes[node_idx + 0];
    const ggml_tensor *mul = cgraph->nodes[node_idx + 1];
    const ggml_tensor *rope = cgraph->nodes[node_idx + 2];

    const int mode = ((const int32_t *) rope->op_params)[2];

    // noncontig tensors aren't tested, and don't seem common in practice
    if (!ggml_is_contiguous(rms) ||
        !ggml_is_contiguous(mul) ||
        !ggml_is_contiguous(rope)) {
        return false;
    }

    // only norm/neox are handled in the shader
    if (mode != GGML_ROPE_TYPE_NEOX && mode != GGML_ROPE_TYPE_NORMAL) {
        return false;
    }

    // shared memory size for passing data from mul->rope
    if (mul->ne[0] > 1024) {
        return false;
    }

    // conditions for pipeline creation
    if (sizeof(vk_op_rms_norm_mul_rope_push_constants) > ctx->device->properties.limits.maxPushConstantsSize) {
        return false;
    }

    return true;
}

static uint32_t ggml_vk_fuse_multi_add(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {

    const ggml_tensor *first_node = cgraph->nodes[node_idx];
    if (first_node->op != GGML_OP_ADD) {
        return 0;
    }

    if (!ctx->device->multi_add) {
        return 0;
    }

    int32_t num_adds = 1;
    while (node_idx + num_adds < cgraph->n_nodes &&
           cgraph->nodes[node_idx + num_adds]->op == GGML_OP_ADD &&
           num_adds < MAX_FUSED_ADDS) {
        num_adds++;
    }

    // The shader currently requires same shapes (but different strides are allowed),
    // everything f32, and no misalignment
    for (int32_t i = 0; i < num_adds; ++i) {
        const ggml_tensor *next_node = cgraph->nodes[node_idx + i];
        if (!ggml_are_same_shape(first_node, next_node->src[0]) ||
            !ggml_are_same_shape(first_node, next_node->src[1]) ||
            next_node->type != GGML_TYPE_F32 ||
            next_node->src[0]->type != GGML_TYPE_F32 ||
            next_node->src[1]->type != GGML_TYPE_F32 ||
            get_misalign_bytes(ctx, next_node) ||
            get_misalign_bytes(ctx, next_node->src[0]) ||
            get_misalign_bytes(ctx, next_node->src[1])) {
            num_adds = i;
        }
    }

    // Verify we can fuse these
    ggml_op adds[MAX_FUSED_ADDS];
    for (int32_t i = 0; i < num_adds; ++i) {
        adds[i] = GGML_OP_ADD;
    }

    // decrease num_adds if they can't all be fused
    while (num_adds > 1 && !ggml_can_fuse(cgraph, node_idx, adds, num_adds)) {
        num_adds--;
    }

    // a single add is not "fused", so just return zero
    if (num_adds == 1) {
        return 0;
    }
    return num_adds;
}

// [TAG_HC_MIX_TAIL] multi_add_scale: the num_adds-long multi_add at node_idx (as returned by
// ggml_vk_fuse_multi_add) plus the SCALE that consumes its result - the qwen4exp build_hc_mix
// stream mean, ((s0 + s1) + s2) + s3 then * 1/hc. One dispatch writes the scaled sum.
//
// Bit-exactness: multi_add.comp keeps the f32 sum of the plain multi_add (same operands, same
// order); under MULTI_ADD_SCALE it applies scale.comp's expression sum * param1 + param2 to that
// f32 value instead of storing it - the same expression shape, hence the same fma-contraction
// decision as scale.comp (see scale_silu.comp for why that, not param2 == 0, is the guarantee).
// Only param2 == 0 is matched (what ggml_scale emits).
//
// Sites in qwen4exp: build_hc_mix's stream mean (2 per layer + the MTP block's mixes) AND
// build_qsa_pool's pooled-key mean (r CONT slices, ADD chain, SCALE(1/r); r = --qsa-ratio = 4 in
// prod; both the pooled-cache dirty-block write and the full recompute; only when the QSA path runs,
// i.e. at KV >= LLAMA_QSA_MIN_KV).
//
// Alias safety: ggml-alloc may hand the SCALE a destination that partially overlaps a stream
// view (the gated tensor is dead once the last ADD has run). The overlap veto in graph_compute
// would then undo the whole fusion, adds included; checking it here keeps the plain multi_add.
// *overlap is set when the pattern matched and only the alias check refused it (GGML_VK_FUSION_COUNT reports
// that as overlap:multi_add_scale, so the plain-multi_add fallback is visible).
static bool ggml_vk_can_fuse_multi_add_scale(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx,
                                             uint32_t num_adds, bool * overlap = nullptr) {
    if (!ctx->device->fuse_multi_add_scale || num_adds < 2 || num_adds > MAX_FUSED_ADDS) {
        return false;
    }
    const int scale_idx = node_idx + (int) num_adds;
    if (scale_idx >= cgraph->n_nodes) {
        return false;
    }

    ggml_op ops[MAX_FUSED_ADDS + 1];
    for (uint32_t k = 0; k < num_adds; ++k) {
        ops[k] = GGML_OP_ADD;
    }
    ops[num_adds] = GGML_OP_SCALE;
    // the adds' result has the scale as its only use, is not an output, and has its shape
    if (!ggml_can_fuse(cgraph, node_idx, ops, (int) num_adds + 1)) {
        return false;
    }

    const ggml_tensor * last_add = cgraph->nodes[scale_idx - 1];
    const ggml_tensor * scale    = cgraph->nodes[scale_idx];
    if (scale->src[0] != last_add || scale->type != GGML_TYPE_F32) {
        return false;
    }
    if (ggml_get_op_params_f32(scale, 1) != 0.0f) {
        return false;
    }
    if (get_misalign_bytes(ctx, scale)) {
        return false;
    }

    for (int k = 0; k <= (int) num_adds; ++k) {
        const ggml_tensor * node = cgraph->nodes[node_idx + k];
        for (uint32_t s = 0; s < GGML_MAX_SRC; ++s) {
            const ggml_tensor * src = node->src[s];
            if (!src || src->op == GGML_OP_NONE) {
                continue;
            }
            bool elided = false;
            for (int n = 0; n <= k; ++n) {
                elided = elided || cgraph->nodes[node_idx + n] == src;
            }
            if (!elided && ggml_vk_tensors_overlap(src, scale, true)) {
                if (overlap) {
                    *overlap = true;
                }
                return false;
            }
        }
    }
    return true;
}

// [TAG_HC_MIX_TAIL] SCALE + UNARY(SILU), the qwen4exp build_hc_mix silu(scale(w_down x, 1/hc)).
// scale_silu.comp evaluates scale.comp's expression and unary.comp's op_silu on the register
// value; the elided store rounded to f32 anyway. Matched only for f32, param2 == 0 and
// contiguous src / destination (scale.comp indexes linearly).
static bool ggml_vk_can_fuse_scale_silu(ggml_backend_vk_context * ctx, const struct ggml_cgraph * cgraph, int node_idx) {
    if (!ctx->device->fuse_scale_silu) {
        return false;
    }
    if (!ggml_vk_can_fuse(ctx, cgraph, node_idx, { GGML_OP_SCALE, GGML_OP_UNARY })) {
        return false;
    }

    const ggml_tensor * scale = cgraph->nodes[node_idx + 0];
    const ggml_tensor * silu  = cgraph->nodes[node_idx + 1];
    const ggml_tensor * x     = scale->src[0];

    if (ggml_get_unary_op(silu) != GGML_UNARY_OP_SILU || silu->src[0] != scale) {
        return false;
    }
    if (x->type != GGML_TYPE_F32 || scale->type != GGML_TYPE_F32 || silu->type != GGML_TYPE_F32) {
        return false;
    }
    if (ggml_get_op_params_f32(scale, 1) != 0.0f) {
        return false;
    }
    if (!ggml_are_same_shape(x, silu) || !ggml_is_contiguous(x) || !ggml_is_contiguous(silu)) {
        return false;
    }
    return true;
}

static int32_t find_first_set(uint32_t x) {
    int32_t ret = 0;
    if (!x) {
        return -1;
    }
    while (!(x & 1)) {
        x >>= 1;
        ret++;
    }
    return ret;
}

static ggml_status ggml_backend_vk_graph_compute(ggml_backend_t backend, ggml_cgraph * cgraph) {
    VK_LOG_DEBUG("ggml_backend_vk_graph_compute(" << cgraph->n_nodes << " nodes)");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;

    const bool prof = ggml_vk_sched_prof_enabled();

    int64_t prof_t_start_us  = 0; // entry
    int64_t prof_flush_us    = 0; // ggml_vk_flush_pending_host_reads: a fence wait when a UMA host read is pending
    int64_t prof_t_record_us = 0; // start of the node loop
    int64_t prof_wait_us     = 0; // fence waits inside this call (serialize_submissions only)
    if (prof) {
        prof_t_start_us = ggml_time_us();
        ctx->sched_prof_submit_us = 0;
    }

    // [TAG_ASYNC_READ_UMA] a pending direct host read owns ctx->compute_ctx; recording this graph
    // into it would strand or race the queued memcpy.
    ggml_vk_flush_pending_host_reads(ctx);

    if (prof) {
        prof_flush_us = ggml_time_us() - prof_t_start_us;
    }

    ctx->device->diag_cgraph = nullptr;
    ctx->device->diag_prev_start = -1;
    ctx->device->diag_prev_end = -1;

    if (vk_instance.debug_utils_support) {
        vk::DebugUtilsLabelEXT dul = {};
        dul.pLabelName = "ggml_backend_vk_graph_compute";
        dul.color = std::array<float,4>{1.0f, 1.0f, 1.0f, 1.0f};

        std::lock_guard<vk_queue_handle> guard(*ctx->device->compute_queue->handle);
        vk_instance.pfn_vkQueueBeginDebugUtilsLabelEXT(ctx->device->compute_queue->handle->queue, reinterpret_cast<VkDebugUtilsLabelEXT*>(&dul));
    }

    ctx->prealloc_size_add_rms_partials_offset = 0;
    ctx->do_add_rms_partials = false;
    ctx->do_add_rms_partials_offset_calculation = false;

    int last_node = cgraph->n_nodes - 1;

    // If the last op in the cgraph isn't backend GPU, the command buffer doesn't get closed properly
    while (last_node > 0 && (ggml_vk_is_empty(cgraph->nodes[last_node]) || ((cgraph->nodes[last_node]->flags & GGML_TENSOR_FLAG_COMPUTE) == 0))) {
        last_node -= 1;
    }

    // Reserve tensor context space for all nodes
    ctx->tensor_ctxs.resize(cgraph->n_nodes);

    bool first_node_in_batch = true; // true if next node will be first node in a batch
    int submit_node_idx = 0; // index to first node in a batch

    ggml_vk_submit_transfer_ctx(ctx);

    vk_context compute_ctx;
    if (vk_perf_logger_enabled) {
        // allocate/resize the query pool
        if (ctx->num_queries < cgraph->n_nodes + 1) {
            if (ctx->query_pool) {
                ctx->device->device.destroyQueryPool(ctx->query_pool);
            }
            vk::QueryPoolCreateInfo query_create_info;
            query_create_info.queryType = vk::QueryType::eTimestamp;
            query_create_info.queryCount = cgraph->n_nodes + 100;
            ctx->query_pool = ctx->device->device.createQueryPool(query_create_info);
            ctx->num_queries = query_create_info.queryCount;
            ctx->query_fusion_names.resize(ctx->num_queries);
            ctx->query_fusion_node_count.resize(ctx->num_queries);
            ctx->query_nodes.resize(ctx->num_queries);
            ctx->query_node_idx.resize(ctx->num_queries);
        }

        ctx->device->device.resetQueryPool(ctx->query_pool, 0, cgraph->n_nodes+1);
        std::fill(ctx->query_fusion_names.begin(), ctx->query_fusion_names.end(), nullptr);
        std::fill(ctx->query_fusion_node_count.begin(), ctx->query_fusion_node_count.end(), 0);
        std::fill(ctx->query_nodes.begin(), ctx->query_nodes.end(), nullptr);
        std::fill(ctx->query_node_idx.begin(), ctx->query_node_idx.end(), 0);

        GGML_ASSERT(ctx->compute_ctx.expired());
        compute_ctx = ggml_vk_get_compute_ctx(ctx);
        ctx->query_idx = 0;
        compute_ctx->s->buffer->buf.writeTimestamp(vk::PipelineStageFlagBits::eAllCommands, ctx->query_pool, ctx->query_idx++);
        ggml_vk_sync_buffers(ctx, compute_ctx);
    }

    ctx->prealloc_y_last_pipeline_used = nullptr;
    ctx->prealloc_y_last_tensor_used = nullptr;
    ctx->prealloc_y_last_decode_vector_staging = false;

    if (ctx->prealloc_size_add_rms_partials) {
        ggml_vk_preallocate_buffers(ctx, nullptr);
        compute_ctx = ggml_vk_get_compute_ctx(ctx);
        // initialize partial sums to zero.
        ggml_vk_buffer_memset_async(compute_ctx, ctx->prealloc_add_rms_partials, 0, 0, ctx->prealloc_size_add_rms_partials);
        ggml_vk_sync_buffers(ctx, compute_ctx);
    }

    // Submit after enough work has accumulated, to overlap CPU cmdbuffer generation with GPU execution.
    // Estimate the amount of compute work using flops, and submit every 200 GFLOP
    // (and scaled down based on total graph flops, so smaller models submit earlier).
    // Also submit at least every 100 nodes, in case there are workloads without heavy compute.
    uint32_t submitted_nodes = 0;
    uint32_t submit_count = 0;
    uint64_t batch_flops = 0;
    uint64_t total_flops = 0;
    uint64_t flops_cap = 200'000'000'000ULL;

    // On weaker AMD GPUs larger submissions can hit a driver timeout, submit more often to avoid this
    if (ctx->device->vendor_id == VK_VENDOR_ID_AMD && ctx->device->shader_core_count > 0) {
        if (ctx->device->architecture == AMD_GCN && ctx->device->shader_core_count < 32) {
            flops_cap = 500'000'000ULL * ctx->device->shader_core_count;
        } else if (ctx->device->architecture != AMD_GCN && ctx->device->shader_core_count < 24) {
            flops_cap = 2'000'000'000ULL * ctx->device->shader_core_count;
        }
    }
    // The submit threshold has to be sized from the work that is about to be recorded, not from
    // whatever ran last. ggml_backend_sched calls graph_compute once per *split*, so seeding it
    // from ctx->last_total_flops makes a big split inherit the flops of the split before it. In
    // qwen4exp the one-node CPU split (the PLE get_rows) sits between blk.0 and blk.1, so the
    // 47-layer Vulkan split is seeded from a ~1.25 GFLOP split: ~31 MFLOP, which even after the
    // three submit_after doublings stays far below a single MoE gate_up, and the flop rule - not
    // the max_nodes_per_submit rule - ends up firing every few nodes.
    //
    // Sum this graph's own flops up front instead. ggml_vk_get_node_flops is a couple of branches
    // and multiplies per node, so an extra pass over the node array is noise next to the command
    // recording it precedes, and the seed then never depends on a previous call. A split with no
    // flop-bearing ops seeds 0, which disables the flop rule for that split and leaves
    // max_nodes_per_submit as the only bound - the correct behaviour for a split that has no
    // matmuls to pace.
    //
    // This changes *when* command buffers are submitted, nothing about what they contain: the
    // node order, the recorded commands and every operand are identical, so results are bit-exact.
    uint64_t graph_total_flops = 0;
    if (!vk_flops_seed_legacy) {
        for (int i = 0; i < cgraph->n_nodes; i++) {
            graph_total_flops += ggml_vk_get_node_flops(cgraph->nodes[i]);
        }
    }
    uint64_t flops_per_submit = std::min(flops_cap, (vk_flops_seed_legacy ? ctx->last_total_flops : graph_total_flops) / 40u);
    const uint64_t flops_per_submit_seed = flops_per_submit;

    // GGML_VK_FUSION_COUNT tally for this graph (empty and untouched when the knob is off)
    const bool fusion_count = ggml_vk_fusion_count_enabled();
    std::map<std::string, int> fusion_counts;
    ctx->fusion_count_add_rms = 0;
    ctx->fusion_sig = vk_fnv1a_seed;
    ctx->fusion_count_disabled.clear();

    auto const submit_after = [&](int start, int end) {
        if (ctx->device->serialize_submissions) {
            int64_t prof_t_wait_us = 0;
            if (prof) {
                prof_t_wait_us = ggml_time_us();
            }
            try {
                auto res = ctx->device->device.waitForFences({ ctx->fence }, true, UINT64_MAX);
                if (res != vk::Result::eSuccess) {
                    GGML_LOG_ERROR("ggml_vulkan: waitForFences error during serialized submission\n");
                    throw vk::SystemError(vk::make_error_code(res), "ggml_vulkan: waitForFences during serialized submission");
                }
            } catch (vk::DeviceLostError &) {
                ggml_vk_print_device_fault_info(ctx->device);
                GGML_LOG_ERROR("ggml_vulkan: device lost on %s waiting for submission (nodes %d to %d):\n",
                        ctx->device->name.c_str(), start, end);
                ggml_vk_print_node_list(cgraph, start, end);
                throw;
            }
            ctx->device->device.resetFences({ ctx->fence });
            ctx->submit_pending = false;
            ctx->device->diag_cgraph = cgraph;
            ctx->device->diag_prev_start = start;
            ctx->device->diag_prev_end = end;
            if (prof) {
                prof_wait_us += ggml_time_us() - prof_t_wait_us;
            }
        }
        first_node_in_batch = true;
        submitted_nodes = 0;
        batch_flops = 0;
        if (submit_count < 3) {
            flops_per_submit *= 2;
        }
        submit_count++;
    };

    if (prof) {
        prof_t_record_us = ggml_time_us();
    }

    for (int i = 0; i < cgraph->n_nodes; i++) {
        if (first_node_in_batch) {
            submit_node_idx = i;
        }

        {
            auto node_flops = ggml_vk_get_node_flops(cgraph->nodes[i]);
            total_flops += node_flops;

            // Flush the current batch before recording a node that would push it over the flop threshold
            if (flops_per_submit != 0 && submitted_nodes > 0 && batch_flops + node_flops >= flops_per_submit) {
                vk_context flush_ctx = ggml_vk_get_compute_ctx(ctx);
                ggml_vk_ctx_end(flush_ctx);
                flush_ctx->exit_tensor_idx = -1;
                ctx->compute_ctx.reset();
                ggml_vk_compute_forward(ctx, cgraph, cgraph->nodes[submit_node_idx], submit_node_idx, false);
                submit_after(submit_node_idx, i - 1);
                submit_node_idx = i;
            }

            batch_flops += node_flops;
        }

        // op_srcs_fused_elementwise indicates whether an op's srcs all contribute to
        // the fused result in an elementwise-way. This affects whether the memory for
        // the src is allowed to overlap the memory for the destination.
        // The array is sized to handle the largest fusion (asserted later).
        bool op_srcs_fused_elementwise[13];

        ctx->fused_topk_moe_mode = TOPK_MOE_COUNT;
        ctx->fused_topk_moe_scale = false;
        ctx->fused_mul_sigmoid = false;
        ctx->fused_gdn_pre = false;
        ctx->fused_topk_qsa = false;
        ctx->fused_multi_add_scale = false;
        ctx->fused_scale_silu = false;
        ctx->fused_concat_ssm_conv = false;
        const char *fusion_string {};
        if (!ctx->device->disable_fusion) {
            uint32_t num_adds = ggml_vk_fuse_multi_add(ctx, cgraph, i);
            if (num_adds && !vk_fusion_veto(ctx, "multi_add")) {
                ctx->num_additional_fused_ops = num_adds - 1;
                fusion_string = "MULTI_ADD";
                std::fill_n(op_srcs_fused_elementwise, ctx->num_additional_fused_ops + 1, true);
                // [TAG_HC_MIX_TAIL] extend by the trailing SCALE; a veto leaves the plain multi_add
                bool mas_overlap = false;
                if (ggml_vk_can_fuse_multi_add_scale(ctx, cgraph, i, num_adds, &mas_overlap) &&
                    !vk_fusion_veto(ctx, "multi_add_scale")) {
                    ctx->num_additional_fused_ops = num_adds;
                    ctx->fused_multi_add_scale = true;
                    fusion_string = "MULTI_ADD_SCALE";
                    // the scale reads only the elided sum (its own src), elementwise
                    op_srcs_fused_elementwise[num_adds] = true;
                } else if (mas_overlap && fusion_count) {
                    ggml_vk_fusion_count_add(fusion_counts, "overlap:", "multi_add_scale");
                }
            } else if (ggml_vk_can_fuse(ctx, cgraph, i, { GGML_OP_MUL_MAT, GGML_OP_ADD, GGML_OP_ADD }) &&
                       !vk_fusion_veto(ctx, "mul_mat_add_add")) {
                ctx->num_additional_fused_ops = 2;
                fusion_string = "MUL_MAT_ADD_ADD";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
                op_srcs_fused_elementwise[2] = true;
            } else if (ggml_vk_can_fuse(ctx, cgraph, i, { GGML_OP_MUL_MAT, GGML_OP_ADD }) &&
                       !vk_fusion_veto(ctx, "mul_mat_add")) {
                ctx->num_additional_fused_ops = 1;
                fusion_string = "MUL_MAT_ADD";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
            } else if (ggml_vk_can_fuse(ctx, cgraph, i, { GGML_OP_MUL_MAT_ID, GGML_OP_ADD_ID, GGML_OP_MUL }) &&
                       !vk_fusion_veto(ctx, "mul_mat_id_add_id_mul")) {
                ctx->num_additional_fused_ops = 2;
                fusion_string = "MUL_MAT_ID_ADD_ID_MUL";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
                op_srcs_fused_elementwise[2] = true;
            } else if (ggml_vk_can_fuse(ctx, cgraph, i, { GGML_OP_MUL_MAT_ID, GGML_OP_ADD_ID }) &&
                       !vk_fusion_veto(ctx, "mul_mat_id_add_id")) {
                ctx->num_additional_fused_ops = 1;
                fusion_string = "MUL_MAT_ID_ADD_ID";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
            } else if (ggml_vk_can_fuse(ctx, cgraph, i, { GGML_OP_MUL_MAT_ID, GGML_OP_MUL }) &&
                       !vk_fusion_veto(ctx, "mul_mat_id_mul")) {
                ctx->num_additional_fused_ops = 1;
                fusion_string = "MUL_MAT_ID_MUL";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
            } else if (ggml_can_fuse_subgraph(cgraph, i, { GGML_OP_RMS_NORM, GGML_OP_MUL, GGML_OP_ROPE, GGML_OP_VIEW, GGML_OP_SET_ROWS }, { i + 4 }) &&
                       ggml_check_edges(cgraph, i, rms_norm_mul_rope_view_set_rows_edges) &&
                       ggml_vk_can_fuse_rms_norm_mul_rope(ctx, cgraph, i) &&
                       ggml_vk_can_fuse_rope_set_rows(ctx, cgraph, i + 2) &&
                       !vk_fusion_veto(ctx, "rms_norm_mul_rope_view_set_rows")) {
                ctx->num_additional_fused_ops = 4;
                fusion_string = "RMS_NORM_MUL_ROPE_VIEW_SET_ROWS";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = false;
                op_srcs_fused_elementwise[2] = false;
                op_srcs_fused_elementwise[3] = false;
                op_srcs_fused_elementwise[4] = false;
            } else if (ggml_vk_can_fuse(ctx, cgraph, i, { GGML_OP_RMS_NORM, GGML_OP_MUL, GGML_OP_ROPE })&&
                       ggml_vk_can_fuse_rms_norm_mul_rope(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "rms_norm_mul_rope")) {
                ctx->num_additional_fused_ops = 2;
                fusion_string = "RMS_NORM_MUL_ROPE";
                // rope is approximately elementwise - whole rows are done by a single workgroup and it's row-wise
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
                op_srcs_fused_elementwise[2] = true;
            } else if (ggml_vk_can_fuse(ctx, cgraph, i, { GGML_OP_RMS_NORM, GGML_OP_MUL }) &&
                       !vk_fusion_veto(ctx, "rms_norm_mul")) {
                ctx->num_additional_fused_ops = 1;
                fusion_string = "RMS_NORM_MUL";
                // rms_norm is not elementwise, but whole rows must be consumed and the scale factor computed before
                // they are overwritten, and one workgroup per row. So close enough.
                op_srcs_fused_elementwise[0] = true;
                op_srcs_fused_elementwise[1] = true;
            } else if (ggml_vk_can_fuse_concat_ssm_conv(ctx, cgraph, i, 2) &&
                       !vk_fusion_veto(ctx, "concat_ssm_conv_bias_silu")) {
                // [TAG_CONV_INPUT_SPLIT] the concat is never written; state / x are read with a window, not elementwise
                ctx->num_additional_fused_ops = 3;
                ctx->fused_concat_ssm_conv = true;
                fusion_string = "CONCAT_SSM_CONV_BIAS_SILU";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = false;
                op_srcs_fused_elementwise[2] = true;
                op_srcs_fused_elementwise[3] = true;
            } else if (ggml_vk_can_fuse_concat_ssm_conv(ctx, cgraph, i, 1) &&
                       !vk_fusion_veto(ctx, "concat_ssm_conv_silu")) {
                ctx->num_additional_fused_ops = 2;
                ctx->fused_concat_ssm_conv = true;
                fusion_string = "CONCAT_SSM_CONV_SILU";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = false;
                op_srcs_fused_elementwise[2] = true;
            } else if (ggml_vk_can_fuse_concat_ssm_conv(ctx, cgraph, i, 0) &&
                       !vk_fusion_veto(ctx, "concat_ssm_conv")) {
                ctx->num_additional_fused_ops = 1;
                ctx->fused_concat_ssm_conv = true;
                fusion_string = "CONCAT_SSM_CONV";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = false;
            } else if (ggml_vk_can_fuse_ssm_conv(ctx, cgraph, i, 2) &&
                       !vk_fusion_veto(ctx, "ssm_conv_bias_silu")) {
                ctx->num_additional_fused_ops = 2;
                fusion_string = "SSM_CONV_BIAS_SILU";
                // ssm_conv reads multiple input tokens per output, so it's not elementwise w.r.t. its srcs.
                // The downstream add and silu are elementwise on the conv output.
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
                op_srcs_fused_elementwise[2] = true;
            } else if (ggml_vk_can_fuse_ssm_conv(ctx, cgraph, i, 1) &&
                       !vk_fusion_veto(ctx, "ssm_conv_silu")) {
                ctx->num_additional_fused_ops = 1;
                fusion_string = "SSM_CONV_SILU";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = true;
            } else if (ggml_can_fuse_subgraph(cgraph, i, { GGML_OP_ROPE, GGML_OP_VIEW, GGML_OP_SET_ROWS }, { i + 2 }) &&
                       ggml_check_edges(cgraph, i, rope_view_set_rows_edges) &&
                       ggml_vk_can_fuse_rope_set_rows(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "rope_view_set_rows")) {
                ctx->num_additional_fused_ops = 2;
                fusion_string = "ROPE_VIEW_SET_ROWS";
                op_srcs_fused_elementwise[0] = false;
                op_srcs_fused_elementwise[1] = false;
                op_srcs_fused_elementwise[2] = false;
            } else if (ggml_vk_can_fuse_hc_combine(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "hc_combine")) {
                ctx->num_additional_fused_ops = 6;
                fusion_string = "HC_COMBINE";
                // elementwise=true: every thread reads residual[idx] into a register before
                // writing out[idx] with a data dependency on it, so an exact residual/out
                // alias is safe. The block and inject srcs have a different byte size than
                // the destination, so ggml_vk_tensors_overlap still rejects any overlap of
                // theirs (they are read with a broadcast, not elementwise).
                std::fill_n(op_srcs_fused_elementwise, 7, true);
            } else if (ggml_vk_can_fuse_snake(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "snake")) {
                ctx->num_additional_fused_ops = 4;
                fusion_string = "SNAKE";
                // elementwise=true: snake.comp is safe under exact aliasing because each
                // thread reads data_x[idx] into a register before writing data_d[idx]
                // with a data dependency on that register. The overlap check still
                // rejects partial overlaps (different base or size).
                std::fill_n(op_srcs_fused_elementwise, 5, true);
            } else if (ggml_vk_can_fuse_topk_qsa(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "topk_qsa")) {
                ctx->num_additional_fused_ops = topk_qsa_pattern.size() - 1;
                ctx->fused_topk_qsa = true;
                fusion_string = "TOPK_QSA";
                std::fill_n(op_srcs_fused_elementwise, ctx->num_additional_fused_ops + 1, false);
            } else if (ggml_can_fuse_subgraph(cgraph, i, topk_moe_early_softmax_norm, { i + 3, i + 9 }) &&
                       ggml_check_edges(cgraph, i, topk_moe_early_softmax_norm_edges) &&
                       ggml_vk_can_fuse_topk_moe(ctx, cgraph, i, TOPK_MOE_EARLY_SOFTMAX_NORM) &&
                       !vk_fusion_veto(ctx, "topk_moe_early_softmax_norm")) {
                ctx->num_additional_fused_ops = topk_moe_early_softmax_norm.size() - 1;
                // view of argsort writes to memory
                ctx->fused_ops_write_mask |= 1 << 3;
                ctx->fused_topk_moe_mode = TOPK_MOE_EARLY_SOFTMAX_NORM;
                fusion_string = "TOPK_MOE_EARLY_SOFTMAX_NORM";
                std::fill_n(op_srcs_fused_elementwise, ctx->num_additional_fused_ops + 1, false);
            } else if (ggml_can_fuse_subgraph(cgraph, i, topk_moe_sigmoid_norm_bias, { i + 4, i + 10 }) &&
                       ggml_check_edges(cgraph, i, topk_moe_sigmoid_norm_bias_edges) &&
                       ggml_vk_can_fuse_topk_moe(ctx, cgraph, i, TOPK_MOE_SIGMOID_NORM_BIAS) &&
                       !vk_fusion_veto(ctx, "topk_moe_sigmoid_norm_bias")) {
                ctx->num_additional_fused_ops = topk_moe_sigmoid_norm_bias.size() - 1;
                // view of argsort writes to memory
                ctx->fused_ops_write_mask |= 1 << 4;
                ctx->fused_topk_moe_mode = TOPK_MOE_SIGMOID_NORM_BIAS;
                fusion_string = "TOPK_MOE_SIGMOID_NORM_BIAS";
                std::fill_n(op_srcs_fused_elementwise, ctx->num_additional_fused_ops + 1, false);
            } else if (ggml_can_fuse_subgraph(cgraph, i, topk_moe_sqrt_softplus_norm_bias, { i + 5, i + 11 }) &&
                       ggml_check_edges(cgraph, i, topk_moe_sqrt_softplus_norm_bias_edges) &&
                       ggml_vk_can_fuse_topk_moe(ctx, cgraph, i, TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS) &&
                       !vk_fusion_veto(ctx, "topk_moe_sqrt_softplus_norm_bias")) {
                ctx->num_additional_fused_ops = topk_moe_sqrt_softplus_norm_bias.size() - 1;
                // view of argsort writes to memory
                ctx->fused_ops_write_mask |= 1 << 5;
                ctx->fused_topk_moe_mode = TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS;
                fusion_string = "TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS";
                std::fill_n(op_srcs_fused_elementwise, ctx->num_additional_fused_ops + 1, false);
            } else if (ggml_can_fuse_subgraph(cgraph, i, topk_moe_early_softmax, { i + 3, i + 4 }) &&
                       ggml_check_edges(cgraph, i, topk_moe_early_softmax_edges) &&
                       ggml_vk_can_fuse_topk_moe(ctx, cgraph, i, TOPK_MOE_EARLY_SOFTMAX) &&
                       !vk_fusion_veto(ctx, "topk_moe_early_softmax")) {
                ctx->num_additional_fused_ops = topk_moe_early_softmax.size() - 1;
                // view of argsort writes to memory
                ctx->fused_ops_write_mask |= 1 << 3;
                ctx->fused_topk_moe_mode = TOPK_MOE_EARLY_SOFTMAX;
                fusion_string = "TOPK_MOE_EARLY_SOFTMAX";
                std::fill_n(op_srcs_fused_elementwise, ctx->num_additional_fused_ops + 1, false);
            } else if (ggml_can_fuse_subgraph(cgraph, i, topk_moe_late_softmax, { i + 1, i + 5 }) &&
                       ggml_check_edges(cgraph, i, topk_moe_late_softmax_edges) &&
                       ggml_vk_can_fuse_topk_moe(ctx, cgraph, i, TOPK_MOE_LATE_SOFTMAX) &&
                       !vk_fusion_veto(ctx, "topk_moe_late_softmax")) {
                ctx->num_additional_fused_ops = topk_moe_late_softmax.size() - 1;
                // view of argsort writes to memory
                ctx->fused_ops_write_mask |= 1 << 1;
                ctx->fused_topk_moe_mode = TOPK_MOE_LATE_SOFTMAX;
                fusion_string = "TOPK_MOE_LATE_SOFTMAX";
                std::fill_n(op_srcs_fused_elementwise, ctx->num_additional_fused_ops + 1, false);
            } else if (ggml_vk_can_fuse_add_softplus_mul(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "add_softplus_mul")) {
                ctx->num_additional_fused_ops = 2;
                ctx->fused_gdn_pre = true;
                fusion_string = "ADD_SOFTPLUS_MUL";
                // elementwise=true: each thread reads alpha[idx] into a register before it
                // writes out[idx] with a data dependency on it, so an exact alias is safe.
                // ssm_dt / ssm_a have a different byte size than the destination, so
                // ggml_vk_tensors_overlap still rejects any overlap of theirs (they are read
                // with a broadcast, not elementwise).
                std::fill_n(op_srcs_fused_elementwise, 3, true);
            } else if (ggml_vk_can_fuse_scale_silu(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "scale_silu")) {
                ctx->num_additional_fused_ops = 1;
                ctx->fused_scale_silu = true;
                fusion_string = "SCALE_SILU";
                // each thread reads its own element of the scale's src into a register before it
                // writes the same element of the destination, so an exact alias is safe
                op_srcs_fused_elementwise[0] = true;
                op_srcs_fused_elementwise[1] = true;
            } else if (ggml_vk_can_fuse_sigmoid_mul(ctx, cgraph, i) &&
                       !vk_fusion_veto(ctx, "sigmoid_mul")) {
                ctx->num_additional_fused_ops = 1;
                ctx->fused_mul_sigmoid = true;
                fusion_string = "SIGMOID_MUL";
                // each thread reads its own elements of both srcs before writing its own
                // element of the destination, so an exact alias is safe
                op_srcs_fused_elementwise[0] = true;
                op_srcs_fused_elementwise[1] = true;
            }
            if (ctx->fused_topk_moe_mode != TOPK_MOE_COUNT) {
                // Look for an additional scale op to fuse - occurs in deepseek2 and nemotron3 nano.
                if ((ggml_can_fuse_subgraph(cgraph, i + ctx->num_additional_fused_ops - 1, { GGML_OP_DIV, GGML_OP_RESHAPE, GGML_OP_SCALE }, { i + ctx->num_additional_fused_ops + 1 }) ||
                     ggml_can_fuse_subgraph(cgraph, i + ctx->num_additional_fused_ops, { GGML_OP_GET_ROWS, GGML_OP_SCALE }, { i + ctx->num_additional_fused_ops + 1 })) &&
                    !vk_fusion_veto(ctx, "topk_moe_scale")) {
                    ctx->fused_topk_moe_scale = true;
                    ctx->num_additional_fused_ops++;
                    op_srcs_fused_elementwise[ctx->num_additional_fused_ops] = false;
                }
            }
        }
        GGML_ASSERT(ctx->num_additional_fused_ops < (int)(sizeof(op_srcs_fused_elementwise) / sizeof(op_srcs_fused_elementwise[0])));
        ctx->fused_ops_write_mask |= 1 << ctx->num_additional_fused_ops;

        // Check whether fusion would overwrite src operands while they're still in use.
        // If so, disable fusion.
        if (ctx->num_additional_fused_ops) {
            // There are up to two output nodes - topk_moe has two.
            uint32_t bits = ctx->fused_ops_write_mask & ~(1 << ctx->num_additional_fused_ops);
            ggml_tensor *output_nodes[2] {};
            output_nodes[0] = cgraph->nodes[i + ctx->num_additional_fused_ops];
            if (bits) {
                int output_idx = find_first_set(bits);
                GGML_ASSERT(bits == (1u << output_idx));
                output_nodes[1] = cgraph->nodes[i + output_idx];
            }

            bool need_disable = false;

            // topk_moe often overwrites the source, but for a given row all the src values are
            // loaded before anything is stored. If there's only one row, this is safe, so treat
            // this as a special case.
            bool is_topk_moe_single_row = ctx->fused_topk_moe_mode != TOPK_MOE_COUNT &&
                                          ggml_nrows(cgraph->nodes[i]->src[0]) == 1;

            if (!is_topk_moe_single_row) {
                for (int j = 0; j < 2; ++j) {
                    ggml_tensor *dst = output_nodes[j];
                    if (!dst) {
                        continue;
                    }
                    // Loop over all srcs of all nodes in the fusion. If the src overlaps
                    // the destination and the src is not an intermediate node that's being
                    // elided, then disable fusion.
                    for (int k = 0; k <= ctx->num_additional_fused_ops; ++k) {
                        for (uint32_t s = 0; s < GGML_MAX_SRC; ++s) {
                            ggml_tensor *src = cgraph->nodes[i + k]->src[s];
                            if (!src || src->op == GGML_OP_NONE) {
                                continue;
                            }
                            if (ggml_vk_tensors_overlap(src, dst, op_srcs_fused_elementwise[k])) {
                                // n <= k, not n < k: a src that IS one of the pattern's own nodes is an
                                // elided intermediate, and that includes the node being scanned itself.
                                // ggml_cast sets result->src[1] = result (for consistency with
                                // ggml_cpy_impl, whose src[1] is the copy's destination), so a pattern
                                // that elides a cast - topk_qsa's f32 mask cast is the only one in this
                                // backend - carries a src that points at an elided node the fused
                                // dispatch never binds. Without this the cast's freed block vetoes the
                                // whole layer whenever ggml-alloc drops the fused destination into it,
                                // which at the production shapes it does in every layer of every graph
                                // (width 2051 vs n_kv 2304 makes it the tightest fit).
                                bool found = false;
                                for (int n = 0; n <= k; ++n) {
                                    if (cgraph->nodes[i + n] == src) {
                                        found = true;
                                        break;
                                    }
                                }
                                if (!found) {
                                    // GGML_VK_FUSION_DIAG=1 names the (src, dst) pair that vetoes a
                                    // fusion; without it a fusion that silently stops firing (topk_moe
                                    // at n_tokens >= 2) is invisible in the perf log, which keeps
                                    // printing the fusion name for the first node anyway.
                                    if (vk_fusion_diag) {
                                        GGML_LOG_INFO("ggml_vulkan: fusion %s disabled at node %d: src %s (%s) overlaps dst %s (%s), elementwise=%d\n",
                                                      fusion_string ? fusion_string : "?", i, src->name, ggml_op_name(src->op),
                                                      dst->name, ggml_op_name(dst->op), (int) op_srcs_fused_elementwise[k]);
                                    }
                                    need_disable = true;
                                }
                            }
                        }
                    }
                }
            }
            if (need_disable) {
                ctx->num_additional_fused_ops = 0;
                ctx->fused_ops_write_mask = 1;
                ctx->fused_topk_moe_mode = TOPK_MOE_COUNT;
                ctx->fused_topk_moe_scale = false;
                ctx->fused_mul_sigmoid = false;
                ctx->fused_gdn_pre = false;
                ctx->fused_topk_qsa = false;
                ctx->fused_multi_add_scale = false;
                ctx->fused_scale_silu = false;
                ctx->fused_concat_ssm_conv = false;
            }
        }

        if (vk_fusion_list_enabled && cgraph->nodes[i]->op == GGML_OP_QSA_SCORE) {
            // [TAG_QSA_SCORE_EPILOGUE] one node, listed like a fusion so the fusion sets of two runs can be diffed
            ggml_vk_fusion_list_report("qsa_score_epilogue", cgraph, i, 1, cgraph->nodes[i]->src[3] ? "+bias" : nullptr);
        }
        if (vk_fusion_list_enabled && ctx->num_additional_fused_ops > 0 && fusion_string) {
            std::string name = fusion_string;
            for (char & c : name) {
                c = (char) tolower((unsigned char) c);
            }
            ggml_vk_fusion_list_report(name.c_str(), cgraph, i, ctx->num_additional_fused_ops + 1,
                                       ctx->fused_topk_moe_scale ? "+topk_moe_scale" : nullptr);
        }

        if (fusion_count && fusion_string) {
            // a match that the overlap veto undid has num_additional_fused_ops == 0 here
            ggml_vk_fusion_count_add(fusion_counts, ctx->num_additional_fused_ops > 0 ? "" : "vetoed:", fusion_string);
            if (ctx->num_additional_fused_ops > 0 && ctx->fused_topk_moe_scale) {
                ggml_vk_fusion_count_add(fusion_counts, "", "topk_moe_scale");
            }
        }

        if (fusion_count) {
            // [TAG_QSA_FUSED_SELECT] topk_qsa_op=<count>: QSA selections dispatched as the single
            // GGML_OP_QSA_TOP_K node rather than as the seven-node fusion. Not a fusion - it can
            // never be vetoed and never appears as vetoed:/disabled: - but the M2 gate counts
            // "12 selections per graph" out of this line, so with GGML_VK_QSA_FUSED_SELECT=1 the
            // 12 move from topk_qsa= to topk_qsa_op= and the total is unchanged.
            if (cgraph->nodes[i]->op == GGML_OP_QSA_TOP_K) {
                ggml_vk_fusion_count_add(fusion_counts, "", "topk_qsa_op");
                // [TAG_QSA_TOPK_NOKEYS] topk_qsa_nokeys=<count>: the QSA_TOP_K nodes that run without the key rows
                const ggml_tensor * qn = cgraph->nodes[i];
                if (ggml_vk_qsa_topk_nokeys(ctx->device, ggml_get_op_params_i32(qn, 0) == 1, ggml_get_op_params_i32(qn, 2) == 1)) {
                    ggml_vk_fusion_count_add(fusion_counts, "", "topk_qsa_nokeys");
                }
            }
            // [TAG_QSA_SCORE_EPILOGUE] qsa_score_epilogue=<count>: indexer scores dispatched as one GGML_OP_QSA_SCORE (the
            // score GEMM with ReLU + head sum (+ bias) in its store) instead of MUL_MAT[_ROWS] + RELU + CONT + ADD/MULTI_ADD
            // (+ bias ADD); qsa_score_epilogue_bias counts those that also folded the bias. Not a fusion pattern: one node.
            if (cgraph->nodes[i]->op == GGML_OP_QSA_SCORE) {
                ggml_vk_fusion_count_add(fusion_counts, "", "qsa_score_epilogue");
                if (cgraph->nodes[i]->src[3]) {
                    ggml_vk_fusion_count_add(fusion_counts, "", "qsa_score_epilogue_bias");
                }
                // [TAG_QSA_SCORE_KREUSE] qsa_score_kreuse=<count>: those dispatched on the kr twin (key tile major, the pooled
                // keys reused across the plane's N tiles); the dispatch's own plan, so the count is what ran. Not a fusion
                // pattern: one node.
                if (ggml_vk_qsa_score_plan(ctx, cgraph->nodes[i]).kr) {
                    ggml_vk_fusion_count_add(fusion_counts, "", "qsa_score_kreuse");
                }
            }

            // mmid_mul_nofuse:<reason>=count - why the expert-weight multiply stayed unfused at this
            // MUL_MAT_ID. The tally above cannot say: a pattern that never matched has no
            // fusion_string, so it is simply absent from the line.
            if (cgraph->nodes[i]->op == GGML_OP_MUL_MAT_ID) {
                const bool fused_mul = ctx->num_additional_fused_ops > 0 && fusion_string &&
                                       (strcmp(fusion_string, "MUL_MAT_ID_MUL") == 0 ||
                                        strcmp(fusion_string, "MUL_MAT_ID_ADD_ID_MUL") == 0);
                if (!fused_mul) {
                    const char * why = ggml_vk_mmid_mul_nofuse_reason(ctx, cgraph, i);
                    // every gate passed and it still did not fuse => the src/dst overlap veto undid it
                    ggml_vk_fusion_count_add(fusion_counts, "mmid_mul_nofuse:", why ? why : "veto");
                }
            }

            // Numerics signature, node half: the op, the fused pattern that will be dispatched for
            // it, and the misalignment ggml-alloc left on its operands (get_misalign_bytes is what
            // mmid_mul_ok and mm_add_ok gate on, and what the shaders fold into their offsets).
            // The dispatch half (pipeline name + workgroup counts) is added in
            // ggml_vk_dispatch_pipeline, below, from inside ggml_vk_build_graph.
            const ggml_tensor * node = cgraph->nodes[i];
            uint64_t h = ggml_vk_fnv1a_str(ctx->fusion_sig, ggml_op_name(node->op));
            h = ggml_vk_fnv1a_str(h, fusion_string ? fusion_string : "-");
            const uint32_t nfused = (uint32_t) ctx->num_additional_fused_ops;
            h = ggml_vk_fnv1a(h, &nfused, sizeof(nfused));
            for (int s = -1; s < GGML_MAX_SRC; ++s) {
                const ggml_tensor * t = s < 0 ? node : node->src[s];
                const uint32_t misalign = (t && t->buffer && ggml_backend_buffer_is_vk(t->buffer))
                                              ? get_misalign_bytes(ctx, t) : 0xffffffffu;
                h = ggml_vk_fnv1a(h, &misalign, sizeof(misalign));
            }
            ctx->fusion_sig = h;
        }

        // Signal the almost_ready fence when the graph is mostly complete (< 20% remaining)
        bool almost_ready = (cgraph->n_nodes - i) < cgraph->n_nodes / 5;
        bool submit = (submitted_nodes >= ctx->device->max_nodes_per_submit) ||
                      (flops_per_submit != 0 && batch_flops >= flops_per_submit) ||
                      (i + ctx->num_additional_fused_ops >= last_node) ||
                      (almost_ready && !ctx->almost_ready_fence_pending);

        bool enqueued = ggml_vk_build_graph(ctx, cgraph, i, cgraph->nodes[submit_node_idx], submit_node_idx, i + ctx->num_additional_fused_ops >= last_node, almost_ready, submit);

        if (vk_perf_logger_enabled && enqueued) {
            compute_ctx = ggml_vk_get_compute_ctx(ctx);
            if (!vk_perf_logger_concurrent) {
                // track a single node/fusion for the current query
                ctx->query_nodes[ctx->query_idx] = cgraph->nodes[i];
                ctx->query_fusion_names[ctx->query_idx] = fusion_string;
                compute_ctx->s->buffer->buf.writeTimestamp(vk::PipelineStageFlagBits::eAllCommands, ctx->query_pool, ctx->query_idx++);
                ggml_vk_sync_buffers(ctx, compute_ctx);
            } else {
                // track a fusion string and number of fused ops for the current node_idx
                ctx->query_fusion_names[i] = fusion_string;
                ctx->query_fusion_node_count[i] = ctx->num_additional_fused_ops;
            }
        }

        if (enqueued) {
            ++submitted_nodes;

#ifndef GGML_VULKAN_CHECK_RESULTS
            if (first_node_in_batch) {
                first_node_in_batch = false;
            }
#endif
        }

        if (submit && enqueued) {
            submit_after(submit_node_idx, i + (int)ctx->num_additional_fused_ops);
        }
        i += ctx->num_additional_fused_ops;
        ctx->num_additional_fused_ops = 0;
        ctx->fused_ops_write_mask = 0;
    }

    ctx->last_total_flops = total_flops;

    if (fusion_count) {
        if (ctx->fusion_count_add_rms) {
            fusion_counts["add_rms"] = ctx->fusion_count_add_rms;
        }
        // disabled:<name>=<count>: matches GGML_VK_DISABLE_FUSION_PATTERNS turned back into
        // unfused ops, so a bisect arm shows in the tally that the knob really acted
        for (const auto & kv : ctx->fusion_count_disabled) {
            fusion_counts["disabled:" + kv.first] = kv.second;
        }
        std::string line = "[vk-fusion-count] graph nodes=" + std::to_string(cgraph->n_nodes);
        for (const auto & kv : fusion_counts) {
            line += " " + kv.first + "=" + std::to_string(kv.second);
        }
        // add_rms is a per-graph running-offset decision, so it belongs in the signature too
        const uint64_t add_rms = (uint64_t) ctx->fusion_count_add_rms;
        char sig[32];
        snprintf(sig, sizeof(sig), " sig=0x%016llx",
                 (unsigned long long) ggml_vk_fnv1a(ctx->fusion_sig, &add_rms, sizeof(add_rms)));
        line += sig;
        fprintf(stderr, "%s\n", line.c_str());
    }

    if (prof) {
        const int64_t t_now_us = ggml_time_us();
        // pre    = everything before the node loop (flush, transfer-ctx submit, prealloc, perf-logger setup); flush is its fence-wait part
        // record = the node loop: ggml_vk_build_graph command recording, fusion detection and the submits it issues
        // submit_time = the ggml_vk_submit() (vkQueueSubmit) part of record; submits = how many this graph issued
        // wait   = fence waits inside this call - only non-zero with serialize_submissions; on the normal path
        //          graph_compute returns with the GPU still running (async) and the wait happens in
        //          ggml_backend_vk_synchronize, i.e. under "[sched-prof] sync" / the sched copy of the next CPU split
        fprintf(stderr, "[sched-prof]   vk graph nodes=%d pre=%.3fms flush=%.3fms record=%.3fms submits=%u submit_time=%.3fms wait=%.3fms total=%.3fms(async)\n",
                cgraph->n_nodes, (prof_t_record_us - prof_t_start_us)/1000.0, prof_flush_us/1000.0,
                (t_now_us - prof_t_record_us)/1000.0, submit_count, ctx->sched_prof_submit_us/1000.0,
                prof_wait_us/1000.0, (t_now_us - prof_t_start_us)/1000.0);
    }

    if (vk_submit_log_enabled || vk_perf_logger_enabled) {
        GGML_LOG_INFO("ggml_vulkan: graph_compute: %d nodes, %.3f GFLOP, %u submits, threshold seed %.3f GFLOP (%s)\n",
                      cgraph->n_nodes, (double) total_flops / 1e9, submit_count,
                      (double) flops_per_submit_seed / 1e9,
                      vk_flops_seed_legacy ? "legacy: previous split" : "this graph");
    }

    if (vk_perf_logger_enabled) {
        // End the command buffer and submit/wait
        GGML_ASSERT(!ctx->compute_ctx.expired());
        compute_ctx = ctx->compute_ctx.lock();
        ggml_vk_ctx_end(compute_ctx);

        ggml_vk_submit(compute_ctx, ctx->device->fence);
        VK_CHECK(ctx->device->device.waitForFences({ ctx->device->fence }, true, UINT64_MAX), "GGML_VULKAN_PERF waitForFences", ctx->device);
        ctx->device->device.resetFences({ ctx->device->fence });
        ctx->compute_ctx.reset();

        // Get the results and pass them to the logger
        std::vector<uint64_t> timestamps(cgraph->n_nodes + 1);
        VK_CHECK(ctx->device->device.getQueryPoolResults(ctx->query_pool, 0, ctx->query_idx, (cgraph->n_nodes + 1)*sizeof(uint64_t), timestamps.data(), sizeof(uint64_t), vk::QueryResultFlagBits::e64 | vk::QueryResultFlagBits::eWait), "get timestamp results", ctx->device);
        if (!vk_perf_logger_concurrent) {
            // Log each op separately
            for (int i = 1; i < ctx->query_idx; i++) {
                auto node = ctx->query_nodes[i];
                auto name = ctx->query_fusion_names[i];
                ctx->perf_logger->log_timing(node, name, uint64_t((timestamps[i] - timestamps[i-1]) * ctx->device->properties.limits.timestampPeriod));
            }
        } else {
            // Log each group of nodes
            int prev_node_idx = 0;
            for (int i = 1; i < ctx->query_idx; i++) {
                auto cur_node_idx = ctx->query_node_idx[i];
                std::vector<ggml_tensor *> nodes;
                std::vector<const char *> names;
                for (int node_idx = prev_node_idx; node_idx < cur_node_idx; ++node_idx) {
                    if (ggml_op_is_empty(cgraph->nodes[node_idx]->op)) {
                        continue;
                    }
                    nodes.push_back(cgraph->nodes[node_idx]);
                    names.push_back(ctx->query_fusion_names[node_idx]);
                    node_idx += ctx->query_fusion_node_count[node_idx];
                }
                prev_node_idx = cur_node_idx;
                ctx->perf_logger->log_timing(nodes, names, uint64_t((timestamps[i] - timestamps[i-1]) * ctx->device->properties.limits.timestampPeriod));
            }
        }
        ctx->perf_logger->print_timings();
    }

    if (!ctx->device->support_async) {
        ggml_vk_synchronize(ctx);
    }

    return GGML_STATUS_SUCCESS;

    UNUSED(backend);
}

// [TAG_QSA_SCRATCH] Record the largest fused-select scratch this graph would ask for.
// ggml_backend_sched calls graph_optimize on every split of every graph *including the reserve
// graphs it builds at context creation* (ggml-backend.cpp:1472, reached from both
// ggml_backend_sched_reserve and ggml_backend_sched_graph_compute), so by the time the first
// TOPK_QSA dispatch runs this is already the reserve span's extent. Presizing prealloc_x from it is
// what turns ~100 growths across a long prefill into one presize plus at most one later growth.
// Only walked when the knob is on; ggml_vk_can_fuse_topk_qsa rejects at the first op compare for
// every node that is not a QSA GET_ROWS, and its overlap veto (which needs allocated buffers, and
// therefore cannot decide during a reserve) can only make this an over-estimate of one graph, never
// an allocation on its own: nothing is allocated until a dispatch actually happens.
static void ggml_vk_qsa_scratch_hint(ggml_backend_vk_context * ctx, const struct ggml_cgraph * graph) {
    // Once prealloc_x already covers the largest extent seen, a further walk cannot change what gets
    // allocated - any bigger need is the dispatch's own scratch_size, which it applies itself - so
    // stop paying for it on every graph. The `> 0` keeps the very first (reserve) graph walking.
    if (ctx->prealloc_size_qsa_hint > 0 && ctx->prealloc_size_x >= ctx->prealloc_size_qsa_hint) {
        return;
    }
    // [TAG_QSA_FUSED_SELECT] GGML_VK_QSA_FUSED_SELECT=1 replaces the whole pattern with one
    // GGML_OP_QSA_TOP_K node, which needs the SAME scratch (ggml_vk_qsa_scratch_bytes is one
    // definition for both). Walked first and unconditionally: the op is not a fusion, so
    // GGML_VK_DISABLE_FUSION_PATTERNS must not turn its scratch hint off.
    // [TAG_QSA_SCRATCH] (M4.2b item 4) the hint is max(QSA fused-select scratch, FA q8_0->f16 K/V staging): the
    // staging shares prealloc_x (ggml_vk_flash_attn) and outgrows the QSA scratch at the chunked shapes (n_kv x 2 KiB
    // vs n_kv x chunk x 4 B per QSA layer). Taken from the graphs this hook sees, i.e. first from the reserve graphs,
    // whose n_kv is init_full()'s min(padded --kv-graph-span, cache size) - never the whole pool when a span is set
    // (with --kv-graph-span 0 the reserve IS the pool, as for the QSA term). Walked before the QSA forms below,
    // which return early.
    for (int i = 0; i < graph->n_nodes; ++i) {
        const ggml_tensor * node = graph->nodes[i];
        if (node->op != GGML_OP_FLASH_ATTN_EXT) {
            continue;
        }
        if (vk_qsa_scratch_presize_fa && ggml_vk_fa_use_dequant_kv(ctx, node->src[0], node->src[1], node->src[2], node->src[5])) {
            ctx->prealloc_size_qsa_hint = std::max(ctx->prealloc_size_qsa_hint,
                                                   ggml_vk_fa_dequant_staging_bytes(node->src[1], node->src[2]));
        }
    }
    bool saw_op = false;
    for (int i = 0; i < graph->n_nodes; ++i) {
        if (graph->nodes[i]->op != GGML_OP_QSA_TOP_K) {
            continue;
        }
        saw_op = true;
        ctx->prealloc_size_qsa_hint = std::max(ctx->prealloc_size_qsa_hint,
                                               ggml_vk_qsa_top_k_scratch_size(ctx->device, graph->nodes[i]));
    }
    if (saw_op) {
        // the two forms never coexist in one graph (the knob is read once per graph build), so a
        // graph carrying the op has no pattern to match and the walk below would only cost time
        return;
    }
    // GGML_VK_DISABLE_FUSION_PATTERNS=topk_qsa must not reserve scratch for a fusion that will not
    // run. Tested directly rather than through vk_fusion_veto(), which would also add this graph to
    // the GGML_VK_FUSION_COUNT tally the dispatcher owns.
    if (vk_fusion_patterns_disabled_any && ggml_vk_fusion_disabled_slow("topk_qsa")) {
        return;
    }
    const int n_ops = (int) topk_qsa_pattern.size();
    for (int i = 0; i + n_ops <= graph->n_nodes; ++i) {
        if (!ggml_vk_can_fuse_topk_qsa(ctx, graph, i)) {
            continue;
        }
        ctx->prealloc_size_qsa_hint = std::max(ctx->prealloc_size_qsa_hint,
                                               ggml_vk_topk_qsa_scratch_size(ctx->device, graph, i));
        i += n_ops - 1;
    }
}

// Sort the graph for improved parallelism.
static void ggml_vk_graph_optimize(ggml_backend_t backend, struct ggml_cgraph * graph)
{
    VK_LOG_DEBUG("ggml_vk_graph_optimize(" << graph->n_nodes << " nodes)");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;

    // [TAG_QSA_SCRATCH] deliberately above the early-out: the hint is about buffer sizing, not about
    // node order, and GGML_VK_DISABLE_GRAPH_OPTIMIZE must not silently change how much is allocated.
    if (vk_qsa_scratch_presize) {
        ggml_vk_qsa_scratch_hint(ctx, graph);
    }

    if (ctx->device->disable_graph_optimize) {
        return;
    }

    auto const &is_empty = [](const ggml_tensor * node) -> bool {
        return node->op == GGML_OP_NONE || node->op == GGML_OP_RESHAPE || node->op == GGML_OP_TRANSPOSE || node->op == GGML_OP_VIEW || node->op == GGML_OP_PERMUTE;
    };

    // Dependency test used before pulling node `dst` ahead of the not-yet-emitted node `src`. Besides direct
    // sources, storage hazards through views count: a node that reads a view of tensor T must not be hoisted
    // above a node that writes T through another view (e.g. build_rs: ggml_scale_inplace(view of the
    // recurrent cache row, 0) followed by ggml_get_rows(reshape(cache)) - the recurrent state of a reused cell
    // was read before it was zeroed), and a node that writes T must not be hoisted above a node still reading
    // a view of T. Same rule as upstream ggml-vulkan (is_src_of with base()).
    auto const &is_src_of = [&is_empty](const ggml_tensor *dst, const ggml_tensor *src) -> bool {
        auto const &base = [](const ggml_tensor * tensor) {
            return tensor->view_src ? tensor->view_src : tensor;
        };
        const ggml_tensor * dst_mut = ggml_vk_mutated_src(dst);
        const ggml_tensor * src_mut = ggml_vk_mutated_src(src);
        for (uint32_t s = 0; s < GGML_MAX_SRC; ++s) {
            if (dst->src[s] == src) {
                return true;
            }
            if (is_empty(dst) || is_empty(src)) {
                continue;
            }
            // A source view of dst may read storage written through a different view by src.
            if (dst->src[s] && (base(dst->src[s]) == base(src) ||
                                (src_mut && base(dst->src[s]) == base(src_mut)))) {
                return true;
            }
            // Moving dst forward may overwrite storage still read through a view by src.
            if (src->src[s] && (base(dst) == base(src->src[s]) ||
                                (dst_mut && base(dst_mut) == base(src->src[s])))) {
                return true;
            }
        }
        // implicit dependency if they view the same tensor
        if (base(dst) == base(src)) {
            return true;
        }
        if (src_mut && base(dst) == base(src_mut)) {
            return true;
        }
        if (dst_mut && (base(dst_mut) == base(src) || (src_mut && base(dst_mut) == base(src_mut)))) {
            return true;
        }
        return false;
    };

    std::vector<ggml_tensor *> new_order;
    std::vector<bool> used(graph->n_nodes, false);
    std::set<ggml_tensor *> used_node_set;

    int first_unused = 0;
    while (first_unused < graph->n_nodes) {
        std::vector<int> current_set;

        // Check for fusion patterns and avoid reordering them
        auto const &match_pattern = [&](const std::initializer_list<ggml_op> &pattern, int start) -> bool {
            if (start + (int)pattern.size() <= graph->n_nodes) {
                bool is_pattern = true;
                for (size_t j = 0; j < pattern.size(); ++j) {
                    if (graph->nodes[start + j]->op != pattern.begin()[j] || used[start + j]) {
                        is_pattern = false;
                    }
                }
                return is_pattern;
            }
            return false;
        };

        // True if node `j` is part of an occurrence of `pattern` that starts at or before j.
        // match_pattern alone only protects a pattern's first node: a node in the middle of a
        // pattern that does not depend on the pattern's first node (hc_combine's SCALE branch)
        // would otherwise be hoisted out of the chain by the lookahead below.
        auto const &inside_pattern = [&](const std::initializer_list<ggml_op> &pattern, int j) -> bool {
            for (int k = 0; k < (int)pattern.size(); ++k) {
                if (j - k >= 0 && match_pattern(pattern, j - k)) {
                    return true;
                }
            }
            return false;
        };

        // [TAG_CONV_INPUT_SPLIT] the op sequence AND the edges, so no unrelated CONCAT/SSM_CONV/UNARY run is caught
        auto const &is_concat_conv_silu = [&](int start) -> bool {
            if (ctx->device->disable_fusion || !ctx->device->fuse_concat_ssm_conv || !match_pattern(concat_conv_silu_pattern, start)) {
                return false;
            }
            const ggml_tensor * concat = graph->nodes[start];
            const ggml_tensor * conv   = graph->nodes[start + 1];
            const ggml_tensor * silu   = graph->nodes[start + 2];
            // the fusable (prefill) shape only: the conv is the concat's single use. In decode / short-verify graphs
            // the history tails still view the concat, the fusion cannot fire, and the v59 order is kept.
            return conv->src[0] == concat && silu->src[0] == conv && ggml_get_unary_op(silu) == GGML_UNARY_OP_SILU &&
                   ggml_node_get_use_count(graph, start) == 1;
        };

        // [TAG_CONV_INPUT_SPLIT] B4 fix round 2: a node reading the x of a not-yet-emitted fusable CONCAT -> SSM_CONV -> SILU
        // (the history tails, expanded after the conv by the model) must not be hoisted above it: ggml-alloc frees x after
        // its last consumer in this order, so a tail placed before the conv lets the conv's output take x's block, and the
        // overlap veto then undoes concat_ssm_conv (and the hoist perturbs the rest of the set, see the B4 fix 2 report).
        auto const &reads_pending_conv_x = [&](int j) -> bool {
            const ggml_tensor * node = graph->nodes[j];
            for (int c = first_unused; c < j; ++c) {
                if (used[c] || graph->nodes[c]->op != GGML_OP_CONCAT || !is_concat_conv_silu(c)) {
                    continue;
                }
                const ggml_tensor * x  = graph->nodes[c]->src[1];
                const ggml_tensor * xb = x->view_src ? x->view_src : x;
                for (uint32_t s = 0; s < GGML_MAX_SRC; ++s) {
                    const ggml_tensor * src = node->src[s];
                    if (src && (src->view_src ? src->view_src : src) == xb) {
                        return true;
                    }
                }
            }
            return false;
        };

        auto const &keep_pattern = [&](const std::initializer_list<ggml_op> &pattern) -> bool {
            if (match_pattern(pattern, first_unused)) {
                for (size_t j = 0; j < pattern.size(); ++j) {
                    new_order.push_back(graph->nodes[first_unused + j]);
                    used_node_set.insert(graph->nodes[first_unused + j]);
                    used[first_unused + j] = true;
                }
                while (first_unused < graph->n_nodes && used[first_unused]) {
                    first_unused++;
                }
                return true;
            }
            return false;
        };

        if (keep_pattern(topk_moe_early_softmax_norm)) {
            continue;
        }
        if (keep_pattern(topk_moe_sigmoid_norm_bias)) {
            continue;
        }
        if (keep_pattern(topk_moe_sqrt_softplus_norm_bias)) {
            continue;
        }
        if (keep_pattern(topk_moe_early_softmax)) {
            continue;
        }
        if (keep_pattern(topk_moe_late_softmax)) {
            continue;
        }
        if (keep_pattern(hc_combine_pattern)) {
            continue;
        }
        if (keep_pattern(snake_pattern)) {
            continue;
        }
        if (keep_pattern(topk_qsa_pattern)) {
            continue;
        }
        // [TAG_CONV_INPUT_SPLIT] CONCAT -> SSM_CONV(concat) -> SILU stays one consecutive run when it reaches the
        // front, and its CONCAT is never hoisted into an earlier set (the guard below), so concat_ssm_conv_silu
        // can match. Gated by GGML_VK_FUSE_CONCAT_SSM_CONV (=0: the v59 order).
        if (is_concat_conv_silu(first_unused) && keep_pattern(concat_conv_silu_pattern)) {
            continue;
        }

        // First, grab the next unused node.
        current_set.push_back(first_unused);

        // Loop through the next N nodes. Grab any that don't depend on other nodes that
        // haven't already been run. Nodes that have already been run have used[i] set
        // to true. Allow nodes that depend on the previous node if it's a fusion pattern
        // that we support (e.g. RMS_NORM + MUL).
        // This first pass only grabs "real" (non-view nodes). Second pass grabs view nodes.
        // The goal is to not interleave real and view nodes in a way that breaks fusion.
        //
        // GGML_VK_OPT_WINDOW sets how far ahead we look. Widening it cannot make the reordering
        // less safe, because the window only bounds which candidate `j` is *considered*: every
        // candidate still has to clear the same two gates, and both scale with the window rather
        // than with the constant.
        //   1. Hazards. For a candidate j the loop below tests is_src_of(nodes[j], nodes[c]) for
        //      *every* not-yet-emitted c in [first_unused, j), so the number of hazard tests grows
        //      with the distance, never leaving a gap. Nodes below first_unused are all emitted
        //      (the while loop at the bottom only advances over used[] entries), and the graph is
        //      topologically ordered, so every unemitted predecessor of j - and, via is_src_of's
        //      base()/ggml_vk_mutated_src() checks, every writer or reader that aliases the same
        //      storage through a view (patch 0012's hazard) - is inside that scanned interval.
        //      A wider window therefore adds candidates, not unchecked ones.
        //   2. Fusion patterns. keep_pattern() runs at first_unused only and is untouched. The
        //      per-candidate match_pattern()/inside_pattern(hc_combine_pattern, j) guards below are
        //      evaluated for each j in the window, so a node that a wider window newly reaches is
        //      still refused if it starts or sits inside a protected pattern. The RMS_NORM+MUL,
        //      MUL_MAT+ADD, ... carve-outs are all conditioned on j == c+1, which no window size
        //      changes.
        // Reordering independent nodes changes no operand of any op. That is not by itself a proof of
        // bit identity across window sizes: fusion in this backend is chosen from *adjacency* in the
        // final order (ggml_can_fuse / ggml_vk_can_fuse) and a fused pair can use a different
        // reduction than the two ops apart - ADD+RMS_NORM accumulates partial sums of squares in the
        // ADD, standalone RMS_NORM reduces over the whole row - so a window that newly makes two
        // nodes adjacent can change the floating-point summation order. The carve-outs below keep an
        // already-adjacent pattern together; they do not stop a wider window from creating one. Treat
        // "same results" as an expectation to verify per window value, not as an invariant.
        const int NUM_TO_CHECK = vk_graph_opt_window;
        // first_unused < n_nodes here (the enclosing while), so n_nodes - first_unused >= 1 and this
        // cannot overflow the way first_unused + NUM_TO_CHECK can once the window is settable.
        const int window_end = first_unused + std::min(NUM_TO_CHECK, graph->n_nodes - first_unused);
        for (int j = first_unused+1; j < window_end; ++j) {
            if (used[j]) {
                continue;
            }
            if (is_empty(graph->nodes[j])) {
                continue;
            }
            // Protect every interior QSA node (not just the start), like hc_combine: the mask
            // branch is independent, so it gets pulled out and breaks keep_pattern otherwise.
            if (match_pattern(topk_moe_early_softmax_norm, j) ||
                match_pattern(topk_moe_sigmoid_norm_bias, j) ||
                match_pattern(topk_moe_sqrt_softplus_norm_bias, j) ||
                match_pattern(topk_moe_early_softmax, j) ||
                match_pattern(topk_moe_late_softmax, j) ||
                match_pattern(snake_pattern, j) ||
                inside_pattern(hc_combine_pattern, j) ||
                inside_pattern(topk_qsa_pattern, j) ||
                is_concat_conv_silu(j) ||
                reads_pending_conv_x(j)) {
                continue;
            }
            bool ok = true;
            for (int c = first_unused; c < j; ++c) {
                if (!used[c] &&
                    is_src_of(graph->nodes[j], graph->nodes[c]) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_RMS_NORM && graph->nodes[j]->op == GGML_OP_MUL) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_MUL_MAT && graph->nodes[j]->op == GGML_OP_ADD) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_MUL_MAT_ID && graph->nodes[j]->op == GGML_OP_ADD_ID) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_MUL_MAT_ID && graph->nodes[j]->op == GGML_OP_MUL) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_ADD && graph->nodes[j]->op == GGML_OP_ADD) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_SSM_CONV && graph->nodes[j]->op == GGML_OP_ADD) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_SSM_CONV && graph->nodes[j]->op == GGML_OP_UNARY) &&
                    !(j == c+1 && c == current_set.back() && graph->nodes[c]->op == GGML_OP_UNARY && graph->nodes[j]->op == GGML_OP_MUL) &&
                    // ADD -> UNARY(SOFTPLUS) opens the GDN decay pre-chain (ADD_SOFTPLUS_MUL);
                    // the UNARY -> MUL carve-out above closes it. Without this the SOFTPLUS is
                    // pushed to a later set and any independent node pulled in behind the ADD
                    // lands between them, so the triple is no longer adjacent and the fusion
                    // never fires. Narrowed to SOFTPLUS on purpose: it is the only unary in the
                    // decode graph that follows an ADD it consumes, and the topk_moe chain that
                    // also uses SOFTPLUS is protected by its own keep_pattern above.
                    !(j == c+1 && c == current_set.back() &&
                      !ctx->device->disable_fusion && ctx->device->fuse_gdn_pre &&
                      graph->nodes[c]->op == GGML_OP_ADD && graph->nodes[j]->op == GGML_OP_UNARY &&
                      ggml_get_unary_op(graph->nodes[j]) == GGML_UNARY_OP_SOFTPLUS) &&
                    // The MUL of a UNARY+MUL pair usually also consumes an earlier node of the
                    // same set (the RMS_NORM+MUL or the reshape that produced its other operand).
                    // That node is emitted before j either way, so it must not veto the pair.
                    !(j > 0 && graph->nodes[j]->op == GGML_OP_MUL &&
                      graph->nodes[j-1]->op == GGML_OP_UNARY && current_set.back() == j-1 &&
                      std::find(current_set.begin(), current_set.end(), c) != current_set.end())) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                current_set.push_back(j);

                int rope_idx = j;

                // When we've found RMS_NORM + MUL, try to find a ROPE that uses it
                if (j > 0 &&
                    graph->nodes[j]->op == GGML_OP_MUL &&
                    graph->nodes[j-1]->op == GGML_OP_RMS_NORM) {
                    for (int k = j + 1; k < std::min(j + 15, graph->n_nodes); ++k) {
                        if (graph->nodes[k]->op == GGML_OP_ROPE &&
                            graph->nodes[k]->src[0] == graph->nodes[j] &&
                            // Check that other srcs are already valid
                            graph->nodes[k]->src[1]->op == GGML_OP_NONE &&
                            (graph->nodes[k]->src[2] == nullptr || graph->nodes[k]->src[2]->op == GGML_OP_NONE)) {
                            rope_idx = k;
                            current_set.push_back(rope_idx);
                            used[rope_idx] = true;
                            break;
                        }
                    }
                }
                // Look for ROPE + VIEW + SET_ROWS and make them consecutive
                if (graph->nodes[rope_idx]->op == GGML_OP_ROPE) {
                    int view_idx = -1;
                    int set_rows_idx = -1;
                    for (int k = rope_idx+1; k < std::min(rope_idx + 10, graph->n_nodes); ++k) {
                        if (view_idx == -1 &&
                            graph->nodes[k]->op == GGML_OP_VIEW &&
                            graph->nodes[k]->src[0] == graph->nodes[rope_idx]) {
                            view_idx = k;
                            continue;
                        }
                        if (view_idx != -1 &&
                            set_rows_idx == -1 &&
                            graph->nodes[k]->op == GGML_OP_SET_ROWS &&
                            graph->nodes[k]->src[0] == graph->nodes[view_idx]) {
                            set_rows_idx = k;
                            break;
                        }
                    }
                    if (set_rows_idx != -1) {
                        current_set.push_back(view_idx);
                        current_set.push_back(set_rows_idx);
                        used[view_idx] = true;
                        used[set_rows_idx] = true;
                    }
                }
                // Look for MUL_MAT_ID + ADD_ID + MUL
                if (j > 0 &&
                    graph->nodes[j]->op == GGML_OP_ADD_ID &&
                    graph->nodes[j-1]->op == GGML_OP_MUL_MAT_ID) {
                    for (int k = j + 1; k < std::min(j + 15, graph->n_nodes); ++k) {
                        if (graph->nodes[k]->op == GGML_OP_MUL &&
                            graph->nodes[k]->src[0] == graph->nodes[j] &&
                            // src1 must either be weights or already processed
                            (graph->nodes[k]->src[1]->op == GGML_OP_NONE || used_node_set.find(graph->nodes[k]->src[1]) != used_node_set.end())) {
                            current_set.push_back(k);
                            used[k] = true;
                            break;
                        }
                    }
                }
                // Look for MUL_MAT + ADD + ADD
                if (j > 0 &&
                    graph->nodes[j]->op == GGML_OP_ADD &&
                    graph->nodes[j-1]->op == GGML_OP_MUL_MAT) {
                    for (int k = j + 1; k < std::min(j + 15, graph->n_nodes); ++k) {
                        if (graph->nodes[k]->op == GGML_OP_ADD &&
                            graph->nodes[k]->src[0] == graph->nodes[j] &&
                            // src1 must either be weights or already processed
                            (graph->nodes[k]->src[1]->op == GGML_OP_NONE || used_node_set.find(graph->nodes[k]->src[1]) != used_node_set.end())) {
                            current_set.push_back(k);
                            used[k] = true;
                            break;
                        }
                    }
                }
                // SSM_CONV + ADD + UNARY: pull the consuming UNARY forward
                if (j > 0 &&
                    graph->nodes[j]->op == GGML_OP_ADD &&
                    graph->nodes[j-1]->op == GGML_OP_SSM_CONV) {
                    for (int k = j + 1; k < std::min(j + 15, graph->n_nodes); ++k) {
                        if (graph->nodes[k]->op == GGML_OP_UNARY &&
                            graph->nodes[k]->src[0] == graph->nodes[j]) {
                            current_set.push_back(k);
                            used[k] = true;
                            break;
                        }
                    }
                }
            }
        }
        // Second pass grabs view nodes.
        // Skip this if it would break a fusion optimization (don't split up add->rms_norm or add->add).
        if (graph->nodes[current_set.back()]->op != GGML_OP_ADD) {
            for (int j = first_unused+1; j < window_end; ++j) {
                if (used[j]) {
                    continue;
                }
                if (!is_empty(graph->nodes[j])) {
                    continue;
                }
                bool ok = true;
                for (int c = first_unused; c < j; ++c) {
                    bool c_in_current_set = std::find(current_set.begin(), current_set.end(), c) != current_set.end();
                    // skip views whose srcs haven't been processed.
                    if (!used[c] &&
                        is_src_of(graph->nodes[j], graph->nodes[c]) &&
                        !c_in_current_set) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    current_set.push_back(j);
                }
            }
        }

        // Push the current set into new_order
        for (auto c : current_set) {
            new_order.push_back(graph->nodes[c]);
            used_node_set.insert(graph->nodes[c]);
            used[c] = true;
        }
        while (first_unused < graph->n_nodes && used[first_unused]) {
            first_unused++;
        }
    }
    // Replace the graph with the new order.
    for (int i = 0; i < graph->n_nodes; ++i) {
        graph->nodes[i] = new_order[i];
    }
}

static void ggml_backend_vk_event_record(ggml_backend_t backend, ggml_backend_event_t event) {
    VK_LOG_DEBUG("ggml_backend_vk_event_record(backend=" << backend << ", event=" << event << ")");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;
    vk_event *vkev = (vk_event *)event->context;

    // [TAG_ASYNC_READ_UMA] this is the third path that ends, submits and then drops
    // ctx->compute_ctx (graph compute and the async set/copy entry points are the other two).
    // A pending direct host read owns that context: the ggml_vk_ctx_end + ggml_vk_submit +
    // ctx->compute_ctx.reset() below would strand its out_memcpys in a context
    // ggml_vk_synchronize can no longer reach - do_transfer is false once compute_ctx has
    // expired - while the synchronize still clears ctx->pending_host_read.  So
    // get_async(A); event_record(e); event_synchronize(e); backend_synchronize() would return
    // with A's destination never written.  Fence the reads off first; in the ordinary
    // graph_compute -> get_async... -> synchronize order nothing is pending and this is free.
    ggml_vk_flush_pending_host_reads(ctx);

    ggml_vk_submit_transfer_ctx(ctx);

    vk_context compute_ctx = ggml_vk_get_compute_ctx(ctx);
    auto* cmd_buf = compute_ctx->s->buffer; // retrieve pointer before it gets reset

    if (vkev->has_event) {
        // Move existing event into submitted
        vkev->events_submitted.push_back(vkev->event);
    }

    // Grab the next event and record it, create one if necessary
    if (vkev->events_free.empty()) {
        vkev->event = ctx->device->device.createEvent({});
    } else {
        vkev->event = vkev->events_free.back();
        vkev->events_free.pop_back();
    }

    vkev->has_event = true;

    ggml_vk_set_event(compute_ctx, vkev->event);

    vkev->tl_semaphore.value++;
    compute_ctx->s->signal_semaphores.push_back(vkev->tl_semaphore);
    ggml_vk_ctx_end(compute_ctx);

    ggml_vk_submit(compute_ctx, {});
    ctx->submit_pending = true;
    vkev->cmd_buffer = cmd_buf;
    vkev->cmd_buffer_use_counter = cmd_buf->use_counter;
    ctx->compute_ctx.reset();
}

static void ggml_backend_vk_event_wait(ggml_backend_t backend, ggml_backend_event_t event) {
    VK_LOG_DEBUG("ggml_backend_vk_event_wait(backend=" << backend << ", event=" << event << ")");
    ggml_backend_vk_context * ctx = (ggml_backend_vk_context *)backend->context;
    vk_event *vkev = (vk_event *)event->context;

    vk_context compute_ctx = ggml_vk_get_compute_ctx(ctx);

    if (vkev->has_event) {
        // Wait for latest event
        ggml_vk_wait_events(compute_ctx, { vkev->event });

        if (ctx->device->async_use_transfer_queue) {
            vk_context transfer_ctx = ggml_vk_get_transfer_ctx(ctx);
            transfer_ctx->s->wait_semaphores.push_back(vkev->tl_semaphore);
        }
    }
}

